package main

import (
	"fmt"
	"os"

	tea "charm.land/bubbletea/v2"
	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/core"
	"github.com/sapirrior/delta/internal/tui"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed loading configuration: %v\n", err)
		os.Exit(1)
	}

	cwd, err := os.Getwd()
	if err != nil {
		cwd = "."
	}

	engine, err := core.NewEngine(cfg, cwd)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed initializing Delta core engine: %v\n", err)
		os.Exit(1)
	}

	model, err := tui.NewAppModel(engine, cwd)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed initializing Delta TUI: %v\n", err)
		os.Exit(1)
	}

	p := tea.NewProgram(model)
	if _, err := p.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "error running Delta: %v\n", err)
		os.Exit(1)
	}
}

package agent

import (
	"encoding/json"
	"fmt"
	"sync"

	"github.com/sapirrior/delta/internal/constants"
	"github.com/zendev-sh/goai"
)

// ConfirmationBridge provides thread-safe synchronous confirmation requests
// from the GoAI tool loop goroutine to the TUI.
type ConfirmationBridge interface {
	RequestConfirmation(toolName, toolCallID string, input json.RawMessage) bool
}

// LoopDetector tracks tool signatures in a ring buffer to catch repetition loops.
// Invariant (AGENTS.md):
//   - Repetition detection: a ring buffer of the last 3 (ToolName, Input) signatures.
//     3 identical consecutive signatures aborts the turn with a clear message.
type LoopDetector struct {
	mu         sync.Mutex
	signatures []string
}

func NewLoopDetector() *LoopDetector {
	return &LoopDetector{
		signatures: make([]string, 0, constants.MaxToolSignatures),
	}
}

func (ld *LoopDetector) CheckAndRecord(toolName string, input json.RawMessage) bool {
	ld.mu.Lock()
	defer ld.mu.Unlock()

	sig := fmt.Sprintf("%s:%s", toolName, string(input))

	// Check if the last 2 recorded signatures are identical to this one (totaling RepetitionLimit consecutive)
	n := len(ld.signatures)
	limit := constants.RepetitionLimit
	if n >= limit-1 {
		allMatch := true
		for i := 1; i < limit; i++ {
			if ld.signatures[n-i] != sig {
				allMatch = false
				break
			}
		}
		if allMatch {
			return true // Loop detected!
		}
	}

	ld.signatures = append(ld.signatures, sig)
	if len(ld.signatures) > constants.MaxToolSignatures {
		ld.signatures = ld.signatures[1:]
	}
	return false
}

// Reset clears recorded signatures for a new turn.
func (ld *LoopDetector) Reset() {
	ld.mu.Lock()
	defer ld.mu.Unlock()
	ld.signatures = ld.signatures[:0]
}

// HookHandler bundles the GoAI hooks for tool confirmation gate and loop detection.
type HookHandler struct {
	bridge   ConfirmationBridge
	detector *LoopDetector
}

func NewHookHandler(bridge ConfirmationBridge) *HookHandler {
	return &HookHandler{
		bridge:   bridge,
		detector: NewLoopDetector(),
	}
}

// BuildBeforeToolExecuteHook creates the OnBeforeToolExecute callback.
// Invariant (AGENTS.md):
//   - OnBeforeToolExecute is the single gate for both (a) interactive-tool confirmation
//     and (b) repetition-loop detection. Both live here.
func (h *HookHandler) BuildBeforeToolExecuteHook() func(goai.BeforeToolExecuteInfo) goai.BeforeToolExecuteResult {
	return func(info goai.BeforeToolExecuteInfo) goai.BeforeToolExecuteResult {
		// 1. Repetition loop check
		if h.detector.CheckAndRecord(info.ToolName, info.Input) {
			return goai.BeforeToolExecuteResult{
				Skip:   true,
				Result: "Execution stopped: detected repeated identical tool calls in single turn.",
			}
		}

		// 2. Interactive tool confirmation gate
		if !IsInteractive(info.ToolName) {
			return goai.BeforeToolExecuteResult{} // Non-interactive: allow immediate execution
		}

		if h.bridge == nil {
			return goai.BeforeToolExecuteResult{} // No bridge configured (e.g. headless/test)
		}

		// Blocks this goroutine until the TUI sends a decision
		approved := h.bridge.RequestConfirmation(info.ToolName, info.ToolCallID, info.Input)
		if !approved {
			return goai.BeforeToolExecuteResult{
				Skip:   true,
				Result: "User declined this action.",
			}
		}

		return goai.BeforeToolExecuteResult{} // Approved: run tool normally
	}
}

package agent_test

import (
	"encoding/json"
	"testing"

	"github.com/sapirrior/delta/internal/agent"
)

func TestLoopDetector(t *testing.T) {
	ld := agent.NewLoopDetector()

	input := json.RawMessage(`{"path":"main.go"}`)

	// 1st call
	if ld.CheckAndRecord("read_file", input) {
		t.Fatalf("unexpected loop detect on 1st call")
	}

	// 2nd call
	if ld.CheckAndRecord("read_file", input) {
		t.Fatalf("unexpected loop detect on 2nd call")
	}

	// 3rd consecutive identical call -> MUST detect loop!
	if !ld.CheckAndRecord("read_file", input) {
		t.Fatalf("expected loop detector to trigger on 3rd identical call")
	}

	// Reset should allow calls again
	ld.Reset()
	if ld.CheckAndRecord("read_file", input) {
		t.Fatalf("unexpected loop detect after reset")
	}
}

func TestInteractiveTools(t *testing.T) {
	if !agent.IsInteractive("write_file") {
		t.Errorf("write_file must be interactive")
	}
	if !agent.IsInteractive("edit_file") {
		t.Errorf("edit_file must be interactive")
	}
	if !agent.IsInteractive("run_command") {
		t.Errorf("run_command must be interactive")
	}
	if agent.IsInteractive("read_file") {
		t.Errorf("read_file must NOT be interactive")
	}
	if agent.IsInteractive("search_text") {
		t.Errorf("search_text must NOT be interactive")
	}
}

package agent

import (
	"github.com/sapirrior/delta/internal/tool"
	"github.com/sapirrior/delta/internal/tools/builtins"
	"github.com/zendev-sh/goai"
)

var defaultCatalog = tool.DefaultRegistry(
	builtins.ReadFileTool,
	builtins.WriteFileTool,
	builtins.EditFileTool,
	builtins.ListDirTool,
	builtins.SearchTextTool,
	builtins.FindTool,
	builtins.RunCommandTool,
	builtins.WebFetchTool,
	builtins.ScheduleTool,
)

// DefaultToolRegistry returns the global tool catalog.
func DefaultToolRegistry() *tool.Registry {
	return defaultCatalog
}

// IsInteractive reports whether a tool requires confirmation before executing.
func IsInteractive(name string) bool {
	return defaultCatalog.IsInteractive(name)
}

// BuildTools returns all tools configured for a workspace root.
func BuildTools(workspaceRoot string) []goai.Tool {
	return defaultCatalog.BuildTools(workspaceRoot)
}

// HumanLabel returns a clean label for human-facing display in TUI toolcards.
func HumanLabel(name string) string {
	return defaultCatalog.DisplayName(name)
}

package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/sapirrior/delta/internal/constants"
	"github.com/zendev-sh/goai"
	"github.com/zendev-sh/goai/provider"
)

// AgentEvent represents events streamed to the core engine.
type AgentEvent struct {
	Type           AgentEventType
	Text           string
	ToolCallID     string
	ToolName       string
	ToolInput      string
	ToolOutput     string
	IsError        bool
	StepsExhausted bool
	InputTokens    int
	OutputTokens   int
}

type AgentEventType string

const (
	EventChunkText       AgentEventType = constants.EventChunkText
	EventChunkReasoning  AgentEventType = constants.EventChunkReasoning
	EventToolStarting    AgentEventType = constants.EventToolStarting
	EventToolDone        AgentEventType = constants.EventToolDone
	EventTurnComplete    AgentEventType = constants.EventTurnComplete
	EventError           AgentEventType = constants.EventError
	EventConfirmationAsk AgentEventType = constants.EventConfirmationAsk
)

// ConfirmationRequest holds a pending tool permission request.
type ConfirmationRequest struct {
	ToolName   string
	ToolCallID string
	Input      json.RawMessage
	ReplyChan  chan bool
}

// ChannelConfirmationBridge implements ConfirmationBridge using channels.
type ChannelConfirmationBridge struct {
	AskChan chan<- ConfirmationRequest
}

func (c *ChannelConfirmationBridge) RequestConfirmation(toolName, toolCallID string, input json.RawMessage) bool {
	replyChan := make(chan bool, 1)
	c.AskChan <- ConfirmationRequest{
		ToolName:   toolName,
		ToolCallID: toolCallID,
		Input:      input,
		ReplyChan:  replyChan,
	}
	return <-replyChan
}

// ToolCallRecord describes a tool call snapshot for conversation reconstruction.
type ToolCallRecord struct {
	ID        string
	Name      string
	Arguments string
}

// MessageRecord provides a snapshot of a conversation turn for restoration.
type MessageRecord struct {
	Role       string // "user", "assistant", "tool"
	Content    string
	ToolCallID string
	ToolName   string
	ToolCalls  []ToolCallRecord
}

// Runner manages conversation state and drives GoAI text generation and tool loops.
// It has no persistence dependencies; core coordinates session storage.
type Runner struct {
	model       provider.LanguageModel
	modelName   string
	cwd         string
	tools       []goai.Tool
	messages    []provider.Message
	hookHandler *HookHandler
}

// NewRunner creates a new agent turn runner.
func NewRunner(
	model provider.LanguageModel,
	modelName string,
	cwd string,
	bridge ConfirmationBridge,
) *Runner {
	sysPrompt := BuildSystemPrompt(cwd)

	return &Runner{
		model:       model,
		modelName:   modelName,
		cwd:         cwd,
		tools:       BuildTools(cwd),
		messages:    []provider.Message{goai.SystemMessage(sysPrompt)},
		hookHandler: NewHookHandler(bridge),
	}
}

// SetModel updates the active language model and model ID.
func (r *Runner) SetModel(model provider.LanguageModel, modelName string) {
	r.model = model
	r.modelName = modelName
}

// ResetContext resets the conversation message history back to initial system prompt.
func (r *Runner) ResetContext() {
	sysPrompt := BuildSystemPrompt(r.cwd)
	r.messages = []provider.Message{goai.SystemMessage(sysPrompt)}
}

// RestoreMessages reconstructs conversation messages from logical turn records.
func (r *Runner) RestoreMessages(records []MessageRecord) {
	sysPrompt := BuildSystemPrompt(r.cwd)
	r.messages = []provider.Message{goai.SystemMessage(sysPrompt)}

	for _, rec := range records {
		switch rec.Role {
		case "user":
			r.messages = append(r.messages, goai.UserMessage(rec.Content))
		case "assistant":
			if len(rec.ToolCalls) > 0 {
				var parts []provider.Part
				if rec.Content != "" {
					parts = append(parts, provider.Part{
						Type: provider.PartText,
						Text: rec.Content,
					})
				}
				for _, tc := range rec.ToolCalls {
					parts = append(parts, provider.Part{
						Type:       provider.PartToolCall,
						ToolCallID: tc.ID,
						ToolName:   tc.Name,
						ToolInput:  json.RawMessage(tc.Arguments),
					})
				}
				r.messages = append(r.messages, provider.Message{
					Role:    provider.RoleAssistant,
					Content: parts,
				})
			} else {
				r.messages = append(r.messages, goai.AssistantMessage(rec.Content))
			}
		case "tool":
			r.messages = append(r.messages, goai.ToolMessage(rec.ToolCallID, rec.ToolName, rec.Content))
		}
	}
}

// RunTurn executes an interactive conversation turn streaming back events.
func (r *Runner) RunTurn(ctx context.Context, userInput string, eventCh chan<- AgentEvent) error {
	var inTokens, outTokens int
	defer func() {
		eventCh <- AgentEvent{
			Type:         EventTurnComplete,
			InputTokens:  inTokens,
			OutputTokens: outTokens,
		}
	}()

	// 1. Record user message
	userMsg := goai.UserMessage(userInput)
	r.messages = append(r.messages, userMsg)

	r.hookHandler.detector.Reset()

	// 2. Setup streaming with tools, max steps ceiling, and hooks
	stream, err := goai.StreamText(ctx, r.model,
		goai.WithMessages(r.messages...),
		goai.WithTools(r.tools...),
		goai.WithMaxSteps(constants.MaxTurnSteps), // AGENTS.md soft ceiling
		goai.WithOnBeforeToolExecute(r.hookHandler.BuildBeforeToolExecuteHook()),
		goai.WithOnToolCallStart(func(info goai.ToolCallStartInfo) {
			eventCh <- AgentEvent{
				Type:       EventToolStarting,
				ToolCallID: info.ToolCallID,
				ToolName:   info.ToolName,
				ToolInput:  string(info.Input),
			}
		}),
		goai.WithOnToolCall(func(info goai.ToolCallInfo) {
			out := info.Output
			isErr := info.Error != nil
			if isErr {
				out = fmt.Sprintf("Tool error: %v", info.Error)
			} else if strings.Contains(out, "declined") || strings.Contains(out, "stopped:") {
				isErr = true
			}
			eventCh <- AgentEvent{
				Type:       EventToolDone,
				ToolCallID: info.ToolCallID,
				ToolName:   info.ToolName,
				ToolInput:  string(info.Input),
				ToolOutput: out,
				IsError:    isErr,
			}
		}),
	)

	if err != nil {
		eventCh <- AgentEvent{Type: EventError, Text: fmt.Sprintf("Stream start error: %v", err)}
		return err
	}

	var accumulatedAssistant strings.Builder
	stripper := NewStreamThinkingStripper()
	hasProviderReasoning := false

	// 3. Drain stream chunks
	for chunk := range stream.Stream() {
		switch chunk.Type {
		case provider.ChunkReasoning:
			hasProviderReasoning = true
			eventCh <- AgentEvent{Type: EventChunkReasoning, Text: chunk.Text}

		case provider.ChunkText:
			if hasProviderReasoning {
				accumulatedAssistant.WriteString(chunk.Text)
				eventCh <- AgentEvent{Type: EventChunkText, Text: chunk.Text}
				continue
			}

			thDelta, ansDelta := stripper.Feed(chunk.Text)
			if thDelta != "" {
				eventCh <- AgentEvent{Type: EventChunkReasoning, Text: thDelta}
			}
			if ansDelta != "" {
				accumulatedAssistant.WriteString(ansDelta)
				eventCh <- AgentEvent{Type: EventChunkText, Text: ansDelta}
			}

		case provider.ChunkToolCall:
			// Tool calls are handled via GoAI hooks and stream execution
		case provider.ChunkError:
			eventCh <- AgentEvent{Type: EventError, Text: fmt.Sprintf("Stream error: %v", chunk.Error)}
		}
	}

	if !hasProviderReasoning {
		thRem, ansRem := stripper.Flush()
		if thRem != "" {
			eventCh <- AgentEvent{Type: EventChunkReasoning, Text: thRem}
		}
		if ansRem != "" {
			accumulatedAssistant.WriteString(ansRem)
			eventCh <- AgentEvent{Type: EventChunkText, Text: ansRem}
		}
	}

	if streamErr := stream.Err(); streamErr != nil {
		eventCh <- AgentEvent{Type: EventError, Text: fmt.Sprintf("Stream error: %v", streamErr)}
	}

	// 4. Record result and messages for multi-turn history
	res := stream.Result()
	if res != nil {
		inTokens = res.TotalUsage.InputTokens
		outTokens = res.TotalUsage.OutputTokens

		if res.StepsExhausted {
			exhaustMsg := fmt.Sprintf("\n[Paused: Soft ceiling of %d tool calls reached in single turn.]", constants.MaxTurnSteps)
			eventCh <- AgentEvent{
				Type:           EventChunkText,
				Text:           exhaustMsg,
				StepsExhausted: true,
			}
		}

		if len(res.ResponseMessages) > 0 {
			r.messages = append(r.messages, res.ResponseMessages...)
		}
	}

	return nil
}

package agent

import (
	"strings"
)

// StreamThinkingStripper is a fast O(1) streaming state machine that strips
// <thought>, <think>, <reasoning>, <reflection>, <thought_process> tags
// on-the-fly without running quadratic regex passes on accumulated history.
type StreamThinkingStripper struct {
	inThought bool
	buffer    strings.Builder
}

func NewStreamThinkingStripper() *StreamThinkingStripper {
	return &StreamThinkingStripper{}
}

// Feed processes an incoming chunk of text and yields reasoning and clean answer deltas.
func (s *StreamThinkingStripper) Feed(chunk string) (thoughtDelta string, answerDelta string) {
	s.buffer.WriteString(chunk)
	text := s.buffer.String()
	s.buffer.Reset()

	var thought strings.Builder
	var answer strings.Builder

	i := 0
	n := len(text)

	for i < n {
		if !s.inThought {
			// Look for tag start '<'
			idx := strings.IndexByte(text[i:], '<')
			if idx == -1 {
				answer.WriteString(text[i:])
				break
			}

			// Output everything before '<' as answer
			answer.WriteString(text[i : i+idx])
			i += idx

			// Check if we have enough characters to inspect the tag
			rem := text[i:]
			if !strings.Contains(rem, ">") {
				// Incomplete tag potentially split across chunks: buffer it if under max tag length
				if len(rem) < 25 {
					s.buffer.WriteString(rem)
					break
				}
				// Otherwise treat as normal character
				answer.WriteByte(text[i])
				i++
				continue
			}

			tagEnd := strings.IndexByte(rem, '>')
			tag := strings.ToLower(rem[:tagEnd+1])
			if isOpeningThoughtTag(tag) {
				s.inThought = true
				i += tagEnd + 1
			} else {
				answer.WriteString(rem[:tagEnd+1])
				i += tagEnd + 1
			}
		} else {
			// Inside thought: look for closing '</' or tag end
			idx := strings.IndexByte(text[i:], '<')
			if idx == -1 {
				thought.WriteString(text[i:])
				break
			}

			// Output everything before '<' as thought
			thought.WriteString(text[i : i+idx])
			i += idx

			rem := text[i:]
			if !strings.Contains(rem, ">") {
				if len(rem) < 25 {
					s.buffer.WriteString(rem)
					break
				}
				thought.WriteByte(text[i])
				i++
				continue
			}

			tagEnd := strings.IndexByte(rem, '>')
			tag := strings.ToLower(rem[:tagEnd+1])
			if isClosingThoughtTag(tag) {
				s.inThought = false
				i += tagEnd + 1
			} else {
				thought.WriteString(rem[:tagEnd+1])
				i += tagEnd + 1
			}
		}
	}

	return thought.String(), answer.String()
}

// Flush returns any remaining buffered characters at the end of the stream.
func (s *StreamThinkingStripper) Flush() (thoughtDelta string, answerDelta string) {
	rem := s.buffer.String()
	s.buffer.Reset()
	if rem == "" {
		return "", ""
	}
	if s.inThought {
		return rem, ""
	}
	return "", rem
}

func isOpeningThoughtTag(tag string) bool {
	// e.g. <think>, <thought>, <reasoning>, <reflection>, <thought_process>
	trimmed := strings.Trim(tag, "<> \t\r\n")
	parts := strings.Fields(trimmed)
	if len(parts) == 0 {
		return false
	}
	name := parts[0]
	switch name {
	case "think", "thin", "thnk", "thinking", "thought", "reasoning", "reflection", "thought_process":
		return true
	default:
		return false
	}
}

func isClosingThoughtTag(tag string) bool {
	trimmed := strings.Trim(tag, "<> \t\r\n")
	trimmed = strings.TrimPrefix(trimmed, "/")
	trimmed = strings.TrimPrefix(trimmed, `\`)
	parts := strings.Fields(trimmed)
	if len(parts) == 0 {
		return false
	}
	name := parts[0]
	switch name {
	case "think", "thin", "thnk", "thinking", "thought", "reasoning", "reflection", "thought_process":
		return true
	default:
		return false
	}
}

// ExtractThinking parses a complete text into thoughts and final response
func ExtractThinking(text string) (string, string) {
	stripper := NewStreamThinkingStripper()
	th, ans := stripper.Feed(text)
	thF, ansF := stripper.Flush()
	return th + thF, ans + ansF
}

package agent

import (
	"testing"
)

func TestExtractThinking(t *testing.T) {
	tests := []struct {
		name         string
		input        string
		wantThinking string
		wantAnswer   string
	}{
		{
			name:         "no thinking tags",
			input:        "Hello world",
			wantThinking: "",
			wantAnswer:   "Hello world",
		},
		{
			name:         "closed thought tag",
			input:        "<thought>I am thinking here</thought>This is the answer.",
			wantThinking: "I am thinking here",
			wantAnswer:   "This is the answer.",
		},
		{
			name:         "unclosed thought tag streaming",
			input:        "<thought>Partial thoughts in progress",
			wantThinking: "Partial thoughts in progress",
			wantAnswer:   "",
		},
		{
			name:         "think tag",
			input:        "<think>\nNeed to plan.\n</think>\nHere is the plan.",
			wantThinking: "\nNeed to plan.\n",
			wantAnswer:   "\nHere is the plan.",
		},
		{
			name:         "reasoning tag",
			input:        "<reasoning>Step 1</reasoning>Done!",
			wantThinking: "Step 1",
			wantAnswer:   "Done!",
		},
		{
			name:         "multiple thoughts",
			input:        "<thought>First</thought>Middle<thought>Second</thought>End",
			wantThinking: "FirstSecond",
			wantAnswer:   "MiddleEnd",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			gotThinking, gotAnswer := ExtractThinking(tt.input)
			if gotThinking != tt.wantThinking {
				t.Errorf("ExtractThinking() gotThinking = %q, want %q", gotThinking, tt.wantThinking)
			}
			if gotAnswer != tt.wantAnswer {
				t.Errorf("ExtractThinking() gotAnswer = %q, want %q", gotAnswer, tt.wantAnswer)
			}
		})
	}
}

package agent
import ( "fmt" "time" )
// BuildSystemPrompt generates Delta's system prompt matching the Rust implementation. func BuildSystemPrompt(cwd string) string { year := time.Now().UTC().Year()
return fmt.Sprintf(`<role> You are Delta, a general-purpose AI agent living in the terminal. You help with everyday tasks: files, research, writing, planning, shell utility work, and code when asked. </role>
<rules> - Investigate before acting: use tools to check real state, never assume. - Execute non-mutating tools (read, search, list, fetch) concurrently. - Execute state-changing tools (write, edit, run_command) sequentially. - Be concise and direct. No filler, no preambles, no conversational padding. - Match the user's register: casual questions get casual answers; technical tasks get precise, technical ones. </rules>
<tools> - Read/Search: read_file, list_dir, search_text, find - Execute: run_command - Write/Modify: write_file, edit_file - Web: web_fetch - Scheduling: schedule </tools>
<output_format> Markdown: # ## ### | - * 1. | > | `+"```"+` | **bold** *italic* `+"`code`"+` | tables No HTML. No emoji. </output_format>
<context> cwd: %s year: %d </context>`, cwd, year) }

package config

import (
	"strings"

	"github.com/zendev-sh/goai/provider"
	"github.com/zendev-sh/goai/provider/anthropic"
	"github.com/zendev-sh/goai/provider/compat"
	"github.com/zendev-sh/goai/provider/google"
	"github.com/zendev-sh/goai/provider/openai"
)

// ProviderPreset defines known API endpoint presets.
type ProviderPreset struct {
	Name         string
	BaseURL      string
	DefaultModel string
	KeyPrompt    string
}

// Presets lists common pre-configured LLM providers.
var Presets = []ProviderPreset{
	{
		Name:         "OpenAI",
		BaseURL:      "https://api.openai.com/v1",
		DefaultModel: "gpt-4o",
		KeyPrompt:    "Enter your OpenAI API key (sk-...): ",
	},
	{
		Name:         "OpenRouter",
		BaseURL:      "https://openrouter.ai/api/v1",
		DefaultModel: "anthropic/claude-3.5-sonnet",
		KeyPrompt:    "Enter your OpenRouter API key (sk-or-...): ",
	},
	{
		Name:         "Google Gemini (OpenAI-compatible endpoint)",
		BaseURL:      "https://generativelanguage.googleapis.com/v1beta/openai",
		DefaultModel: "gemini-1.5-pro",
		KeyPrompt:    "Enter your Google AI Studio API key: ",
	},
	{
		Name:         "Ollama (Local)",
		BaseURL:      "http://localhost:11434/v1",
		DefaultModel: "llama3.1",
		KeyPrompt:    "Enter API key (leave empty for none): ",
	},
	{
		Name:         "Custom OpenAI-compatible endpoint",
		BaseURL:      "",
		DefaultModel: "",
		KeyPrompt:    "Enter API key (if required): ",
	},
}

// BuildModel intelligently selects the native GoAI provider (Google, Anthropic, OpenAI)
// based on model name analysis or URL, and falls back to compat.Chat for generic endpoints.
func BuildModel(cfg Config) provider.LanguageModel {
	m := strings.ToLower(strings.TrimSpace(cfg.Model))
	u := strings.ToLower(strings.TrimSpace(cfg.BaseURL))

	// 1. If base_url explicitly points to a custom or local endpoint (like Ollama or OpenRouter)
	// and is not the official default API URL, use compat provider.
	isCustomURL := u != "" &&
		!strings.Contains(u, "googleapis.com") &&
		!strings.Contains(u, "api.anthropic.com") &&
		!strings.Contains(u, "api.openai.com")

	if isCustomURL {
		opts := []compat.Option{compat.WithBaseURL(cfg.BaseURL)}
		if cfg.APIKey != "" {
			opts = append(opts, compat.WithAPIKey(cfg.APIKey))
		}
		return compat.Chat(cfg.Model, opts...)
	}

	// 2. Google Gemini native provider:
	// Matches gemini-*, gemma-*, or googleapis base_url
	if strings.HasPrefix(m, "gemini-") || strings.HasPrefix(m, "gemma-") || strings.Contains(u, "googleapis.com") {
		var opts []google.Option
		if cfg.APIKey != "" {
			opts = append(opts, google.WithAPIKey(cfg.APIKey))
		}
		return google.Chat(cfg.Model, opts...)
	}

	// 3. Anthropic Claude native provider:
	// Matches claude-*, sonnet-*, opus-*, haiku-*, or anthropic.com base_url
	if strings.HasPrefix(m, "claude-") || strings.HasPrefix(m, "sonnet-") || strings.HasPrefix(m, "opus-") || strings.HasPrefix(m, "haiku-") || strings.Contains(u, "anthropic.com") {
		var opts []anthropic.Option
		if cfg.APIKey != "" {
			opts = append(opts, anthropic.WithAPIKey(cfg.APIKey))
		}
		return anthropic.Chat(cfg.Model, opts...)
	}

	// 4. OpenAI native provider:
	// Matches gpt-*, o1-*, o3-*, chatgpt-*, or api.openai.com base_url
	if strings.HasPrefix(m, "gpt-") || strings.HasPrefix(m, "o1-") || strings.HasPrefix(m, "o3-") || strings.HasPrefix(m, "chatgpt-") || strings.Contains(u, "openai.com") {
		var opts []openai.Option
		if cfg.APIKey != "" {
			opts = append(opts, openai.WithAPIKey(cfg.APIKey))
		}
		return openai.Chat(cfg.Model, opts...)
	}

	// 5. Default fallback to compat provider
	opts := []compat.Option{}
	if cfg.BaseURL != "" {
		opts = append(opts, compat.WithBaseURL(cfg.BaseURL))
	}
	if cfg.APIKey != "" {
		opts = append(opts, compat.WithAPIKey(cfg.APIKey))
	}
	return compat.Chat(cfg.Model, opts...)
}

// BuildCompatModel maintains backwards compatibility
func BuildCompatModel(cfg Config) provider.LanguageModel {
	return BuildModel(cfg)
}

