package config

import (
	"fmt"
	"os"
	"path/filepath"

	toml "github.com/pelletier/go-toml/v2"
)

// Config represents Delta's configuration stored at ~/.delta/config.toml
type Config struct {
	BaseURL string `toml:"base_url"`
	APIKey  string `toml:"api_key"`
	Model   string `toml:"model"`
}

func defaultBaseURL() string {
	if v := os.Getenv("OPENAI_BASE_URL"); v != "" {
		return v
	}
	return "https://api.openai.com/v1"
}

func defaultModel() string {
	if v := os.Getenv("OPENAI_MODEL"); v != "" {
		return v
	}
	return "gpt-4o"
}

// DefaultConfig returns default config options taking environment variables into account.
func DefaultConfig() Config {
	return Config{
		BaseURL: defaultBaseURL(),
		APIKey:  os.Getenv("OPENAI_API_KEY"),
		Model:   defaultModel(),
	}
}

// ConfigPath returns the standard path to ~/.delta/config.toml
func ConfigPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to determine user home directory: %w", err)
	}
	return filepath.Join(home, ".delta", "config.toml"), nil
}

// Load reads and unmarshals config from path, creating default file if nonexistent.
func Load() (Config, error) {
	path, err := ConfigPath()
	if err != nil {
		return DefaultConfig(), err
	}

	if _, err := os.Stat(path); os.IsNotExist(err) {
		cfg := DefaultConfig()
		_ = Save(path, cfg)
		return cfg, nil
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return DefaultConfig(), fmt.Errorf("failed reading config file: %w", err)
	}

	var cfg Config
	if err := toml.Unmarshal(data, &cfg); err != nil {
		return DefaultConfig(), fmt.Errorf("failed parsing config.toml: %w", err)
	}

	if cfg.BaseURL == "" {
		cfg.BaseURL = defaultBaseURL()
	}
	if cfg.Model == "" {
		cfg.Model = defaultModel()
	}
	return cfg, nil
}

// Save writes config formatted as TOML.
func Save(path string, cfg Config) error {
	parent := filepath.Dir(path)
	if err := os.MkdirAll(parent, 0o755); err != nil {
		return fmt.Errorf("failed creating config directory: %w", err)
	}

	data, err := toml.Marshal(cfg)
	if err != nil {
		return fmt.Errorf("failed marshaling config to toml: %w", err)
	}

	return os.WriteFile(path, data, 0o644)
}

