package core

import "context"

// Backend defines the boundary contract consumed by presentation layers (e.g. TUI).
// The presentation layer does not import internal/agent, internal/session, or internal/tools.
type Backend interface {
	// Turn & Execution control
	StartTurn(ctx context.Context, input string) error
	StartBash(ctx context.Context, command string) error
	CancelActiveWork()

	// Asynchronous streams
	Events() <-chan Event
	Confirmations() <-chan Confirmation

	// Confirmation resolution
	ResolveConfirmation(approved bool)
	ResolveConfirmationForSession(toolName string, approved bool)

	// Slash commands
	Commands() []Command
	ExecuteCommand(ctx context.Context, command string) error

	// Session management
	Sessions() ([]SessionRow, error)
	ResumeSession(ctx context.Context, path string) (SessionView, error)
	NewSession(ctx context.Context) error
	ClearContext(ctx context.Context) error

	// Model configuration
	ModelName() string
	SetModel(ctx context.Context, name string) error
}

package core_test

import (
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestArchitectureImportInvariants(t *testing.T) {
	root := "../.."

	// Invariant 1: internal/core must NOT import internal/tui, charm.land/bubbletea, charm.land/bubbles, charm.land/lipgloss
	checkForbiddenImports(t, filepath.Join(root, "internal/core"), []string{
		"github.com/sapirrior/delta/internal/tui",
		"charm.land/bubbletea",
		"charm.land/bubbles",
		"charm.land/lipgloss",
	}, "internal/core")

	// Invariant 2: internal/agent must NOT import internal/session
	checkForbiddenImports(t, filepath.Join(root, "internal/agent"), []string{
		"github.com/sapirrior/delta/internal/session",
	}, "internal/agent")

	// Invariant 3: internal/tool must NOT import charm.land/lipgloss, charm.land/bubbletea, charm.land/bubbles
	checkForbiddenImports(t, filepath.Join(root, "internal/tool"), []string{
		"charm.land/lipgloss",
		"charm.land/bubbletea",
		"charm.land/bubbles",
	}, "internal/tool")

	// Invariant 4: internal/tui/view must NOT import internal/core, internal/agent, internal/session, internal/tool, or internal/tools
	checkForbiddenImports(t, filepath.Join(root, "internal/tui/view"), []string{
		"github.com/sapirrior/delta/internal/core",
		"github.com/sapirrior/delta/internal/agent",
		"github.com/sapirrior/delta/internal/session",
		"github.com/sapirrior/delta/internal/tool",
		"github.com/sapirrior/delta/internal/tools",
	}, "internal/tui/view")
}

func checkForbiddenImports(t *testing.T, dir string, forbidden []string, pkgLabel string) {
	files, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return
		}
		t.Fatalf("failed reading dir %s: %v", dir, err)
	}

	fset := token.NewFileSet()
	for _, f := range files {
		if !strings.HasSuffix(f.Name(), ".go") || strings.HasSuffix(f.Name(), "_test.go") {
			continue
		}
		path := filepath.Join(dir, f.Name())
		node, err := parser.ParseFile(fset, path, nil, parser.ImportsOnly)
		if err != nil {
			t.Fatalf("failed parsing %s: %v", path, err)
		}

		for _, imp := range node.Imports {
			impPath := strings.Trim(imp.Path.Value, `"`)
			for _, forbid := range forbidden {
				if strings.HasPrefix(impPath, forbid) {
					t.Errorf("[%s] %s imports forbidden package %q", pkgLabel, f.Name(), impPath)
				}
			}
		}
	}
}

package core

import (
	"context"
	"strings"
)

// CommandHandler is the execution function for a slash command.
type CommandHandler func(ctx context.Context, e *Engine, args []string) error

// CommandDescriptor defines a slash command, its metadata, and handler.
type CommandDescriptor struct {
	Name        string
	Description string
	Handler     CommandHandler
}

// FilterCommands returns commands matching a query string (case-insensitive in name or description).
func FilterCommands(commands []CommandDescriptor, query string) []CommandDescriptor {
	if query == "" {
		res := make([]CommandDescriptor, len(commands))
		copy(res, commands)
		return res
	}
	q := strings.ToLower(query)
	var filtered []CommandDescriptor
	for _, cmd := range commands {
		if strings.Contains(strings.ToLower(cmd.Name), q) || strings.Contains(strings.ToLower(cmd.Description), q) {
			filtered = append(filtered, cmd)
		}
	}
	return filtered
}

// DefaultCommands returns the canonical list of slash commands supported by Delta.
func DefaultCommands() []CommandDescriptor {
	return []CommandDescriptor{
		{
			Name:        "/model",
			Description: "Set or display the active model",
			Handler: func(ctx context.Context, e *Engine, args []string) error {
				if len(args) > 0 {
					return e.SetModel(ctx, args[0])
				}
				e.eventCh <- Event{
					Type:      EventModelChanged,
					ModelName: e.ModelName(),
				}
				return nil
			},
		},
		{
			Name:        "/new",
			Description: "Start a new session and reset context",
			Handler: func(ctx context.Context, e *Engine, args []string) error {
				return e.NewSession(ctx)
			},
		},
		{
			Name:        "/clear",
			Description: "Clear transcript and conversation context",
			Handler: func(ctx context.Context, e *Engine, args []string) error {
				return e.ClearContext(ctx)
			},
		},
		{
			Name:        "/resume",
			Description: "Resume a previous session from history",
			Handler: func(ctx context.Context, e *Engine, args []string) error {
				// Presentation triggers session dock for interactive resume
				return nil
			},
		},
		{
			Name:        "/exit",
			Description: "Exit Delta",
			Handler: func(ctx context.Context, e *Engine, args []string) error {
				return nil
			},
		},
	}
}

package core_test

import (
	"context"
	"testing"

	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/core"
)

func TestCommandCatalogFiltering(t *testing.T) {
	cmds := core.DefaultCommands()
	if len(cmds) == 0 {
		t.Fatal("expected non-empty default commands catalog")
	}

	// 1. Empty query returns all
	all := core.FilterCommands(cmds, "")
	if len(all) != len(cmds) {
		t.Fatalf("expected %d commands on empty query, got %d", len(cmds), len(all))
	}

	// 2. Query matching name
	filteredModel := core.FilterCommands(cmds, "model")
	if len(filteredModel) != 1 || filteredModel[0].Name != "/model" {
		t.Fatalf("expected only /model, got %+v", filteredModel)
	}

	// 3. Query matching description
	filteredContext := core.FilterCommands(cmds, "context")
	if len(filteredContext) < 2 {
		t.Fatalf("expected at least 2 commands with 'context' in description (/new, /clear), got %d", len(filteredContext))
	}

	// 4. Non-matching query
	filteredNone := core.FilterCommands(cmds, "zzzznonexistent")
	if len(filteredNone) != 0 {
		t.Fatalf("expected 0 commands for nonexistent query, got %d", len(filteredNone))
	}
}

func TestCommandCatalogExecution(t *testing.T) {
	tmpDir := t.TempDir()
	cfg := config.DefaultConfig()
	cfg.Model = "gemini-2.5-flash"

	engine, err := core.NewEngine(cfg, tmpDir)
	if err != nil {
		t.Fatalf("creating engine: %v", err)
	}

	ctx := context.Background()

	// 1. Execute /model with argument
	if err := engine.ExecuteCommand(ctx, "/model test-model-42"); err != nil {
		t.Fatalf("executing /model: %v", err)
	}
	if engine.ModelName() != "test-model-42" {
		t.Fatalf("expected model to be updated to test-model-42, got %s", engine.ModelName())
	}

	// 2. Execute /clear
	if err := engine.ExecuteCommand(ctx, "/clear"); err != nil {
		t.Fatalf("executing /clear: %v", err)
	}

	// 3. Execute /new
	if err := engine.ExecuteCommand(ctx, "/new"); err != nil {
		t.Fatalf("executing /new: %v", err)
	}

	// 4. Execute unknown command
	if err := engine.ExecuteCommand(ctx, "/unknownxyz"); err == nil {
		t.Fatal("expected error executing unknown command")
	}
}

package core

import (
	"context"
	"encoding/json"
	"os"
	"sync"
	"testing"
	"time"

	"github.com/sapirrior/delta/internal/config"
)

func TestConfirmationFlowAndSessionScopedApproval(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_confirm_test_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	cfg := config.DefaultConfig()
	cfg.Model = "test-model"

	eng, err := NewEngine(cfg, tempDir)
	if err != nil {
		t.Fatalf("failed to create engine: %v", err)
	}

	confCh := eng.Confirmations()

	// 1. One-time approval: ask confirmation for "run_command"
	var wg sync.WaitGroup
	var approved1 bool
	wg.Add(1)
	go func() {
		defer wg.Done()
		approved1 = eng.requestConfirmation("run_command", "call_1", json.RawMessage(`{"command":"ls"}`))
	}()

	select {
	case conf := <-confCh:
		if conf.ToolName != "run_command" {
			t.Fatalf("expected conf for run_command, got %s", conf.ToolName)
		}
		if conf.ToolCallID != "call_1" {
			t.Fatalf("expected tool call ID call_1, got %s", conf.ToolCallID)
		}
		// Resolve once
		eng.ResolveConfirmation(true)
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for confirmation 1")
	}

	wg.Wait()
	if !approved1 {
		t.Fatal("expected call 1 to be approved")
	}

	// Because it was one-time approval, another call to "run_command" should STILL ask for confirmation
	var approved2 bool
	wg.Add(1)
	go func() {
		defer wg.Done()
		approved2 = eng.requestConfirmation("run_command", "call_2", json.RawMessage(`{"command":"pwd"}`))
	}()

	select {
	case conf := <-confCh:
		if conf.ToolName != "run_command" {
			t.Fatalf("expected conf for run_command, got %s", conf.ToolName)
		}
		// Resolve for SESSION this time
		eng.ResolveConfirmationForSession("run_command", true)
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for confirmation 2")
	}

	wg.Wait()
	if !approved2 {
		t.Fatal("expected call 2 to be approved")
	}

	// 2. Subsequent call to "run_command" in the same session must NOT emit confirmation and auto-approve immediately
	select {
	case conf := <-confCh:
		t.Fatalf("unexpected confirmation emitted before call: %+v", conf)
	default:
	}

	doneChan := make(chan bool, 1)
	go func() {
		app := eng.requestConfirmation("run_command", "call_3", json.RawMessage(`{"command":"whoami"}`))
		doneChan <- app
	}()

	select {
	case app := <-doneChan:
		if !app {
			t.Fatal("expected call 3 to be auto-approved via session allowlist")
		}
	case <-time.After(500 * time.Millisecond):
		t.Fatal("call 3 hung instead of auto-approving via session allowlist")
	}

	// Ensure nothing was sent to confCh
	select {
	case conf := <-confCh:
		t.Fatalf("unexpected confirmation request received on confCh: %+v", conf)
	default:
	}

	// 3. Different tool ("edit_file") must STILL require confirmation
	var approvedEdit bool
	wg.Add(1)
	go func() {
		defer wg.Done()
		approvedEdit = eng.requestConfirmation("edit_file", "call_4", json.RawMessage(`{"path":"foo.txt"}`))
	}()

	select {
	case conf := <-confCh:
		if conf.ToolName != "edit_file" {
			t.Fatalf("expected conf for edit_file, got %s", conf.ToolName)
		}
		eng.ResolveConfirmation(true)
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for confirmation for edit_file")
	}

	wg.Wait()
	if !approvedEdit {
		t.Fatal("expected edit_file call to be approved")
	}

	// 4. NewSession resets the session-scoped approval allowlist
	if err := eng.NewSession(context.Background()); err != nil {
		t.Fatalf("failed to create new session: %v", err)
	}

	var approvedAfterReset bool
	wg.Add(1)
	go func() {
		defer wg.Done()
		approvedAfterReset = eng.requestConfirmation("run_command", "call_5", json.RawMessage(`{"command":"ls"}`))
	}()

	select {
	case conf := <-confCh:
		if conf.ToolName != "run_command" {
			t.Fatalf("expected conf for run_command after session reset, got %s", conf.ToolName)
		}
		eng.ResolveConfirmation(false) // decline
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for confirmation after session reset (allowlist was not cleared!)")
	}

	wg.Wait()
	if approvedAfterReset {
		t.Fatal("expected declined call 5 to return false")
	}

	// 5. ResumeSession also resets the session-scoped approval allowlist
	sessRows, err := eng.Sessions()
	if err != nil || len(sessRows) == 0 {
		t.Fatalf("failed listing sessions: %v", err)
	}

	// First allow for session
	eng.sessionAllowedTools["run_command"] = true

	// Now resume
	if _, err := eng.ResumeSession(context.Background(), sessRows[0].FilePath); err != nil {
		t.Fatalf("failed to resume session: %v", err)
	}

	var approvedAfterResume bool
	wg.Add(1)
	go func() {
		defer wg.Done()
		approvedAfterResume = eng.requestConfirmation("run_command", "call_6", json.RawMessage(`{"command":"ls"}`))
	}()

	select {
	case conf := <-confCh:
		if conf.ToolName != "run_command" {
			t.Fatalf("expected conf for run_command after session resume, got %s", conf.ToolName)
		}
		eng.ResolveConfirmation(true)
	case <-time.After(2 * time.Second):
		t.Fatal("timed out waiting for confirmation after resume (allowlist was not cleared!)")
	}

	wg.Wait()
	if !approvedAfterResume {
		t.Fatal("expected call 6 to be approved")
	}
}

package core

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"strings"
	"sync"

	"github.com/sapirrior/delta/internal/agent"
	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/session"
	"github.com/sapirrior/delta/internal/shell"
	"github.com/sapirrior/delta/internal/tool"
)

// Engine implements Backend and orchestrates sessions, turns, commands, and permissions.
type Engine struct {
	mu           sync.Mutex
	cfg          config.Config
	cwd          string
	sessionStore *session.SessionStore
	sessionID    string
	sessionPath  string
	modelName    string

	runner       *agent.Runner
	shellRunner  *shell.Runner
	toolRegistry *tool.Registry
	cmdRegistry  []CommandDescriptor

	eventCh chan Event
	confCh  chan Confirmation

	// Active turn tracking
	activeCancel context.CancelFunc

	// Pending confirmation tracking
	pendingConfirm *agent.ConfirmationRequest

	// Session-scoped approval allowlist: toolName -> allowed
	sessionAllowedTools map[string]bool
}

// NewEngine initializes the Delta application core engine.
func NewEngine(cfg config.Config, cwd string) (*Engine, error) {
	store, err := session.NewStore()
	if err != nil {
		return nil, fmt.Errorf("initializing session store: %w", err)
	}

	sessionID := session.GenerateSessionID()
	sessionPath := store.SessionPath(sessionID, "")

	if err := store.AppendEvent(sessionPath, session.NowMeta("session_start", cfg.Model)); err != nil {
		return nil, fmt.Errorf("starting initial session: %w", err)
	}

	eventCh := make(chan Event, 128)
	confCh := make(chan Confirmation, 4)

	e := &Engine{
		cfg:                 cfg,
		cwd:                 cwd,
		sessionStore:        store,
		sessionID:           sessionID,
		sessionPath:         sessionPath,
		modelName:           cfg.Model,
		eventCh:             eventCh,
		confCh:              confCh,
		shellRunner:         shell.NewRunner(cwd),
		toolRegistry:        agent.DefaultToolRegistry(),
		cmdRegistry:         DefaultCommands(),
		sessionAllowedTools: make(map[string]bool),
	}

	bridge := &engineConfirmationBridge{engine: e}
	model := config.BuildModel(cfg)
	e.runner = agent.NewRunner(model, cfg.Model, cwd, bridge)

	return e, nil
}

type engineConfirmationBridge struct {
	engine *Engine
}

func (b *engineConfirmationBridge) RequestConfirmation(toolName, toolCallID string, input json.RawMessage) bool {
	return b.engine.requestConfirmation(toolName, toolCallID, input)
}

func (e *Engine) requestConfirmation(toolName, toolCallID string, input json.RawMessage) bool {
	e.mu.Lock()
	if e.sessionAllowedTools[toolName] {
		e.mu.Unlock()
		return true
	}

	replyChan := make(chan bool, 1)
	req := &agent.ConfirmationRequest{
		ToolName:   toolName,
		ToolCallID: toolCallID,
		Input:      input,
		ReplyChan:  replyChan,
	}
	e.pendingConfirm = req

	// Prepare neutral confirmation DTO via tool catalog
	conf := e.toolRegistry.Confirmation(toolName, toolCallID, string(input))
	e.mu.Unlock()

	e.confCh <- conf

	approved := <-replyChan

	e.mu.Lock()
	e.pendingConfirm = nil
	e.mu.Unlock()

	return approved
}

func (e *Engine) Events() <-chan Event {
	return e.eventCh
}

func (e *Engine) Confirmations() <-chan Confirmation {
	return e.confCh
}

func (e *Engine) ResolveConfirmation(approved bool) {
	e.mu.Lock()
	req := e.pendingConfirm
	e.mu.Unlock()

	if req != nil && req.ReplyChan != nil {
		req.ReplyChan <- approved
	}
}

func (e *Engine) ResolveConfirmationForSession(toolName string, approved bool) {
	e.mu.Lock()
	if approved {
		e.sessionAllowedTools[toolName] = true
	}
	req := e.pendingConfirm
	e.mu.Unlock()

	if req != nil && req.ReplyChan != nil {
		req.ReplyChan <- approved
	}
}

func (e *Engine) CancelActiveWork() {
	e.mu.Lock()
	cancel := e.activeCancel
	e.activeCancel = nil
	e.mu.Unlock()

	if cancel != nil {
		cancel()
	}
}

func (e *Engine) StartBash(ctx context.Context, command string) error {
	e.mu.Lock()
	turnCtx, cancel := context.WithCancel(ctx)
	e.activeCancel = cancel
	sessPath := e.sessionPath
	store := e.sessionStore
	e.mu.Unlock()

	// Persist bash command invocation as user event
	if err := store.AppendEvent(sessPath, session.NowUser("! "+command)); err != nil {
		log.Printf("delta: failed appending bash invocation event: %v", err)
	}

	go func() {
		defer func() {
			e.mu.Lock()
			if e.activeCancel != nil {
				e.activeCancel = nil
			}
			e.mu.Unlock()
		}()

		res, err := e.shellRunner.Run(turnCtx, command, nil)
		resStr := res.Output
		if err != nil && resStr == "" {
			resStr = err.Error()
		}
		if res.ExitCode != 0 && resStr == "" && res.Error != nil {
			resStr = res.Error.Error()
		}

		isErr := err != nil || res.ExitCode != 0
		if appErr := store.AppendEvent(sessPath, session.NowTool("bash", resStr, isErr)); appErr != nil {
			log.Printf("delta: failed appending bash result event: %v", appErr)
		}

		e.eventCh <- Event{
			Type:            EventToolFinished,
			ToolName:        "bash",
			ToolDisplayName: "Bash",
			ToolInput:       command,
			ToolOutput:      resStr,
			ToolSummary:     resStr,
			IsError:         isErr,
			TurnDone:        true,
		}
	}()

	return nil
}

func (e *Engine) StartTurn(ctx context.Context, input string) error {
	e.mu.Lock()
	turnCtx, cancel := context.WithCancel(ctx)
	e.activeCancel = cancel
	runner := e.runner
	sessPath := e.sessionPath
	store := e.sessionStore
	e.mu.Unlock()

	// Persist user prompt
	if err := store.AppendEvent(sessPath, session.NowUser(input)); err != nil {
		log.Printf("delta: failed appending user prompt event: %v", err)
	}

	agentEvCh := make(chan agent.AgentEvent, 64)

	go func() {
		defer func() {
			e.mu.Lock()
			if e.activeCancel != nil {
				e.activeCancel = nil
			}
			e.mu.Unlock()
		}()

		err := runner.RunTurn(turnCtx, input, agentEvCh)
		if err != nil {
			e.eventCh <- Event{
				Type:     EventApplicationError,
				Error:    err,
				TurnDone: true,
			}
		}
	}()

	go func() {
		var accumulatedAssistant strings.Builder
		var turnToolCalls []session.ToolCall

		for ev := range agentEvCh {
			switch ev.Type {
			case agent.EventChunkText:
				accumulatedAssistant.WriteString(ev.Text)
				e.eventCh <- Event{
					Type:  EventTextDelta,
					Delta: ev.Text,
				}
			case agent.EventChunkReasoning:
				e.eventCh <- Event{
					Type:  EventReasoningDelta,
					Delta: ev.Text,
				}
			case agent.EventToolStarting:
				turnToolCalls = append(turnToolCalls, session.ToolCall{
					ID:   ev.ToolCallID,
					Type: "function",
					Function: session.FunctionCall{
						Name:      ev.ToolName,
						Arguments: ev.ToolInput,
					},
				})
				e.eventCh <- Event{
					Type:            EventToolStarted,
					ToolName:        ev.ToolName,
					ToolDisplayName: e.toolRegistry.DisplayName(ev.ToolName),
					ToolCallID:      ev.ToolCallID,
					ToolInput:       ev.ToolInput,
				}
			case agent.EventToolDone:
				summary := e.toolRegistry.Summarize(ev.ToolName, ev.ToolInput, ev.ToolOutput, ev.IsError)
				if appErr := store.AppendEvent(sessPath, session.NowTool(ev.ToolCallID, ev.ToolOutput, ev.IsError)); appErr != nil {
					log.Printf("delta: failed appending tool event: %v", appErr)
				}
				e.eventCh <- Event{
					Type:            EventToolFinished,
					ToolName:        ev.ToolName,
					ToolDisplayName: e.toolRegistry.DisplayName(ev.ToolName),
					ToolCallID:      ev.ToolCallID,
					ToolInput:       ev.ToolInput,
					ToolOutput:      ev.ToolOutput,
					ToolSummary:     summary,
					IsError:         ev.IsError,
				}
			case agent.EventError:
				e.eventCh <- Event{
					Type:  EventApplicationError,
					Error: fmt.Errorf("%s", ev.Text),
				}
			case agent.EventTurnComplete:
				if accumulatedAssistant.Len() > 0 || len(turnToolCalls) > 0 {
					if appErr := store.AppendEvent(sessPath, session.NowAssistant(accumulatedAssistant.String(), turnToolCalls)); appErr != nil {
						log.Printf("delta: failed appending assistant event: %v", appErr)
					}
				}
				e.eventCh <- Event{
					Type:     EventTurnCompleted,
					TurnDone: true,
				}
			}
		}
	}()

	return nil
}

// RegisterCommand registers a new slash command in the engine.
func (e *Engine) RegisterCommand(cmd CommandDescriptor) {
	e.mu.Lock()
	defer e.mu.Unlock()
	for i, c := range e.cmdRegistry {
		if c.Name == cmd.Name {
			e.cmdRegistry[i] = cmd
			return
		}
	}
	e.cmdRegistry = append(e.cmdRegistry, cmd)
}

func (e *Engine) Commands() []Command {
	e.mu.Lock()
	defs := e.cmdRegistry
	cmds := make([]Command, len(defs))
	for i, d := range defs {
		cmds[i] = Command{Name: d.Name, Description: d.Description}
	}
	e.mu.Unlock()
	return cmds
}

func (e *Engine) ExecuteCommand(ctx context.Context, cmdStr string) error {
	parts := strings.Fields(cmdStr)
	if len(parts) == 0 {
		return nil
	}

	name := parts[0]
	args := parts[1:]

	e.mu.Lock()
	cmds := make([]CommandDescriptor, len(e.cmdRegistry))
	copy(cmds, e.cmdRegistry)
	e.mu.Unlock()

	for _, cmd := range cmds {
		if cmd.Name == name {
			if cmd.Handler != nil {
				return cmd.Handler(ctx, e, args)
			}
			return nil
		}
	}

	return fmt.Errorf("unknown command %s", name)
}

func (e *Engine) ModelName() string {
	e.mu.Lock()
	defer e.mu.Unlock()
	return e.modelName
}

func (e *Engine) SetModel(ctx context.Context, name string) error {
	e.mu.Lock()
	e.modelName = name
	e.cfg.Model = name
	newModel := config.BuildModel(e.cfg)
	e.runner.SetModel(newModel, name)

	if cfgPath, err := config.ConfigPath(); err == nil {
		if saveErr := config.Save(cfgPath, e.cfg); saveErr != nil {
			log.Printf("delta: failed saving config: %v", saveErr)
		}
	}
	e.mu.Unlock()

	e.eventCh <- Event{
		Type:      EventModelChanged,
		ModelName: name,
	}
	return nil
}

func (e *Engine) ClearContext(ctx context.Context) error {
	e.mu.Lock()
	e.runner.ResetContext()
	e.mu.Unlock()
	return nil
}

func (e *Engine) NewSession(ctx context.Context) error {
	e.mu.Lock()
	e.sessionID = session.GenerateSessionID()
	e.sessionPath = e.sessionStore.SessionPath(e.sessionID, "")
	if err := e.sessionStore.AppendEvent(e.sessionPath, session.NowMeta("session_start", e.modelName)); err != nil {
		log.Printf("delta: failed appending new session start event: %v", err)
	}
	e.runner.ResetContext()
	e.sessionAllowedTools = make(map[string]bool)
	sessID := e.sessionID
	e.mu.Unlock()

	e.eventCh <- Event{
		Type:      EventSessionChanged,
		SessionID: sessID,
	}
	return nil
}

func (e *Engine) Sessions() ([]SessionRow, error) {
	e.mu.Lock()
	store := e.sessionStore
	e.mu.Unlock()

	infos, err := store.ListSessions()
	if err != nil {
		return nil, err
	}

	rows := make([]SessionRow, 0, len(infos))
	for _, s := range infos {
		rows = append(rows, SessionRow{
			ID:       s.ID,
			Date:     s.Date,
			FilePath: s.Path,
		})
	}
	return rows, nil
}

func (e *Engine) ResumeSession(ctx context.Context, path string) (SessionView, error) {
	e.mu.Lock()
	events, err := e.sessionStore.LoadEvents(path)
	if err != nil {
		e.mu.Unlock()
		return SessionView{}, fmt.Errorf("loading session %s: %w", path, err)
	}

	e.sessionPath = path
	toolCallMap := make(map[string]session.ToolCall)
	for _, ev := range events {
		if ev.Type == session.EventAssistant {
			for _, tc := range ev.ToolCalls {
				toolCallMap[tc.ID] = tc
			}
		}
	}

	var records []agent.MessageRecord
	for _, ev := range events {
		switch ev.Type {
		case session.EventUser:
			records = append(records, agent.MessageRecord{Role: "user", Content: ev.Content})
		case session.EventAssistant:
			var tcRecs []agent.ToolCallRecord
			for _, tc := range ev.ToolCalls {
				tcRecs = append(tcRecs, agent.ToolCallRecord{
					ID:        tc.ID,
					Name:      tc.Function.Name,
					Arguments: tc.Function.Arguments,
				})
			}
			records = append(records, agent.MessageRecord{
				Role:      "assistant",
				Content:   ev.Content,
				ToolCalls: tcRecs,
			})
		case session.EventTool:
			toolName := "tool"
			if tc, ok := toolCallMap[ev.ToolCallID]; ok {
				toolName = tc.Function.Name
			}
			raw := ev.RawOutput
			if raw == "" {
				raw = ev.Content
			}
			records = append(records, agent.MessageRecord{
				Role:       "tool",
				ToolCallID: ev.ToolCallID,
				ToolName:   toolName,
				Content:    raw,
			})
		}
	}
	e.runner.RestoreMessages(records)
	e.sessionAllowedTools = make(map[string]bool)
	e.mu.Unlock()

	sessView := SessionView{
		FilePath: path,
	}

	for _, ev := range events {
		switch ev.Type {
		case session.EventUser:
			role := "user"
			content := ev.Content
			if strings.HasPrefix(content, "! ") {
				role = "bash"
				content = strings.TrimPrefix(content, "! ")
			}
			sessView.Events = append(sessView.Events, Event{
				Type:  EventTextDelta,
				Role:  role,
				Delta: content,
			})
		case session.EventAssistant:
			if ev.Content != "" {
				sessView.Events = append(sessView.Events, Event{
					Type:  EventTextDelta,
					Role:  "assistant",
					Delta: ev.Content,
				})
			}
		case session.EventTool:
			toolName := "tool"
			toolInput := ""
			if tc, ok := toolCallMap[ev.ToolCallID]; ok {
				toolName = tc.Function.Name
				toolInput = tc.Function.Arguments
			} else if ev.ToolCallID == "bash" {
				toolName = "bash"
			}
			summary := e.toolRegistry.Summarize(toolName, toolInput, ev.Content, ev.IsError)
			sessView.Events = append(sessView.Events, Event{
				Type:            EventToolFinished,
				Role:            "tool",
				ToolCallID:      ev.ToolCallID,
				ToolName:        toolName,
				ToolDisplayName: e.toolRegistry.DisplayName(toolName),
				ToolInput:       toolInput,
				ToolOutput:      ev.Content,
				ToolSummary:     summary,
				IsError:         ev.IsError,
			})
		}
	}

	return sessView, nil
}

package core_test

import (
	"context"
	"os"
	"strings"
	"testing"

	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/constants"
	"github.com/sapirrior/delta/internal/core"
	"github.com/sapirrior/delta/internal/session"
)

func TestEngineResumeSessionFidelity(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_resume_test_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	store := session.WithBaseDir(tempDir)
	filePath := store.SessionPath("session-fidelity", "2026-09-08")

	// Write session events with user, tool call, tool result, and assistant
	_ = store.AppendEvent(filePath, session.NowMeta("session_start", "test-model"))
	_ = store.AppendEvent(filePath, session.NowUser("User request"))
	_ = store.AppendEvent(filePath, session.NowAssistant("Running read_file...", []session.ToolCall{
		{
			ID:   "call_abc",
			Type: "function",
			Function: session.FunctionCall{
				Name:      constants.ToolReadFile,
				Arguments: `{"path":"main.go"}`,
			},
		},
	}))
	_ = store.AppendEvent(filePath, session.NowTool("call_abc", "package main\n\nfunc main() {}", false))
	_ = store.AppendEvent(filePath, session.NowAssistant("Done reading file.", nil))

	cfg := config.DefaultConfig()
	eng, err := core.NewEngine(cfg, tempDir)
	if err != nil {
		t.Fatalf("failed creating engine: %v", err)
	}

	viewSess, err := eng.ResumeSession(context.Background(), filePath)
	if err != nil {
		t.Fatalf("ResumeSession failed: %v", err)
	}

	if len(viewSess.Events) != 4 {
		t.Fatalf("expected 4 events, got %d", len(viewSess.Events))
	}

	if viewSess.Events[0].Role != "user" || viewSess.Events[0].Delta != "User request" {
		t.Errorf("unexpected event 0: %+v", viewSess.Events[0])
	}
	if viewSess.Events[1].Role != "assistant" || viewSess.Events[1].Delta != "Running read_file..." {
		t.Errorf("unexpected event 1: %+v", viewSess.Events[1])
	}
	if viewSess.Events[2].Role != "tool" || viewSess.Events[2].ToolName != constants.ToolReadFile {
		t.Errorf("unexpected event 2: %+v", viewSess.Events[2])
	}
	if !strings.Contains(viewSess.Events[2].ToolInput, "main.go") {
		t.Errorf("expected tool input with main.go, got %s", viewSess.Events[2].ToolInput)
	}
	if viewSess.Events[3].Role != "assistant" || viewSess.Events[3].Delta != "Done reading file." {
		t.Errorf("unexpected event 3: %+v", viewSess.Events[3])
	}
}

package core_test

import (
	"context"
	"os"
	"testing"
	"time"

	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/core"
)

func TestEngineLifecycleAndSessionApprovals(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_engine_test_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	cfg := config.DefaultConfig()
	cfg.Model = "test-model"

	eng, err := core.NewEngine(cfg, tempDir)
	if err != nil {
		t.Fatalf("failed to create engine: %v", err)
	}

	// 1. Check model name
	if eng.ModelName() != "test-model" {
		t.Errorf("expected test-model, got %s", eng.ModelName())
	}

	// 2. Test slash command listing
	cmds := eng.Commands()
	if len(cmds) < 5 {
		t.Errorf("expected at least 5 slash commands, got %d", len(cmds))
	}

	// 3. Test direct bash execution via core
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	err = eng.StartBash(ctx, "echo 'delta engine'")
	if err != nil {
		t.Fatalf("failed starting bash: %v", err)
	}

	select {
	case ev := <-eng.Events():
		if ev.Type != core.EventToolFinished {
			t.Errorf("expected EventToolFinished, got %v", ev.Type)
		}
		if ev.ToolName != "bash" {
			t.Errorf("expected bash tool name, got %s", ev.ToolName)
		}
	case <-time.After(3 * time.Second):
		t.Fatal("timed out waiting for bash completion event")
	}

	// 4. Test session creation and listing
	rows, err := eng.Sessions()
	if err != nil {
		t.Fatalf("failed listing sessions: %v", err)
	}
	if len(rows) < 1 {
		t.Errorf("expected at least 1 session row, got %d", len(rows))
	}

	// 5. Test session-scoped approval resolution
	eng.ResolveConfirmationForSession("run_command", true)
}

package core

import "github.com/sapirrior/delta/internal/tool"

// EventType categorizes high-level application events emitted to consumers.
type EventType int

const (
	EventTextDelta EventType = iota
	EventReasoningDelta
	EventToolStarted
	EventToolFinished
	EventConfirmationRequested
	EventTurnCompleted
	EventApplicationError
	EventSessionChanged
	EventModelChanged
)

// Event is a presentation-neutral event emitted by the core engine.
type Event struct {
	Type EventType

	// Text and reasoning stream deltas
	Delta string

	// Role for session resume presentation ("user", "assistant", "system", "tool", "thought", "bash")
	Role string

	// Tool execution info
	ToolName        string
	ToolDisplayName string
	ToolCallID      string
	ToolInput       string
	ToolOutput      string
	ToolSummary     string
	IsError         bool

	// Turn completion or error info
	TurnDone bool
	Error    error

	// Metadata updates
	SessionID string
	ModelName string
}

// Aliases for tool confirmation types at the core boundary
type (
	Confirmation    = tool.Confirmation
	PreviewKind     = tool.PreviewKind
	PreviewLineKind = tool.PreviewLineKind
	PreviewLine     = tool.PreviewLine
)

const (
	PreviewText = tool.PreviewText
	PreviewDiff = tool.PreviewDiff

	LineNeutral  = tool.LineNeutral
	LineAddition = tool.LineAddition
	LineDeletion = tool.LineDeletion
)

// Command represents a user-executable slash command.
type Command struct {
	Name        string
	Description string
}

// SessionRow is a presentation DTO for displaying session history.
type SessionRow struct {
	ID         string
	Date       string
	Title      string
	EventCount int
	FilePath   string
}

// SessionView holds data needed to resume and display a session in the TUI.
type SessionView struct {
	ID       string
	FilePath string
	Events   []Event
}

package core_test

import (
	"context"
	"strings"
	"testing"

	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/core"
	"github.com/sapirrior/delta/internal/tool"
	"github.com/sapirrior/delta/internal/tui"
	"github.com/sapirrior/delta/internal/tui/view"
)

// TestOCPExtensibility verifies that adding a new custom tool and slash command
// is supported purely through core/tool registration without editing any code in
// internal/tui or internal/tui/view.
func TestOCPExtensibility(t *testing.T) {
	tmpDir := t.TempDir()
	cfg := config.DefaultConfig()
	cfg.Model = "gemini-2.5-flash"

	engine, err := core.NewEngine(cfg, tmpDir)
	if err != nil {
		t.Fatalf("creating engine: %v", err)
	}

	// 1. Register a brand new custom slash command dynamically on the engine.
	customCommandExecuted := false
	customCmd := core.CommandDescriptor{
		Name:        "/custom_diagnostics",
		Description: "Run deep system diagnostics",
		Handler: func(ctx context.Context, e *core.Engine, args []string) error {
			customCommandExecuted = true
			return nil
		},
	}
	engine.RegisterCommand(customCmd)

	// Verify command is present in core.Backend
	var foundCmd bool
	for _, cmd := range engine.Commands() {
		if cmd.Name == "/custom_diagnostics" {
			foundCmd = true
			if cmd.Description != "Run deep system diagnostics" {
				t.Fatalf("unexpected command description: %s", cmd.Description)
			}
		}
	}
	if !foundCmd {
		t.Fatal("expected /custom_diagnostics to be returned by engine.Commands()")
	}

	// 2. Verify command discovery and palette rendering in view without view changes
	cmds := engine.Commands()
	var descList []core.CommandDescriptor
	for _, c := range cmds {
		descList = append(descList, core.CommandDescriptor{
			Name:        c.Name,
			Description: c.Description,
		})
	}
	filtered := core.FilterCommands(descList, "diagnostics")
	if len(filtered) != 1 || filtered[0].Name != "/custom_diagnostics" {
		t.Fatalf("expected 1 match for 'diagnostics', got: %+v", filtered)
	}

	paletteEntries := []view.CommandEntry{
		{Command: filtered[0].Name, Description: filtered[0].Description},
	}
	renderedPalette := view.RenderCommandPalette(paletteEntries, 0, 80)
	if !strings.Contains(renderedPalette, "/custom_diagnostics") {
		t.Fatalf("expected RenderCommandPalette to contain custom command, got: %s", renderedPalette)
	}

	// Execute command via Backend
	ctx := context.Background()
	if err := engine.ExecuteCommand(ctx, "/custom_diagnostics --verbose"); err != nil {
		t.Fatalf("failed executing custom command: %v", err)
	}
	if !customCommandExecuted {
		t.Fatal("expected customCommandExecuted to be true after executing via backend")
	}

	// 3. Register a brand new custom tool in tool.Registry
	customRegistry := tool.NewRegistry()
	customToolDef := tool.Definition{
		Name:                 "custom_analyzer",
		DisplayName:          "Custom Analyzer",
		RequiresConfirmation: true,
		Summarize: func(input, output string, isError bool) string {
			return "Analyzed custom artifacts successfully"
		},
		Confirmation: func(toolCallID, input string) tool.Confirmation {
			return tool.Confirmation{
				ID:          toolCallID,
				ToolName:    "custom_analyzer",
				ToolCallID:  toolCallID,
				Title:       "Custom Analyzer",
				Question:    "Run custom analyzer on repository?",
				PreviewKind: tool.PreviewText,
				Lines: []tool.PreviewLine{
					{Kind: tool.LineNeutral, Text: "Target: full workspace scan"},
				},
			}
		},
	}
	customRegistry.Register(customToolDef)

	// Verify tool metadata and formatting without hardcoded switches
	if !customRegistry.IsInteractive("custom_analyzer") {
		t.Fatal("expected custom_analyzer to require confirmation")
	}
	if customRegistry.DisplayName("custom_analyzer") != "Custom Analyzer" {
		t.Fatalf("expected 'Custom Analyzer', got %s", customRegistry.DisplayName("custom_analyzer"))
	}

	conf := customRegistry.Confirmation("custom_analyzer", "call_xyz", `{"target":"repo"}`)
	if conf.Question != "Run custom analyzer on repository?" {
		t.Fatalf("unexpected confirmation question: %s", conf.Question)
	}

	summary := customRegistry.Summarize("custom_analyzer", `{}`, `result`, false)
	if summary != "Analyzed custom artifacts successfully" {
		t.Fatalf("unexpected summary: %s", summary)
	}

	// 4. Verify TUI Presentation & View Render for the custom tool requires 0 TUI modifications
	appModel, err := tui.NewAppModel(engine, tmpDir)
	if err != nil {
		t.Fatalf("creating AppModel: %v", err)
	}

	// Simulate receiving EventToolFinished for the custom tool
	eventMsg := tui.CoreEventMsg(core.Event{
		Type:            core.EventToolFinished,
		Role:            "tool",
		ToolCallID:      "call_xyz",
		ToolName:        customToolDef.Name,
		ToolDisplayName: customRegistry.DisplayName(customToolDef.Name),
		ToolInput:       `{"target":"repo"}`,
		ToolOutput:      `result`,
		ToolSummary:     summary,
	})

	newModel, _ := appModel.Update(eventMsg)
	if newModel == nil {
		t.Fatal("expected non-model update")
	}

	// Verify View rendering handles confirmation cards for custom tool
	confView := view.ConfirmationView{
		ToolName: conf.ToolName,
		Title:    conf.Title,
		Question: conf.Question,
		Lines: []view.ConfirmationLine{
			{Kind: view.LineNeutral, Text: conf.Lines[0].Text},
		},
	}
	renderedCard := view.RenderToolConfirmCard(confView, 0, false, 0, 80)
	if !strings.Contains(renderedCard, "Custom Analyzer") || !strings.Contains(renderedCard, "Run custom analyzer on repository?") {
		t.Fatalf("expected RenderToolConfirmCard to display custom tool info, got: %s", renderedCard)
	}

	// Verify rendering transcript item with custom tool
	transcriptItems := []view.TranscriptItem{
		{
			Role:       "tool",
			Content:    "Custom Analyzer(repo)",
			ToolIcon:   "✔",
			ToolName:   "Custom Analyzer",
			ToolArg:    "repo",
			ToolOutput: summary,
		},
	}
	renderedTranscript, _, _ := view.RenderTranscriptIncremental(transcriptItems, 80, 0, "", 0)
	if !strings.Contains(renderedTranscript, "Custom Analyzer") || !strings.Contains(renderedTranscript, summary) {
		t.Fatalf("expected RenderTranscriptIncremental to format custom tool transcript correctly, got: %s", renderedTranscript)
	}
}

package core_test

import (
	"context"
	"os"
	"testing"

	"github.com/sapirrior/delta/internal/config"
	"github.com/sapirrior/delta/internal/core"
	"github.com/sapirrior/delta/internal/session"
)

func TestEngineResumeSessionFidelityAndToolHistory(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_resume_test_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	cfg := config.DefaultConfig()
	cfg.Model = "test-model"

	eng, err := core.NewEngine(cfg, tempDir)
	if err != nil {
		t.Fatalf("failed to create engine: %v", err)
	}

	// Manually write a session with user, assistant with tool calls, and tool result
	store := session.WithBaseDir(tempDir)
	sessPath := store.SessionPath("session-fidelity", "2026-09-08")

	_ = store.AppendEvent(sessPath, session.NowMeta("session_start", "test-model"))
	_ = store.AppendEvent(sessPath, session.NowUser("read main.go please"))
	_ = store.AppendEvent(sessPath, session.NowAssistant("Certainly, reading now.", []session.ToolCall{
		{
			ID:   "call_456",
			Type: "function",
			Function: session.FunctionCall{
				Name:      "read_file",
				Arguments: "{\"path\":\"main.go\"}",
			},
		},
	}))
	toolEv := session.NowTool("call_456", "package main\n\nfunc main() {}", false)
	toolEv.RawOutput = "package main\n\nfunc main() {}"
	_ = store.AppendEvent(sessPath, toolEv)
	_ = store.AppendEvent(sessPath, session.NowAssistant("File read successfully.", nil))

	// Resume the session through the Engine
	sessView, err := eng.ResumeSession(context.Background(), sessPath)
	if err != nil {
		t.Fatalf("failed to resume session: %v", err)
	}

	if sessView.FilePath != sessPath {
		t.Errorf("expected session path %s, got %s", sessPath, sessView.FilePath)
	}

	// Verify events in SessionView
	foundTool := false
	for _, ev := range sessView.Events {
		if ev.ToolCallID == "call_456" {
			foundTool = true
			if ev.ToolName != "read_file" {
				t.Errorf("expected read_file tool name, got %s", ev.ToolName)
			}
			if ev.ToolOutput != "package main\n\nfunc main() {}" {
				t.Errorf("expected faithful tool output, got %s", ev.ToolOutput)
			}
		}
	}
	if !foundTool {
		t.Error("tool event was not restored in session view")
	}
}

package session_test

import (
	"fmt"
	"os"
	"sync"
	"testing"

	"github.com/sapirrior/delta/internal/session"
)

func TestConcurrentAppendEvents(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_session_concurrent_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	store := session.WithBaseDir(tempDir)
	filePath := store.SessionPath("concurrent-session", "2026-09-08")

	const numWorkers = 20
	const eventsPerWorker = 25
	var wg sync.WaitGroup

	for w := 0; w < numWorkers; w++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for i := 0; i < eventsPerWorker; i++ {
				callID := fmt.Sprintf("call_%d_%d", workerID, i)
				ev := session.NowTool(callID, fmt.Sprintf("output-%d-%d", workerID, i), false)
				if err := store.AppendEvent(filePath, ev); err != nil {
					t.Errorf("worker %d failed appending: %v", workerID, err)
				}
			}
		}(w)
	}

	wg.Wait()

	events, err := store.LoadEvents(filePath)
	if err != nil {
		t.Fatalf("LoadEvents failed: %v", err)
	}

	expectedTotal := numWorkers * eventsPerWorker
	if len(events) != expectedTotal {
		t.Fatalf("expected %d events, got %d", expectedTotal, len(events))
	}
}

package session

import (
	"encoding/json"
	"time"

	"github.com/sapirrior/delta/internal/constants"
)

// ToolCall models an assistant tool call matching the Rust schema format.
type ToolCall struct {
	ID       string       `json:"id"`
	Type     string       `json:"type"` // "function"
	Function FunctionCall `json:"function"`
}

// FunctionCall models the function invocation inside a ToolCall.
type FunctionCall struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

// EventType distinguishes the session event payload.
type EventType string

const (
	EventMeta      EventType = constants.SessionEventMeta
	EventUser      EventType = constants.SessionEventUser
	EventAssistant EventType = constants.SessionEventAssistant
	EventTool      EventType = constants.SessionEventTool
)

// SessionEvent matches the versioned JSONL schema (`{"v":1,...}`) from the Rust build.
type SessionEvent struct {
	Type EventType `json:"t"`
	V    int       `json:"v"`
	TS   string    `json:"ts"`

	// Meta event fields
	Event string `json:"event,omitempty"`
	Model string `json:"model,omitempty"`

	// User & Assistant common content
	Content string `json:"content,omitempty"`

	// Assistant tool calls
	ToolCalls []ToolCall `json:"tool_calls,omitempty"`

	// Tool event fields
	ToolCallID   string `json:"tool_call_id,omitempty"`
	IsError      bool   `json:"is_error,omitempty"`
	RawOutput    string `json:"raw_output,omitempty"`
	ErrorMessage string `json:"error_message,omitempty"`
}

// NowMeta creates a session start/metadata event.
func NowMeta(event, model string) SessionEvent {
	return SessionEvent{
		Type:  EventMeta,
		V:     constants.SessionSchemaVersion,
		TS:    time.Now().UTC().Format(time.RFC3339),
		Event: event,
		Model: model,
	}
}

// NowUser creates a user message event.
func NowUser(content string) SessionEvent {
	return SessionEvent{
		Type:    EventUser,
		V:       constants.SessionSchemaVersion,
		TS:      time.Now().UTC().Format(time.RFC3339),
		Content: content,
	}
}

// NowAssistant creates an assistant message event with optional tool calls.
func NowAssistant(content string, toolCalls []ToolCall) SessionEvent {
	return SessionEvent{
		Type:      EventAssistant,
		V:         constants.SessionSchemaVersion,
		TS:        time.Now().UTC().Format(time.RFC3339),
		Content:   content,
		ToolCalls: toolCalls,
	}
}

// NowTool creates a tool execution result event.
func NowTool(toolCallID, content string, isError bool) SessionEvent {
	return SessionEvent{
		Type:       EventTool,
		V:          constants.SessionSchemaVersion,
		TS:         time.Now().UTC().Format(time.RFC3339),
		ToolCallID: toolCallID,
		Content:    content,
		RawOutput:  content,
		IsError:    isError,
	}
}

// UnmarshalJSON handles parsing JSON into SessionEvent safely.
func ParseEvent(line []byte) (SessionEvent, error) {
	var ev SessionEvent
	err := json.Unmarshal(line, &ev)
	return ev, err
}

package session_test

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/sapirrior/delta/internal/session"
)

func TestSessionToolRawOutputAndLexicalPreservation(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_schema_test_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	store := session.WithBaseDir(tempDir)
	sessPath := store.SessionPath("test-sess", "2026-09-08")

	rawToolOutput := "{\n  \"status\": \"ok\",\n  \"count\":   42\n}"
	toolEv := session.NowTool("call_123", rawToolOutput, false)
	toolEv.RawOutput = rawToolOutput

	if err := store.AppendEvent(sessPath, toolEv); err != nil {
		t.Fatalf("failed to append tool event: %v", err)
	}

	loaded, err := store.LoadEvents(sessPath)
	if err != nil {
		t.Fatalf("failed loading events: %v", err)
	}
	if len(loaded) != 1 {
		t.Fatalf("expected 1 event, got %d", len(loaded))
	}

	resEv := loaded[0]
	if resEv.RawOutput != rawToolOutput {
		t.Errorf("raw output lexical mismatch:\nexpected:\n%q\ngot:\n%q", rawToolOutput, resEv.RawOutput)
	}

	// Verify line format
	content, _ := os.ReadFile(sessPath)
	lines := strings.Split(strings.TrimSpace(string(content)), "\n")
	if len(lines) != 1 {
		t.Errorf("expected exactly 1 line in jsonl, got %d", len(lines))
	}
	var rawMap map[string]any
	if err := json.Unmarshal([]byte(lines[0]), &rawMap); err != nil {
		t.Errorf("jsonl line is not valid JSON: %v", err)
	}
}

package session

import (
	"bufio"
	"crypto/rand"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

// SessionStore manages sessions stored under ~/.delta/sessions/YYYY-MM-DD/<session_id>.jsonl
// It serializes concurrent appends safely with an internal mutex.
type SessionStore struct {
	mu      sync.Mutex
	baseDir string
}

// NewStore initializes SessionStore pointing to ~/.delta/sessions
func NewStore() (*SessionStore, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get user home directory: %w", err)
	}
	baseDir := filepath.Join(home, ".delta", "sessions")
	return &SessionStore{baseDir: baseDir}, nil
}

// WithBaseDir allows customizing the session storage root directory (e.g. for testing)
func WithBaseDir(dir string) *SessionStore {
	return &SessionStore{baseDir: dir}
}

// GenerateSessionID returns a cryptographically random UUID v4 string.
func GenerateSessionID() string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		// Fallback to timestamp-based unique string if system entropy fails
		return fmt.Sprintf("fallback-%x-%x", time.Now().UnixNano(), os.Getpid())
	}
	b[6] = (b[6] & 0x0f) | 0x40 // Version 4
	b[8] = (b[8] & 0x3f) | 0x80 // Variant RFC4122
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

// SessionPath returns the path to a session's JSONL file.
// If dateStr is empty, current UTC date is formatted as YYYY-MM-DD.
func (s *SessionStore) SessionPath(sessionID string, dateStr string) string {
	if dateStr == "" {
		dateStr = time.Now().UTC().Format("2006-01-02")
	}
	return filepath.Join(s.baseDir, dateStr, fmt.Sprintf("%s.jsonl", sessionID))
}

// AppendEvent writes one SessionEvent to the given file path as a single JSON line.
// Safe for concurrent callers via internal mutex synchronization.
func (s *SessionStore) AppendEvent(filePath string, event SessionEvent) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	parent := filepath.Dir(filePath)
	if err := os.MkdirAll(parent, 0o755); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	f, err := os.OpenFile(filePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return fmt.Errorf("failed to open session file: %w", err)
	}
	defer f.Close()

	data, err := json.Marshal(event)
	if err != nil {
		return fmt.Errorf("failed to marshal session event: %w", err)
	}
	data = append(data, '\n')

	if _, err := f.Write(data); err != nil {
		return fmt.Errorf("failed to write session event: %w", err)
	}
	return f.Sync()
}

// LoadEvents reads all valid events from the session file.
// Follows AGENTS.md Invariant: Gracefully tolerates truncated trailing lines while rejecting middle corruptions.
func (s *SessionStore) LoadEvents(filePath string) ([]SessionEvent, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	f, err := os.Open(filePath)
	if err != nil {
		if os.IsNotExist(err) {
			return []SessionEvent{}, nil
		}
		return nil, fmt.Errorf("failed to open session file: %w", err)
	}
	defer f.Close()

	var events []SessionEvent
	reader := bufio.NewReader(f)
	lineNum := 0

	for {
		lineNum++
		lineBytes, err := reader.ReadBytes('\n')

		// End of file handling
		if err == io.EOF && len(lineBytes) == 0 {
			break
		}

		// AGENTS.md Invariant: Tolerant EOF recovery for truncated trailing bytes on crash
		if err == io.EOF && len(lineBytes) > 0 {
			lineStr := strings.TrimSpace(string(lineBytes))
			if lineStr != "" {
				ev, parseErr := ParseEvent([]byte(lineStr))
				if parseErr == nil {
					events = append(events, ev)
				}
				// If incomplete / invalid JSON at EOF, ignore silently
			}
			break
		}

		if err != nil {
			return nil, fmt.Errorf("read error on line %d: %w", lineNum, err)
		}

		lineStr := strings.TrimSpace(string(lineBytes))
		if lineStr == "" {
			continue
		}

		ev, parseErr := ParseEvent([]byte(lineStr))
		if parseErr != nil {
			// Check if we are at EOF despite no explicit EOF flag yet
			peek, peekErr := reader.Peek(1)
			if peekErr == io.EOF || len(peek) == 0 {
				// Last line is corrupt/truncated -> tolerate and recover intact prefix
				break
			}
			return nil, fmt.Errorf("corrupt line %d in session file: %w", lineNum, parseErr)
		}

		events = append(events, ev)
	}

	return events, nil
}

// SessionInfo holds metadata about an existing session on disk
type SessionInfo struct {
	ID      string
	Path    string
	Date    string
	ModTime time.Time
}

// ListSessions scans baseDir for all *.jsonl files across YYYY-MM-DD subdirectories,
// sorted latest-first by date/session.
func (s *SessionStore) ListSessions() ([]SessionInfo, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	var sessions []SessionInfo
	if _, err := os.Stat(s.baseDir); os.IsNotExist(err) {
		return sessions, nil
	}

	entries, err := os.ReadDir(s.baseDir)
	if err != nil {
		return nil, fmt.Errorf("failed to read session base directory: %w", err)
	}

	for _, dateEntry := range entries {
		if !dateEntry.IsDir() {
			continue
		}
		dateDir := filepath.Join(s.baseDir, dateEntry.Name())
		files, err := os.ReadDir(dateDir)
		if err != nil {
			continue
		}

		for _, file := range files {
			if file.IsDir() || !strings.HasSuffix(file.Name(), ".jsonl") {
				continue
			}
			info, err := file.Info()
			if err != nil {
				continue
			}
			id := strings.TrimSuffix(file.Name(), ".jsonl")
			sessions = append(sessions, SessionInfo{
				ID:      id,
				Path:    filepath.Join(dateDir, file.Name()),
				Date:    dateEntry.Name(),
				ModTime: info.ModTime(),
			})
		}
	}

	// Sort latest date and time first
	sort.Slice(sessions, func(i, j int) bool {
		if sessions[i].Date != sessions[j].Date {
			return sessions[i].Date > sessions[j].Date
		}
		return sessions[i].ModTime.After(sessions[j].ModTime)
	})

	return sessions, nil
}

package session_test

import (
	"os"
	"testing"

	"github.com/sapirrior/delta/internal/session"
)

func TestSessionAppendLoadAndTruncatedRecovery(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_session_test_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	store := session.WithBaseDir(tempDir)
	sessionID := "test-session-123"
	filePath := store.SessionPath(sessionID, "2026-09-07")

	meta := session.NowMeta("session_start", "gpt-4o")
	user := session.NowUser("Hello delta!")
	assistant := session.NowAssistant("Hello! How can I help?", []session.ToolCall{
		{
			ID:   "call_123",
			Type: "function",
			Function: session.FunctionCall{
				Name:      "read_file",
				Arguments: `{"path":"main.go"}`,
			},
		},
	})
	toolEv := session.NowTool("call_123", "package main...", false)

	if err := store.AppendEvent(filePath, meta); err != nil {
		t.Fatalf("failed to append meta: %v", err)
	}
	if err := store.AppendEvent(filePath, user); err != nil {
		t.Fatalf("failed to append user: %v", err)
	}
	if err := store.AppendEvent(filePath, assistant); err != nil {
		t.Fatalf("failed to append assistant: %v", err)
	}
	if err := store.AppendEvent(filePath, toolEv); err != nil {
		t.Fatalf("failed to append tool event: %v", err)
	}

	// Write a truncated/corrupt line simulating a crash mid-write
	f, err := os.OpenFile(filePath, os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatalf("failed to open file for corrupt append: %v", err)
	}
	if _, err := f.WriteString(`{"v":1,"t":"user","ts":"2026-09-07T12:00:00Z","con`); err != nil {
		f.Close()
		t.Fatalf("failed to write truncated bytes: %v", err)
	}
	_ = f.Close()

	// Load events — truncated line must be silently ignored, returning the 4 intact ones
	events, err := store.LoadEvents(filePath)
	if err != nil {
		t.Fatalf("LoadEvents failed: %v", err)
	}

	if len(events) != 4 {
		t.Fatalf("expected 4 events, got %d", len(events))
	}

	if events[0].Type != session.EventMeta || events[0].Model != "gpt-4o" {
		t.Errorf("unexpected event 0: %+v", events[0])
	}
	if events[1].Type != session.EventUser || events[1].Content != "Hello delta!" {
		t.Errorf("unexpected event 1: %+v", events[1])
	}
	if events[2].Type != session.EventAssistant || len(events[2].ToolCalls) != 1 {
		t.Errorf("unexpected event 2: %+v", events[2])
	}
	if events[3].Type != session.EventTool || events[3].ToolCallID != "call_123" {
		t.Errorf("unexpected event 3: %+v", events[3])
	}

	// Verify ListSessions finds the session
	sessions, err := store.ListSessions()
	if err != nil {
		t.Fatalf("ListSessions failed: %v", err)
	}
	if len(sessions) != 1 {
		t.Fatalf("expected 1 session listed, got %d", len(sessions))
	}
	if sessions[0].ID != sessionID {
		t.Errorf("expected session ID %s, got %s", sessionID, sessions[0].ID)
	}
	if sessions[0].Date != "2026-09-07" {
		t.Errorf("expected date 2026-09-07, got %s", sessions[0].Date)
	}
}

func TestGenerateSessionID(t *testing.T) {
	id1 := session.GenerateSessionID()
	id2 := session.GenerateSessionID()
	if id1 == "" || id2 == "" || id1 == id2 {
		t.Errorf("generated invalid or identical IDs: %s, %s", id1, id2)
	}
	if len(id1) != 36 {
		t.Errorf("expected UUID format length 36, got %d (%s)", len(id1), id1)
	}
}

package shell

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os/exec"
	"strings"
	"sync"
	"time"
)

const (
	DefaultCommandTimeout = 120 * time.Second
	DefaultTailLines      = 15
)

// Result contains the outcome of a shell execution.
type Result struct {
	Output   string
	ExitCode int
	Error    error
}

// Runner executes shell commands with context cancellation, timeout, and bounded streaming line buffering.
type Runner struct {
	Cwd string
}

// NewRunner creates a new shell runner for the given working directory.
func NewRunner(cwd string) *Runner {
	return &Runner{Cwd: cwd}
}

// Run executes a shell command with a bounded timeout and optional line callback.
func (r *Runner) Run(ctx context.Context, command string, onLine func(line string)) (Result, error) {
	execCtx := ctx
	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
		var cancel context.CancelFunc
		execCtx, cancel = context.WithTimeout(ctx, DefaultCommandTimeout)
		defer cancel()
	}

	cmd := exec.CommandContext(execCtx, "sh", "-c", command)
	cmd.Dir = r.Cwd

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		return Result{Error: err}, err
	}
	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		return Result{Error: err}, err
	}

	if err := cmd.Start(); err != nil {
		return Result{Error: err}, err
	}

	var mu sync.Mutex
	var allLines []string

	readPipe := func(reader io.Reader) {
		scanner := bufio.NewScanner(reader)
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)

		for scanner.Scan() {
			line := scanner.Text()
			mu.Lock()
			allLines = append(allLines, line)
			mu.Unlock()
			if onLine != nil {
				onLine(line)
			}
		}
		if scanErr := scanner.Err(); scanErr != nil {
			mu.Lock()
			allLines = append(allLines, fmt.Sprintf("[scanner error: %v]", scanErr))
			mu.Unlock()
		}
	}

	var wg sync.WaitGroup
	wg.Add(2)
	go func() {
		defer wg.Done()
		readPipe(stdoutPipe)
	}()
	go func() {
		defer wg.Done()
		readPipe(stderrPipe)
	}()

	wg.Wait()
	waitErr := cmd.Wait()

	mu.Lock()
	fullOutput := strings.Join(allLines, "\n")
	mu.Unlock()

	exitCode := 0
	if execCtx.Err() == context.Canceled {
		return Result{
			Output: fullOutput,
			Error:  fmt.Errorf("command cancelled by user"),
		}, nil
	} else if execCtx.Err() == context.DeadlineExceeded {
		return Result{
			Output: fullOutput,
			Error:  fmt.Errorf("command timed out after %v", DefaultCommandTimeout),
		}, nil
	}

	if waitErr != nil {
		if exitErr, ok := waitErr.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		}
	}

	return Result{
		Output:   fullOutput,
		ExitCode: exitCode,
		Error:    waitErr,
	}, nil
}

package shell_test

import (
	"context"
	"strings"
	"testing"
	"time"

	"github.com/sapirrior/delta/internal/shell"
)

func TestShellRunnerExecution(t *testing.T) {
	r := shell.NewRunner(".")

	// 1. Success execution with output
	ctx := context.Background()
	res, err := r.Run(ctx, "echo 'hello shell'", nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if strings.TrimSpace(res.Output) != "hello shell" {
		t.Errorf("expected 'hello shell', got %q", res.Output)
	}
	if res.ExitCode != 0 {
		t.Errorf("expected exit code 0, got %d", res.ExitCode)
	}

	// 2. Non-zero exit code
	res, err = r.Run(ctx, "sh -c 'exit 42'", nil)
	if res.ExitCode != 42 {
		t.Errorf("expected exit code 42, got %d (err: %v)", res.ExitCode, err)
	}

	// 3. Cancellation unblocks
	cancelCtx, cancel := context.WithCancel(context.Background())
	time.AfterFunc(50*time.Millisecond, cancel)
	res, _ = r.Run(cancelCtx, "sleep 5", nil)
	if res.Error == nil || !strings.Contains(res.Error.Error(), "cancelled") {
		t.Errorf("expected cancelled error, got: %v", res.Error)
	}

	// 4. Line callback works
	var lines []string
	_, err = r.Run(ctx, "echo 'line 1'; echo 'line 2'", func(l string) {
		lines = append(lines, l)
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(lines) != 2 || lines[0] != "line 1" || lines[1] != "line 2" {
		t.Errorf("unexpected callback lines: %v", lines)
	}
}

package tool

// Confirmation encapsulates a pending action that requires user approval.
type Confirmation struct {
	ID          string
	ToolName    string
	ToolCallID  string
	RawArgs     string
	Title       string
	Subtitle    string
	Question    string
	PreviewKind PreviewKind
	Lines       []PreviewLine
}

// PreviewKind describes how preview lines should be presented.
type PreviewKind int

const (
	PreviewText PreviewKind = iota
	PreviewDiff
)

// PreviewLineKind denotes the semantic role of a preview line.
type PreviewLineKind int

const (
	LineNeutral PreviewLineKind = iota
	LineAddition
	LineDeletion
)

// PreviewLine represents a single line in a confirmation preview.
type PreviewLine struct {
	Kind       PreviewLineKind
	LineNumber int
	Prefix     string
	Text       string
}

package tool

import (
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/zendev-sh/goai"
)

// Well-known tool identifiers
const (
	ReadFile   = "read_file"
	WriteFile  = "write_file"
	EditFile   = "edit_file"
	ListDir    = "list_dir"
	SearchText = "search_text"
	Find       = "find"
	RunCommand = "run_command"
	WebFetch   = "web_fetch"
	Schedule   = "schedule"
)

// Definition describes a tool, its confirmation policy, summaries, and constructor.
type Definition struct {
	Name                 string
	Description          string
	DisplayName          string
	RequiresConfirmation bool

	// Build returns the underlying goai.Tool instance
	Build func(workspaceRoot string) goai.Tool

	// Summarize produces a concise execution summary
	Summarize func(input, output string, isError bool) string

	// Confirmation produces presentation-neutral preview data
	Confirmation func(toolCallID, input string) Confirmation
}

// Registry stores and discovers available tool definitions.
type Registry struct {
	tools map[string]Definition
	order []string
}

// NewRegistry creates a new empty tool registry.
func NewRegistry() *Registry {
	return &Registry{
		tools: make(map[string]Definition),
	}
}

// Register registers a tool definition.
func (r *Registry) Register(def Definition) {
	if _, exists := r.tools[def.Name]; !exists {
		r.order = append(r.order, def.Name)
	}
	r.tools[def.Name] = def
}

// Get returns the definition for a tool name.
func (r *Registry) Get(name string) (Definition, bool) {
	def, ok := r.tools[name]
	return def, ok
}

// IsInteractive reports whether a tool requires confirmation.
func (r *Registry) IsInteractive(name string) bool {
	if def, ok := r.tools[name]; ok {
		return def.RequiresConfirmation
	}
	return false
}

// DisplayName returns a human-friendly name for a tool.
func (r *Registry) DisplayName(name string) string {
	if def, ok := r.tools[name]; ok && def.DisplayName != "" {
		return def.DisplayName
	}
	if len(name) > 0 {
		return strings.ToUpper(name[:1]) + name[1:]
	}
	return name
}

// Summarize produces a summary using the tool definition or fallback.
func (r *Registry) Summarize(name, input, output string, isError bool) string {
	if isError {
		if strings.Contains(output, "declined") {
			return "Interrupted · What should Delta do instead?"
		}
		if output != "" {
			return firstLine(output)
		}
		return "Error"
	}

	if def, ok := r.tools[name]; ok && def.Summarize != nil {
		return def.Summarize(input, output, isError)
	}

	trimmed := strings.TrimSpace(output)
	if trimmed == "" {
		return "(Done)"
	}
	return firstLine(trimmed)
}

// Confirmation creates a neutral confirmation DTO.
func (r *Registry) Confirmation(name, toolCallID, input string) Confirmation {
	if def, ok := r.tools[name]; ok && def.Confirmation != nil {
		return def.Confirmation(toolCallID, input)
	}

	return Confirmation{
		ID:          toolCallID,
		ToolName:    name,
		ToolCallID:  toolCallID,
		RawArgs:     input,
		Title:       name,
		Question:    "Do you want to proceed?",
		PreviewKind: PreviewText,
		Lines:       []PreviewLine{{Kind: LineNeutral, Text: input}},
	}
}

// BuildTools constructs goai.Tool implementations for all registered tools.
func (r *Registry) BuildTools(workspaceRoot string) []goai.Tool {
	var result []goai.Tool
	for _, name := range r.order {
		def := r.tools[name]
		if def.Build != nil {
			result = append(result, def.Build(workspaceRoot))
		}
	}
	return result
}

func firstLine(s string) string {
	parts := strings.SplitN(s, "\n", 2)
	return parts[0]
}

// Helper to parse JSON input
func parseJSON(s string) map[string]any {
	var obj map[string]any
	_ = json.Unmarshal([]byte(s), &obj)
	return obj
}

// DefaultRegistry returns the catalog of all standard Delta tools.
func DefaultRegistry(
	readFile, writeFile, editFile, listDir, searchText, find, runCmd func(string) goai.Tool,
	webFetch, schedule func() goai.Tool,
) *Registry {
	reg := NewRegistry()

	// 1. read_file
	reg.Register(Definition{
		Name:        ReadFile,
		DisplayName: "Read",
		Build:       readFile,
		Summarize: func(input, output string, isError bool) string {
			trimmed := strings.TrimSpace(output)
			if trimmed == "" {
				return "(empty file)"
			}
			lines := strings.Split(trimmed, "\n")
			return fmt.Sprintf("Read %d lines", len(lines))
		},
	})

	// 2. write_file
	reg.Register(Definition{
		Name:                 WriteFile,
		DisplayName:          "Write",
		RequiresConfirmation: true,
		Build:                writeFile,
		Summarize: func(input, output string, isError bool) string {
			obj := parseJSON(input)
			path, _ := obj["path"].(string)
			content, _ := obj["content"].(string)
			lineCount := len(strings.Split(content, "\n"))
			if len(content) == 0 {
				lineCount = 0
			}
			if path != "" {
				return fmt.Sprintf("Wrote %d lines to %s", lineCount, path)
			}
			return fmt.Sprintf("Wrote %d lines", lineCount)
		},
		Confirmation: func(toolCallID, input string) Confirmation {
			obj := parseJSON(input)
			path, _ := obj["path"].(string)
			content, _ := obj["content"].(string)
			base := filepath.Base(path)

			conf := Confirmation{
				ID:          toolCallID,
				ToolName:    WriteFile,
				ToolCallID:  toolCallID,
				RawArgs:     input,
				Title:       "Create file",
				Subtitle:    path,
				Question:    fmt.Sprintf("Do you want to create %s?", base),
				PreviewKind: PreviewDiff,
			}
			for i, l := range strings.Split(content, "\n") {
				conf.Lines = append(conf.Lines, PreviewLine{
					Kind:       LineAddition,
					LineNumber: i + 1,
					Prefix:     "+",
					Text:       l,
				})
			}
			return conf
		},
	})

	// 3. edit_file
	reg.Register(Definition{
		Name:                 EditFile,
		DisplayName:          "Update",
		RequiresConfirmation: true,
		Build:                editFile,
		Summarize: func(input, output string, isError bool) string {
			obj := parseJSON(input)
			target, _ := obj["target_content"].(string)
			repl, _ := obj["replacement_content"].(string)
			numDel := len(strings.Split(target, "\n"))
			if len(target) == 0 {
				numDel = 0
			}
			numAdd := len(strings.Split(repl, "\n"))
			if len(repl) == 0 {
				numAdd = 0
			}
			return fmt.Sprintf("Added %d lines, removed %d lines", numAdd, numDel)
		},
		Confirmation: func(toolCallID, input string) Confirmation {
			obj := parseJSON(input)
			path, _ := obj["path"].(string)
			target, _ := obj["target_content"].(string)
			repl, _ := obj["replacement_content"].(string)
			base := filepath.Base(path)

			conf := Confirmation{
				ID:          toolCallID,
				ToolName:    EditFile,
				ToolCallID:  toolCallID,
				RawArgs:     input,
				Title:       "Edit file",
				Subtitle:    path,
				Question:    fmt.Sprintf("Do you want to make this edit to %s?", base),
				PreviewKind: PreviewDiff,
			}
			for i, l := range strings.Split(target, "\n") {
				conf.Lines = append(conf.Lines, PreviewLine{
					Kind:       LineDeletion,
					LineNumber: i + 1,
					Prefix:     "-",
					Text:       l,
				})
			}
			for i, l := range strings.Split(repl, "\n") {
				conf.Lines = append(conf.Lines, PreviewLine{
					Kind:       LineAddition,
					LineNumber: i + 1,
					Prefix:     "+",
					Text:       l,
				})
			}
			return conf
		},
	})

	// 4. list_dir
	reg.Register(Definition{
		Name:        ListDir,
		DisplayName: "List",
		Build:       listDir,
		Summarize: func(input, output string, isError bool) string {
			trimmed := strings.TrimSpace(output)
			if trimmed == "" {
				return "(empty directory)"
			}
			lines := strings.Split(trimmed, "\n")
			return fmt.Sprintf("Listed %d items", len(lines))
		},
	})

	// 5. search_text
	reg.Register(Definition{
		Name:        SearchText,
		DisplayName: "Search",
		Build:       searchText,
	})

	// 6. find
	reg.Register(Definition{
		Name:        Find,
		DisplayName: "Find",
		Build:       find,
	})

	// 7. run_command
	reg.Register(Definition{
		Name:                 RunCommand,
		DisplayName:          "Bash",
		RequiresConfirmation: true,
		Build:                runCmd,
		Summarize: func(input, output string, isError bool) string {
			trimmed := strings.TrimSpace(output)
			if trimmed == "" {
				return "(No output)"
			}
			lines := strings.Split(trimmed, "\n")
			if len(lines) == 1 {
				return lines[0]
			}
			return fmt.Sprintf("%s (%d lines)", lines[0], len(lines))
		},
		Confirmation: func(toolCallID, input string) Confirmation {
			obj := parseJSON(input)
			cmd, _ := obj["command"].(string)

			conf := Confirmation{
				ID:          toolCallID,
				ToolName:    RunCommand,
				ToolCallID:  toolCallID,
				RawArgs:     input,
				Title:       "Bash command",
				Question:    "Do you want to proceed?",
				PreviewKind: PreviewText,
			}
			for _, l := range strings.Split(cmd, "\n") {
				conf.Lines = append(conf.Lines, PreviewLine{
					Kind: LineNeutral,
					Text: l,
				})
			}
			return conf
		},
	})

	// 8. web_fetch
	reg.Register(Definition{
		Name:        WebFetch,
		DisplayName: "Web",
		Build:       func(string) goai.Tool { return webFetch() },
	})

	// 9. schedule
	reg.Register(Definition{
		Name:        Schedule,
		DisplayName: "Schedule",
		Build:       func(string) goai.Tool { return schedule() },
	})

	return reg
}

package tool_test

import (
	"context"
	"testing"

	"github.com/sapirrior/delta/internal/agent"
	"github.com/sapirrior/delta/internal/constants"
	"github.com/sapirrior/delta/internal/tool"
	"github.com/zendev-sh/goai"
)

type customAnalyzerParams struct {
	Target string `json:"target"`
}

func TestExtensibleToolCatalogRegistration(t *testing.T) {
	reg := agent.DefaultToolRegistry()

	// 1. Verify default tools are present
	if !reg.IsInteractive(tool.RunCommand) {
		t.Errorf("expected run_command to be interactive")
	}
	if !reg.IsInteractive(tool.WriteFile) {
		t.Errorf("expected write_file to be interactive")
	}
	if !reg.IsInteractive(tool.EditFile) {
		t.Errorf("expected edit_file to be interactive")
	}
	if reg.IsInteractive(tool.ReadFile) {
		t.Errorf("expected read_file NOT to be interactive")
	}

	// 2. Register custom test tool without modifying any TUI or renderer files
	reg.Register(tool.Definition{
		Name:                 "custom_analyzer",
		DisplayName:          "Analyzer",
		RequiresConfirmation: true,
		Build: func(workspaceRoot string) goai.Tool {
			return goai.NewTool("custom_analyzer", "analyzes files", func(ctx context.Context, input customAnalyzerParams) (string, error) {
				return "analyzed", nil
			})
		},
		Summarize: func(input, output string, isError bool) string {
			if isError {
				return "analysis failed"
			}
			return "Analysis completed successfully"
		},
		Confirmation: func(toolCallID, input string) tool.Confirmation {
			return tool.Confirmation{
				ID:          toolCallID,
				ToolName:    "custom_analyzer",
				ToolCallID:  toolCallID,
				Title:       "Custom Analyzer",
				Question:    "Run custom analyzer?",
				PreviewKind: tool.PreviewText,
				Lines:       []tool.PreviewLine{{Kind: tool.LineNeutral, Text: "analysis target"}},
			}
		},
	})

	// 3. Verify registry lookup and contracts
	if !reg.IsInteractive("custom_analyzer") {
		t.Errorf("expected custom_analyzer to be interactive")
	}
	if reg.DisplayName("custom_analyzer") != "Analyzer" {
		t.Errorf("expected Analyzer display name, got %s", reg.DisplayName("custom_analyzer"))
	}
	summary := reg.Summarize("custom_analyzer", "", "ok", false)
	if summary != "Analysis completed successfully" {
		t.Errorf("unexpected summary: %s", summary)
	}
	conf := reg.Confirmation("custom_analyzer", "call_xyz", `{"target":"."}`)
	if conf.Title != "Custom Analyzer" || conf.Question != "Run custom analyzer?" {
		t.Errorf("unexpected confirmation DTO: %+v", conf)
	}

	// 4. Negative test: unknown tool falls back gracefully
	if reg.IsInteractive("unknown_tool_xyz") {
		t.Errorf("unknown tool should not be interactive")
	}
	if reg.DisplayName("unknown_tool_xyz") != "Unknown_tool_xyz" {
		t.Errorf("unexpected fallback display name: %s", reg.DisplayName("unknown_tool_xyz"))
	}
	fallbackSummary := reg.Summarize("unknown_tool_xyz", "", "first line\nsecond line", false)
	if fallbackSummary != "first line" {
		t.Errorf("expected first line fallback, got %s", fallbackSummary)
	}
	fallbackConf := reg.Confirmation("unknown_tool_xyz", "call_unknown", "raw args")
	if fallbackConf.Title != "unknown_tool_xyz" {
		t.Errorf("unexpected fallback confirmation title: %s", fallbackConf.Title)
	}
}

func TestCharacterizationSummarizeToolOutputInCatalog(t *testing.T) {
	reg := agent.DefaultToolRegistry()

	tests := []struct {
		name     string
		tool     string
		input    string
		output   string
		isError  bool
		expected string
	}{
		{
			name:     "error declined",
			tool:     constants.ToolRunCommand,
			input:    `{"command":"ls"}`,
			output:   "user declined confirmation",
			isError:  true,
			expected: "Interrupted · What should Delta do instead?",
		},
		{
			name:     "generic error with message",
			tool:     constants.ToolRunCommand,
			input:    `{"command":"ls"}`,
			output:   "command failed: exit status 1\nsecond line",
			isError:  true,
			expected: "command failed: exit status 1",
		},
		{
			name:     "generic error empty output",
			tool:     constants.ToolRunCommand,
			input:    `{"command":"ls"}`,
			output:   "",
			isError:  true,
			expected: "Error",
		},
		{
			name:     "run_command single line",
			tool:     constants.ToolRunCommand,
			input:    `{"command":"echo hi"}`,
			output:   "hi",
			isError:  false,
			expected: "hi",
		},
		{
			name:     "run_command multiline",
			tool:     constants.ToolRunCommand,
			input:    `{"command":"ls"}`,
			output:   "file1\nfile2\nfile3",
			isError:  false,
			expected: "file1 (3 lines)",
		},
		{
			name:     "write_file summary",
			tool:     constants.ToolWriteFile,
			input:    `{"path":"test.txt","content":"a\nb\nc"}`,
			output:   "success",
			isError:  false,
			expected: "Wrote 3 lines to test.txt",
		},
		{
			name:     "edit_file summary",
			tool:     constants.ToolEditFile,
			input:    `{"path":"test.txt","target_content":"old\nlines","replacement_content":"new"}`,
			output:   "success",
			isError:  false,
			expected: "Added 1 lines, removed 2 lines",
		},
		{
			name:     "read_file summary",
			tool:     constants.ToolReadFile,
			input:    `{"path":"test.txt"}`,
			output:   "line 1\nline 2\nline 3\nline 4",
			isError:  false,
			expected: "Read 4 lines",
		},
		{
			name:     "list_dir summary",
			tool:     constants.ToolListDir,
			input:    `{"path":"."}`,
			output:   "a\nb",
			isError:  false,
			expected: "Listed 2 items",
		},
		{
			name:     "unknown tool summary",
			tool:     "custom_tool",
			input:    `{}`,
			output:   "custom result line 1\nline 2",
			isError:  false,
			expected: "custom result line 1",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := reg.Summarize(tc.tool, tc.input, tc.output, tc.isError)
			if got != tc.expected {
				t.Errorf("expected %q, got %q", tc.expected, got)
			}
		})
	}
}

package builtins

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// EditFileTool replaces exact target string snippets in workspace files atomically.
func EditFileTool(workspaceRoot string) goai.Tool {
	type params struct {
		Path               string `json:"path" jsonschema:"description=The workspace-relative path of the file to edit."`
		TargetContent      string `json:"target_content" jsonschema:"description=The exact text block to search and replace (must match uniquely)."`
		ReplacementContent string `json:"replacement_content" jsonschema:"description=The replacement text."`
	}

	return goai.NewTool("edit_file", "Replace an exact target snippet in a workspace file with replacement content.",
		func(ctx context.Context, p params) (string, error) {
			target, err := workspace.SafePath(workspaceRoot, p.Path)
			if err != nil {
				return "", err
			}

			data, err := os.ReadFile(target)
			if err != nil {
				return "", fmt.Errorf("file not found: %s", p.Path)
			}
			content := string(data)

			if !strings.Contains(content, p.TargetContent) {
				return "", fmt.Errorf("target_content not found in %s", p.Path)
			}

			count := strings.Count(content, p.TargetContent)
			if count > 1 {
				return "", fmt.Errorf("target_content matched %d times in %s. Please provide a more unique snippet", count, p.Path)
			}

			newContent := strings.Replace(content, p.TargetContent, p.ReplacementContent, 1)

			parent := filepath.Dir(target)
			tmpFile, err := os.CreateTemp(parent, ".delta_edit_*")
			if err != nil {
				if writeErr := os.WriteFile(target, []byte(newContent), 0o644); writeErr != nil {
					return "", fmt.Errorf("failed writing updated content: %w", writeErr)
				}
				return fmt.Sprintf("Successfully replaced snippet in %s", p.Path), nil
			}
			tmpName := tmpFile.Name()

			if _, err := tmpFile.Write([]byte(newContent)); err != nil {
				_ = tmpFile.Close()
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed writing to temp file: %w", err)
			}
			if err := tmpFile.Sync(); err != nil {
				_ = tmpFile.Close()
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed syncing file: %w", err)
			}
			_ = tmpFile.Close()

			if fi, err := os.Stat(target); err == nil {
				_ = os.Chmod(tmpName, fi.Mode())
			}

			if err := os.Rename(tmpName, target); err != nil {
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed renaming temp file to target: %w", err)
			}

			return fmt.Sprintf("Successfully replaced snippet in %s", p.Path), nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// FindTool searches for files/directories matching a substring pattern.
func FindTool(workspaceRoot string) goai.Tool {
	type params struct {
		Pattern string `json:"pattern" jsonschema:"description=Filename or directory name substring to match."`
		Path    string `json:"path,omitempty" jsonschema:"description=Optional directory to start finding from."`
		Kind    string `json:"kind,omitempty" jsonschema:"enum=file|dir|any,description=Type of entries: file, dir, or any."`
	}

	return goai.NewTool("find", "Find files and directories matching a name pattern in the workspace.",
		func(ctx context.Context, p params) (string, error) {
			startDir := workspaceRoot
			if p.Path != "" {
				safe, err := workspace.SafePath(workspaceRoot, p.Path)
				if err != nil {
					return "", err
				}
				startDir = safe
			}

			kind := p.Kind
			if kind == "" {
				kind = "any"
			}
			patternLower := strings.ToLower(p.Pattern)

			var matches []string
			err := filepath.WalkDir(startDir, func(path string, d os.DirEntry, walkErr error) error {
				if walkErr != nil {
					return nil
				}
				if ctx.Err() != nil {
					return ctx.Err()
				}
				// AGENTS.md rule: Never follow symlinks during recursive scans
				if d.Type()&os.ModeSymlink != 0 {
					return nil
				}
				name := d.Name()
				if d.IsDir() && strings.HasPrefix(name, ".") && name != "." {
					return filepath.SkipDir
				}

				nameLower := strings.ToLower(name)
				matched := strings.Contains(nameLower, patternLower)

				if d.IsDir() {
					if matched && (kind == "dir" || kind == "any") {
						rel, relErr := filepath.Rel(workspaceRoot, path)
						if relErr != nil {
							rel = path
						}
						if rel != "." {
							matches = append(matches, fmt.Sprintf("%s/", rel))
						}
					}
				} else {
					if matched && (kind == "file" || kind == "any") {
						rel, relErr := filepath.Rel(workspaceRoot, path)
						if relErr != nil {
							rel = path
						}
						matches = append(matches, rel)
					}
				}

				if len(matches) >= 100 {
					matches = append(matches, "... [capped at 100 results]")
					return io.EOF
				}
				return nil
			})

			if err != nil && err != io.EOF && err != context.Canceled {
				return "", err
			}

			if len(matches) == 0 {
				return fmt.Sprintf("No files or directories found matching '%s'", p.Pattern), nil
			}
			return strings.Join(matches, "\n"), nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// ListDirTool lists the contents of a directory.
func ListDirTool(workspaceRoot string) goai.Tool {
	type params struct {
		Path string `json:"path,omitempty" jsonschema:"description=The workspace-relative path of the folder to list (defaults to root '.')."`
	}

	return goai.NewTool("list_dir", "List files and directories in a given folder relative to workspace root.",
		func(ctx context.Context, p params) (string, error) {
			dirPath := p.Path
			if dirPath == "" {
				dirPath = "."
			}
			target, err := workspace.SafePath(workspaceRoot, dirPath)
			if err != nil {
				return "", err
			}

			entries, err := os.ReadDir(target)
			if err != nil {
				return "", fmt.Errorf("failed to read directory: %w", err)
			}

			var lines []string
			for _, e := range entries {
				name := e.Name()
				if e.IsDir() {
					lines = append(lines, fmt.Sprintf("%s/", name))
				} else if e.Type()&os.ModeSymlink != 0 {
					lines = append(lines, fmt.Sprintf("%s -> [symlink]", name))
				} else {
					fi, err := e.Info()
					if err == nil {
						lines = append(lines, fmt.Sprintf("%s (%d bytes)", name, fi.Size()))
					} else {
						lines = append(lines, name)
					}
				}
			}

			sort.Strings(lines)
			return strings.Join(lines, "\n"), nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// ReadFileTool builds the tool definition for reading file contents with optional line numbers.
func ReadFileTool(workspaceRoot string) goai.Tool {
	type params struct {
		Path      string `json:"path" jsonschema:"description=The workspace-relative path of the file to read."`
		StartLine int    `json:"start_line,omitempty" jsonschema:"description=Optional 1-indexed starting line number."`
		EndLine   int    `json:"end_line,omitempty" jsonschema:"description=Optional 1-indexed ending line number (inclusive)."`
	}

	return goai.NewTool("read_file", "Read the contents of a file within the workspace with optional line ranges.",
		func(ctx context.Context, p params) (string, error) {
			target, err := workspace.SafePath(workspaceRoot, p.Path)
			if err != nil {
				return "", err
			}

			fi, err := os.Stat(target)
			if err != nil {
				return "", fmt.Errorf("file not found: %s", p.Path)
			}
			if fi.IsDir() {
				return "", fmt.Errorf("path is a directory, not a file: %s", p.Path)
			}

			data, err := os.ReadFile(target)
			if err != nil {
				return "", fmt.Errorf("failed reading file: %w", err)
			}

			lines := strings.Split(string(data), "\n")
			// Remove trailing empty line if present
			if len(lines) > 0 && lines[len(lines)-1] == "" {
				lines = lines[:len(lines)-1]
			}

			start := 0
			if p.StartLine > 1 {
				start = p.StartLine - 1
			}
			end := len(lines)
			if p.EndLine > 0 && p.EndLine < end {
				end = p.EndLine
			}

			if start >= len(lines) {
				return "", nil
			}

			var b strings.Builder
			for i := start; i < end; i++ {
				fmt.Fprintf(&b, "%4d | %s\n", i+1, lines[i])
			}
			return strings.TrimRight(b.String(), "\n"), nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"

	"github.com/sapirrior/delta/internal/shell"
	"github.com/zendev-sh/goai"
)

// RunCommandTool executes a shell command in workspaceRoot using the shared ShellRunner engine.
func RunCommandTool(workspaceRoot string) goai.Tool {
	type params struct {
		Command string `json:"command" jsonschema:"description=The shell command to execute."`
	}

	runner := shell.NewRunner(workspaceRoot)

	return goai.NewTool("run_command", "Run a shell command within the workspace directory.",
		func(ctx context.Context, p params) (string, error) {
			res, err := runner.Run(ctx, p.Command, nil)
			if err != nil {
				return res.Output, err
			}
			if res.Error != nil && res.Output == "" {
				return res.Error.Error(), nil
			}
			if res.ExitCode != 0 {
				if res.Output == "" {
					return fmt.Sprintf("Command exited with code %d", res.ExitCode), nil
				}
				return fmt.Sprintf("%s\n[Process exited with code %d]", res.Output, res.ExitCode), nil
			}
			return res.Output, nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"

	"github.com/zendev-sh/goai"
)

// ScheduleTool simulates scheduling reminders or background timer notifications.
func ScheduleTool() goai.Tool {
	type params struct {
		DurationSeconds int    `json:"duration_seconds,omitempty" jsonschema:"description=Duration in seconds before triggering notification."`
		CronExpression  string `json:"cron_expression,omitempty" jsonschema:"description=Standard 5-field cron expression."`
		Prompt          string `json:"prompt" jsonschema:"description=Message prompt to be reminded of."`
	}

	return goai.NewTool("schedule", "Schedule a reminder or background timer notification.",
		func(ctx context.Context, p params) (string, error) {
			if p.DurationSeconds > 0 {
				return fmt.Sprintf("Scheduled one-shot reminder in %ds: '%s'", p.DurationSeconds, p.Prompt), nil
			}
			if p.CronExpression != "" {
				return fmt.Sprintf("Scheduled cron task '%s': '%s'", p.CronExpression, p.Prompt), nil
			}
			return "", fmt.Errorf("either duration_seconds or cron_expression must be specified")
		},
	)
}

package builtins

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// SearchTextTool performs ripgrep-style recursive pattern matching across workspace files.
func SearchTextTool(workspaceRoot string) goai.Tool {
	type params struct {
		Query string `json:"query" jsonschema:"description=The exact string or phrase to search for."`
		Path  string `json:"path,omitempty" jsonschema:"description=Optional subdirectory to restrict search to."`
	}

	return goai.NewTool("search_text", "Search for a text pattern or string across files in the workspace (ripgrep-style).",
		func(ctx context.Context, p params) (string, error) {
			startDir := workspaceRoot
			if p.Path != "" {
				safe, err := workspace.SafePath(workspaceRoot, p.Path)
				if err != nil {
					return "", err
				}
				startDir = safe
			}

			var matches []string
			err := filepath.WalkDir(startDir, func(path string, d os.DirEntry, walkErr error) error {
				if walkErr != nil {
					return nil
				}
				if ctx.Err() != nil {
					return ctx.Err()
				}
				// AGENTS.md rule: Never follow symlinks during recursive scans
				if d.Type()&os.ModeSymlink != 0 {
					return nil
				}
				name := d.Name()
				if d.IsDir() && strings.HasPrefix(name, ".") && name != "." {
					return filepath.SkipDir
				}
				if !d.IsDir() {
					f, err := os.Open(path)
					if err != nil {
						return nil
					}

					scanner := bufio.NewScanner(f)
					buf := make([]byte, 64*1024)
					scanner.Buffer(buf, 1024*1024)

					lineIdx := 0
					for scanner.Scan() {
						if ctx.Err() != nil {
							_ = f.Close()
							return ctx.Err()
						}
						lineIdx++
						line := scanner.Text()
						if strings.Contains(line, p.Query) {
							rel, relErr := filepath.Rel(workspaceRoot, path)
							if relErr != nil {
								rel = path
							}
							matches = append(matches, fmt.Sprintf("%s:%d: %s", rel, lineIdx, strings.TrimSpace(line)))
							if len(matches) >= 100 {
								matches = append(matches, "... [capped at 100 matches]")
								_ = f.Close()
								return io.EOF // Stop scan early
							}
						}
					}
					if scanErr := scanner.Err(); scanErr != nil {
						_ = f.Close()
						return fmt.Errorf("reading file %s: %w", path, scanErr)
					}
					_ = f.Close()
				}
				return nil
			})

			if err != nil && err != io.EOF && err != context.Canceled {
				return "", err
			}

			if len(matches) == 0 {
				return fmt.Sprintf("No matches found for '%s'", p.Query), nil
			}
			return strings.Join(matches, "\n"), nil
		},
	)
}

package builtins_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/sapirrior/delta/internal/tools/builtins"
)

func TestReadFileAndWriteFileAndEditFile(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_tools_test_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	ctx := context.Background()

	// 1. Write file
	wf := builtins.WriteFileTool(tempDir)
	writeArgs := map[string]any{
		"path":    "hello.txt",
		"content": "line 1\nline 2\nline 3\nline 4\n",
	}
	argsBytes, _ := json.Marshal(writeArgs)
	out, err := wf.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("write_file failed: %v", err)
	}
	if !strings.Contains(out, "Successfully wrote") {
		t.Errorf("unexpected write output: %s", out)
	}

	// 2. Read file with line numbers
	rf := builtins.ReadFileTool(tempDir)
	readArgs := map[string]any{
		"path":       "hello.txt",
		"start_line": 2,
		"end_line":   3,
	}
	argsBytes, _ = json.Marshal(readArgs)
	out, err = rf.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("read_file failed: %v", err)
	}
	expected := "   2 | line 2\n   3 | line 3"
	if out != expected {
		t.Errorf("read_file expected %q, got %q", expected, out)
	}

	// 3. Edit file
	ef := builtins.EditFileTool(tempDir)
	editArgs := map[string]any{
		"path":                "hello.txt",
		"target_content":      "line 3",
		"replacement_content": "line 3 modified",
	}
	argsBytes, _ = json.Marshal(editArgs)
	out, err = ef.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("edit_file failed: %v", err)
	}
	if !strings.Contains(out, "Successfully replaced") {
		t.Errorf("unexpected edit output: %s", out)
	}

	// Read full file to verify edit
	readFullArgs := map[string]any{"path": "hello.txt"}
	argsBytes, _ = json.Marshal(readFullArgs)
	out, err = rf.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("read_file failed: %v", err)
	}
	if !strings.Contains(out, "line 3 modified") {
		t.Errorf("file did not contain edited string: %s", out)
	}
}

func TestListDirFindSearch(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_tools_test2_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	subDir := filepath.Join(tempDir, "pkg")
	_ = os.MkdirAll(subDir, 0o755)
	_ = os.WriteFile(filepath.Join(subDir, "main.go"), []byte("package main\n\nfunc Run() {}\n"), 0o644)
	_ = os.WriteFile(filepath.Join(tempDir, "README.md"), []byte("# Title\n"), 0o644)

	ctx := context.Background()

	// ListDir
	ld := builtins.ListDirTool(tempDir)
	argsBytes, _ := json.Marshal(map[string]any{"path": "."})
	out, err := ld.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("list_dir failed: %v", err)
	}
	if !strings.Contains(out, "pkg/") || !strings.Contains(out, "README.md") {
		t.Errorf("list_dir output missing entries: %s", out)
	}

	// Find
	findTool := builtins.FindTool(tempDir)
	argsBytes, _ = json.Marshal(map[string]any{"pattern": "main"})
	out, err = findTool.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("find failed: %v", err)
	}
	if !strings.Contains(out, "pkg/main.go") {
		t.Errorf("find failed to locate main.go: %s", out)
	}

	// SearchText
	st := builtins.SearchTextTool(tempDir)
	argsBytes, _ = json.Marshal(map[string]any{"query": "package main"})
	out, err = st.Execute(ctx, argsBytes)
	if err != nil {
		t.Fatalf("search_text failed: %v", err)
	}
	if !strings.Contains(out, "pkg/main.go:1: package main") {
		t.Errorf("search_text failed to match: %s", out)
	}
}

func TestRunCommand(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_tools_cmd_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	rc := builtins.RunCommandTool(tempDir)
	argsBytes, _ := json.Marshal(map[string]any{"command": "echo 'delta test'"})
	out, err := rc.Execute(context.Background(), argsBytes)
	if err != nil {
		t.Fatalf("run_command failed: %v", err)
	}
	if strings.TrimSpace(out) != "delta test" {
		t.Errorf("expected 'delta test', got %q", out)
	}
}

package builtins

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"time"

	"github.com/zendev-sh/goai"
)

// WebFetchTool fetches web page content via HTTP GET request.
func WebFetchTool() goai.Tool {
	type params struct {
		Url string `json:"url" jsonschema:"description=The URL to fetch."`
	}

	client := &http.Client{Timeout: 15 * time.Second}

	return goai.NewTool("web_fetch", "Fetch web page content via HTTP GET request.",
		func(ctx context.Context, p params) (string, error) {
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.Url, nil)
			if err != nil {
				return "", fmt.Errorf("invalid URL: %w", err)
			}
			req.Header.Set("User-Agent", "Delta/0.1.0")

			resp, err := client.Do(req)
			if err != nil {
				return "", fmt.Errorf("HTTP fetch failed: %w", err)
			}
			defer resp.Body.Close()

			if resp.StatusCode < 200 || resp.StatusCode >= 300 {
				return "", fmt.Errorf("HTTP fetch returned status %s", resp.Status)
			}

			body, err := io.ReadAll(io.LimitReader(resp.Body, 1024*1024))
			if err != nil {
				return "", fmt.Errorf("reading response body: %w", err)
			}

			text := string(body)
			if len(text) > 20000 {
				text = text[:20000] + "\n\n[Content truncated at 20,000 characters]"
			}
			return text, nil
		},
	)
}

package builtins

import (
	"context"
	"fmt"
	"os"
	"path/filepath"

	"github.com/sapirrior/delta/internal/workspace"
	"github.com/zendev-sh/goai"
)

// WriteFileTool builds the tool for creating or overwriting workspace files atomically.
func WriteFileTool(workspaceRoot string) goai.Tool {
	type params struct {
		Path    string `json:"path" jsonschema:"description=The workspace-relative path of the file to write."`
		Content string `json:"content" jsonschema:"description=The entire text content to write."`
	}

	return goai.NewTool("write_file", "Create or overwrite a file at the specified workspace path atomically.",
		func(ctx context.Context, p params) (string, error) {
			target, err := workspace.SafePath(workspaceRoot, p.Path)
			if err != nil {
				return "", err
			}

			parent := filepath.Dir(target)
			if err := os.MkdirAll(parent, 0o755); err != nil {
				return "", fmt.Errorf("failed to create directory: %w", err)
			}

			// Atomic write pattern: write to temp file then rename
			tmpFile, err := os.CreateTemp(parent, ".delta_write_*")
			if err != nil {
				// Fallback to direct write if temp file creation fails
				if writeErr := os.WriteFile(target, []byte(p.Content), 0o644); writeErr != nil {
					return "", fmt.Errorf("failed writing file: %w", writeErr)
				}
				return fmt.Sprintf("Successfully wrote %d bytes to %s", len(p.Content), p.Path), nil
			}
			tmpName := tmpFile.Name()

			if _, err := tmpFile.Write([]byte(p.Content)); err != nil {
				_ = tmpFile.Close()
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed writing to temp file: %w", err)
			}
			if err := tmpFile.Sync(); err != nil {
				_ = tmpFile.Close()
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed syncing file: %w", err)
			}
			_ = tmpFile.Close()

			// Preserve existing permissions if file exists
			if fi, err := os.Stat(target); err == nil {
				_ = os.Chmod(tmpName, fi.Mode())
			} else {
				_ = os.Chmod(tmpName, 0o644)
			}

			if err := os.Rename(tmpName, target); err != nil {
				_ = os.Remove(tmpName)
				return "", fmt.Errorf("failed renaming temp file to target: %w", err)
			}

			return fmt.Sprintf("Successfully wrote %d bytes to %s", len(p.Content), p.Path), nil
		},
	)
}

package tui

import (
	"context"
	"fmt"
	"strings"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/sapirrior/delta/internal/constants"
	"github.com/sapirrior/delta/internal/tui/view"
	"github.com/sapirrior/delta/internal/workspace"
)

// handleKeyConfirming handles key events in the confirmation modal.
func (m *AppModel) handleKeyConfirming(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	if m.pendingConfirm == nil {
		m.setMode(ModeNormal)
		return m, nil
	}

	switch key {
	case "up", "k":
		if m.confirmSelected > 0 {
			m.confirmSelected--
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "down", "j", "tab":
		m.confirmSelected = (m.confirmSelected + 1) % 3
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "f":
		m.setMode(ModeReviewing)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "1":
		m.confirmSelected = 0
		m.resolveConfirmation(true, false)
		return m, nil
	case "2":
		m.confirmSelected = 1
		m.resolveConfirmation(true, true)
		return m, nil
	case "3", "n", "N", "esc":
		m.confirmSelected = 2
		m.resolveConfirmation(false, false)
		return m, nil
	case "y", "Y":
		m.confirmSelected = 0
		m.resolveConfirmation(true, false)
		return m, nil
	case "enter":
		allowed := m.confirmSelected == 0 || m.confirmSelected == 1
		forSession := m.confirmSelected == 1
		m.resolveConfirmation(allowed, forSession)
		return m, nil
	}
	return m, nil
}

// handleKeyReviewing handles key events when reviewing a diff/preview.
func (m *AppModel) handleKeyReviewing(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	switch key {
	case "up", "k":
		if m.reviewOffset > 0 {
			m.reviewOffset--
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "down", "j":
		m.reviewOffset++
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "pgup":
		if m.reviewOffset >= 5 {
			m.reviewOffset -= 5
		} else {
			m.reviewOffset = 0
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "pgdown":
		m.reviewOffset += 5
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "1":
		m.confirmSelected = 0
		m.resolveConfirmation(true, false)
		return m, nil
	case "2":
		m.confirmSelected = 1
		m.resolveConfirmation(true, true)
		return m, nil
	case "3", "n", "N":
		m.confirmSelected = 2
		m.resolveConfirmation(false, false)
		return m, nil
	case "y", "Y":
		m.confirmSelected = 0
		m.resolveConfirmation(true, false)
		return m, nil
	case "enter":
		allowed := m.confirmSelected == 0 || m.confirmSelected == 1
		forSession := m.confirmSelected == 1
		m.resolveConfirmation(allowed, forSession)
		return m, nil
	case "f", "esc", "q":
		m.setMode(ModeConfirming)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	}
	return m, nil
}

func (m *AppModel) resolveConfirmation(approved, forSession bool) {
	if m.pendingConfirm != nil {
		if forSession {
			m.backend.ResolveConfirmationForSession(m.pendingConfirm.ToolName, approved)
		} else {
			m.backend.ResolveConfirmation(approved)
		}
		m.pendingConfirm = nil
	}
	m.setMode(ModeStreaming)
	m.updateViewportContent()
	m.viewport.GotoBottom()
}

// handleKeySessionMenu handles keys within the session picker overlay.
func (m *AppModel) handleKeySessionMenu(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	filtered := m.getFilteredSessions()

	switch key {
	case "esc":
		if m.sessionQuery != "" {
			m.sessionQuery = ""
			m.selectedSess = 0
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		}
		m.setMode(ModeNormal)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "up":
		if m.selectedSess > 0 {
			m.selectedSess--
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "down":
		if m.selectedSess < len(filtered)-1 {
			m.selectedSess++
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "enter":
		if len(filtered) > 0 {
			idx := m.selectedSess
			if idx >= len(filtered) {
				idx = len(filtered) - 1
			}
			sess := filtered[idx]
			m.loadSession(sess.Path)
		}
		m.setMode(ModeNormal)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "backspace":
		if len(m.sessionQuery) > 0 {
			m.sessionQuery = m.sessionQuery[:len(m.sessionQuery)-1]
			m.selectedSess = 0
			m.updateViewportContent()
			m.viewport.GotoBottom()
		}
		return m, nil
	default:
		runes := []rune(msg.String())
		if len(runes) == 1 && runes[0] >= 32 && runes[0] != 127 {
			m.sessionQuery += string(runes)
			m.selectedSess = 0
			m.updateViewportContent()
			m.viewport.GotoBottom()
		}
		return m, nil
	}
}

// handleKeyPalette handles navigation inside the slash command palette.
func (m *AppModel) handleKeyPalette(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	switch key {
	case "up":
		if m.paletteIdx > 0 {
			m.paletteIdx--
		}
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "down":
		m.paletteIdx++
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "esc":
		m.setMode(ModeNormal)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	case "tab", "enter":
		return m.executeSelectedCommand()
	}
	return nil, nil
}

// handleKeyStreaming handles user cancellation during ongoing stream generation.
func (m *AppModel) handleKeyStreaming(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()
	if key == "esc" || key == "ctrl+c" {
		m.backend.CancelActiveWork()
		m.transcript = append(m.transcript, view.TranscriptItem{
			Role:    "system",
			Content: constants.HintResponseStopped,
		})
		m.setMode(ModeNormal)
		m.dirty = true
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	}
	return nil, nil
}

// handleKeyNormal handles regular keyboard interaction, shortcuts, bash toggles, and submissions.
func (m *AppModel) handleKeyNormal(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	key := msg.String()

	// 1. Double Ctrl+C when idle: exits application
	if key == "ctrl+c" {
		if time.Since(m.lastCtrlC) < constants.DoubleCtrlCInterval {
			return m, tea.Quit
		}
		m.lastCtrlC = time.Now()
		m.quitHint = true
		m.updateViewportContent()
		return m, nil
	}
	m.quitHint = false

	// 2. Esc key handling
	if key == "esc" {
		if len(m.fileMatches) > 0 {
			m.fileMatches = nil
			m.fileSelectIdx = 0
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		}
		if m.mode == ModePalette || m.mode == ModeHelp || m.mode == ModeBash {
			m.setMode(ModeNormal)
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		}

		now := time.Now()
		isDoubleEsc := time.Since(m.lastEsc) <= constants.DoubleEscInterval

		if isDoubleEsc {
			m.lastEsc = time.Time{}
			if m.input.Value() != "" {
				m.input.Reset()
				m.updateViewportContent()
				m.viewport.GotoBottom()
				return m, nil
			}
			// Double Esc on empty input opens session picker
			m.openSessionMenu()
			return m, nil
		}

		m.lastEsc = now
		return m, nil
	}

	// 2b. File completion navigation and selection
	if len(m.fileMatches) > 0 {
		switch key {
		case "up":
			if m.fileSelectIdx > 0 {
				m.fileSelectIdx--
			}
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		case "down":
			if m.fileSelectIdx < len(m.fileMatches)-1 {
				m.fileSelectIdx++
			}
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		case "tab":
			m.insertSelectedFile()
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		case "enter":
			m.insertSelectedFile()
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		}
	}

	// 3. Help menu toggle (? on empty input or any key dismisses help)
	if m.mode == ModeHelp {
		m.setMode(ModeNormal)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		if key == "esc" {
			return m, nil
		}
	} else if (key == "?" || msg.String() == "?") && m.input.Value() == "" {
		m.setMode(ModeHelp)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	}

	// 4. Bash mode toggle (! on empty input)
	if m.mode != ModeBash && (key == "!" || msg.String() == "!") && m.input.Value() == "" {
		m.setMode(ModeBash)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	} else if m.mode == ModeBash && (key == "backspace" && m.input.Value() == "") {
		m.setMode(ModeNormal)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	}

	// 5. Enter triggers submission
	if key == "enter" {
		text := strings.TrimSpace(m.input.Value())
		if text == "" {
			return m, nil
		}

		// Direct User Shell Mode: runs directly without confirmation prompts
		if m.mode == ModeBash {
			m.input.Reset()
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:     "bash",
				Content:  text,
				ToolIcon: "!",
			})
			m.updateViewportContent()
			m.viewport.GotoBottom()

			_ = m.backend.StartBash(context.Background(), text)
			return m, nil
		}

		// Slash command
		if strings.HasPrefix(text, "/") {
			m.input.Reset()
			return m.handleSlashCommand(text)
		}

		// Extract @path mentions and append structured file content
		files, _ := workspace.ExtractFileMentions(m.cwd, text)
		turnText := text
		if len(files) > 0 {
			turnText = workspace.BuildPromptWithFiles(m.cwd, text, files)
		}

		// User prompt submission
		m.transcript = append(m.transcript, view.TranscriptItem{
			Role:    "user",
			Content: text,
		})
		m.input.Reset()
		m.fileMatches = nil
		m.fileSelectIdx = 0
		m.setMode(ModeStreaming)
		m.updateViewportContent()
		m.viewport.GotoBottom()

		_ = m.backend.StartTurn(context.Background(), turnText)
		return m, renderTick()
	}

	return nil, nil
}

func (m *AppModel) handleSlashCommand(cmd string) (tea.Model, tea.Cmd) {
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		return m, nil
	}

	name := parts[0]
	switch name {
	case "/exit":
		return m, tea.Quit
	case "/resume", "/sessions":
		m.openSessionMenu()
		return m, nil
	case "/clear":
		m.transcript = nil
		_ = m.backend.ExecuteCommand(context.Background(), cmd)
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, nil
	default:
		err := m.backend.ExecuteCommand(context.Background(), cmd)
		if err != nil {
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "system",
				Content: fmt.Sprintf(constants.HintUnknownCommand, name),
			})
			m.updateViewportContent()
			m.viewport.GotoBottom()
			return m, nil
		}
		if name == "/model" && len(parts) == 1 {
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "system",
				Content: fmt.Sprintf("Current model: %s. Use /model <name> to change.", m.backend.ModelName()),
			})
			m.updateViewportContent()
			m.viewport.GotoBottom()
		}
		return m, nil
	}
}

package tui

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/sapirrior/delta/internal/core"
)

type mockBackend struct {
	modelName string
	events    chan core.Event
	confirms  chan core.Confirmation
	lastTurn  string
}

func newMockBackend() *mockBackend {
	return &mockBackend{
		modelName: "test-model",
		events:    make(chan core.Event, 10),
		confirms:  make(chan core.Confirmation, 10),
	}
}

func (m *mockBackend) StartTurn(ctx context.Context, input string) error {
	m.lastTurn = input
	return nil
}
func (m *mockBackend) StartBash(ctx context.Context, command string) error          { return nil }
func (m *mockBackend) CancelActiveWork()                                            {}
func (m *mockBackend) Events() <-chan core.Event                                    { return m.events }
func (m *mockBackend) Confirmations() <-chan core.Confirmation                      { return m.confirms }
func (m *mockBackend) ResolveConfirmation(approved bool)                            {}
func (m *mockBackend) ResolveConfirmationForSession(toolName string, approved bool) {}
func (m *mockBackend) Commands() []core.Command                                     { return nil }
func (m *mockBackend) ExecuteCommand(ctx context.Context, command string) error     { return nil }
func (m *mockBackend) Sessions() ([]core.SessionRow, error)                         { return nil, nil }
func (m *mockBackend) ResumeSession(ctx context.Context, path string) (core.SessionView, error) {
	return core.SessionView{}, nil
}
func (m *mockBackend) NewSession(ctx context.Context) error   { return nil }
func (m *mockBackend) ClearContext(ctx context.Context) error { return nil }
func (m *mockBackend) ModelName() string                      { return m.modelName }
func (m *mockBackend) SetModel(ctx context.Context, name string) error {
	m.modelName = name
	return nil
}

func TestInputKeyRoutingAndOverlayExclusivity(t *testing.T) {
	backend := newMockBackend()
	m, err := NewAppModel(backend, ".")
	if err != nil {
		t.Fatalf("failed creating app model: %v", err)
	}

	// 1. Enter Help overlay
	m.enterOverlay(OverlayHelp)
	if m.mode != ModeHelp {
		t.Errorf("expected ModeHelp, got %v", m.mode)
	}

	// 2. Enter Bash overlay (should close Help)
	m.enterOverlay(OverlayBash)
	if m.mode != ModeBash {
		t.Errorf("expected ModeBash, got %v", m.mode)
	}

	// 3. Double Esc on empty input opens session menu
	m.setMode(ModeNormal)
	m.lastEsc = time.Now()
	m.handleKeyNormal(tea.KeyPressMsg{Code: tea.KeyEscape})
	if m.mode != ModeSessionMenu {
		t.Errorf("expected ModeSessionMenu after double Esc on empty input, got %v", m.mode)
	}

	// 4. Esc in Session menu returns to normal
	m.handleKeySessionMenu(tea.KeyPressMsg{Code: tea.KeyEscape})
	if m.mode != ModeNormal {
		t.Errorf("expected ModeNormal after Esc in session menu, got %v", m.mode)
	}
}

func TestConfirmationReviewMode(t *testing.T) {
	backend := newMockBackend()
	m, err := NewAppModel(backend, ".")
	if err != nil {
		t.Fatalf("failed creating app model: %v", err)
	}

	m.pendingConfirm = &core.Confirmation{
		ID:       "call_1",
		ToolName: "edit_file",
	}
	m.setMode(ModeConfirming)

	// Press 'f' to enter review mode
	m.handleKeyConfirming(tea.KeyPressMsg{Text: "f"})
	if m.mode != ModeReviewing {
		t.Errorf("expected ModeReviewing after pressing 'f', got %v", m.mode)
	}

	// Down arrow in review mode increases offset
	m.handleKeyReviewing(tea.KeyPressMsg{Code: tea.KeyDown})
	if m.reviewOffset != 1 {
		t.Errorf("expected reviewOffset=1, got %d", m.reviewOffset)
	}

	// 'f' or 'esc' leaves review mode back to option selection
	m.handleKeyReviewing(tea.KeyPressMsg{Text: "f"})
	if m.mode != ModeConfirming {
		t.Errorf("expected ModeConfirming after exiting review mode, got %v", m.mode)
	}
}

func TestFileCompletionAndPromptAttachment(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_tui_file_complete_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	subDir := filepath.Join(tempDir, "pkg")
	if err := os.MkdirAll(subDir, 0755); err != nil {
		t.Fatalf("failed creating subDir: %v", err)
	}
	testFile := filepath.Join(subDir, "code.go")
	if err := os.WriteFile(testFile, []byte("package pkg\nfunc Code() {}\n"), 0644); err != nil {
		t.Fatalf("failed writing test file: %v", err)
	}

	backend := newMockBackend()
	m, err := NewAppModel(backend, tempDir)
	if err != nil {
		t.Fatalf("failed creating app model: %v", err)
	}

	// 1. Typing @ triggers file completion
	m.input.SetValue("@c")
	m.input.SetCursor(2)
	// Simulate input update cycle typing 'o'
	m.Update(tea.KeyPressMsg{Code: 'o', Text: "o"})

	if len(m.fileMatches) == 0 {
		t.Fatalf("expected fileMatches to be populated for '@co'")
	}
	expectedRel := filepath.Join("pkg", "code.go")
	if m.fileMatches[0] != expectedRel {
		t.Errorf("expected match %s, got %s", expectedRel, m.fileMatches[0])
	}

	// 2. Tab or Enter inserts selected file into input text
	m.handleKeyNormal(tea.KeyPressMsg{Code: tea.KeyTab})
	expectedInput := "@" + expectedRel + " "
	if m.input.Value() != expectedInput {
		t.Errorf("expected input %q, got %q", expectedInput, m.input.Value())
	}
	if len(m.fileMatches) != 0 {
		t.Errorf("expected fileMatches to be cleared after insertion")
	}

	// 3. Submitting prompt with @mention appends structured file content
	m.handleKeyNormal(tea.KeyPressMsg{Code: tea.KeyEnter})
	if !strings.Contains(backend.lastTurn, strings.TrimSpace(expectedInput)) {
		t.Errorf("expected original prompt text in lastTurn, got: %s", backend.lastTurn)
	}
	if !strings.Contains(backend.lastTurn, "<file path=\""+expectedRel+"\">") {
		t.Errorf("expected structured file block in lastTurn, got: %s", backend.lastTurn)
	}
	if !strings.Contains(backend.lastTurn, "package pkg") {
		t.Errorf("expected file content in lastTurn, got: %s", backend.lastTurn)
	}
}

package tui

import (
	"context"
	"fmt"
	"strings"
	"time"

	"charm.land/bubbles/v2/textinput"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	"github.com/sapirrior/delta/internal/constants"
	"github.com/sapirrior/delta/internal/core"
	"github.com/sapirrior/delta/internal/tui/view"
	"github.com/sapirrior/delta/internal/workspace"
)

// Mode represents the explicit, mutually exclusive top-level interaction state of Delta.
type Mode int

const (
	ModeNormal Mode = iota
	ModeStreaming
	ModeConfirming
	ModeReviewing
	ModeSessionMenu
	ModePalette
	ModeHelp
	ModeBash
)

// OverlayKind is retained as an alias for transition requests.
type OverlayKind = Mode

const (
	OverlayNone        = ModeNormal
	OverlayHelp        = ModeHelp
	OverlayBash        = ModeBash
	OverlayPalette     = ModePalette
	OverlaySessionMenu = ModeSessionMenu
)

// AppModel implements the Bubble Tea v2 Model interface.
type AppModel struct {
	backend       core.Backend
	mode          Mode
	width         int
	height        int
	viewport      viewport.Model
	viewportReady bool
	input         textinput.Model
	transcript    []view.TranscriptItem

	// Session picker state
	sessions     []view.SessionRow
	selectedSess int
	sessionQuery string

	// Palette state
	paletteQuery string
	paletteIdx   int

	// File completion state
	fileMatches   []string
	fileSelectIdx int

	// Confirmation state
	pendingConfirm  *core.Confirmation
	confirmSelected int
	reviewOffset    int

	lastCtrlC time.Time
	lastEsc   time.Time
	quitHint  bool
	modelName string
	dirty     bool
	animFrame int

	totalInTokens  int
	totalOutTokens int

	staticTranscriptCache string
	cachedTranscriptLen   int
	cachedTranscriptWidth int
	cwd                   string
}

// Backward-compatible getters
func (m *AppModel) state() Mode       { return m.mode }
func (m *AppModel) helpOpen() bool    { return m.mode == ModeHelp }
func (m *AppModel) isBashMode() bool  { return m.mode == ModeBash }
func (m *AppModel) paletteOpen() bool { return m.mode == ModePalette }

// Msg types
type (
	CoreEventMsg   core.Event
	CoreConfirmMsg core.Confirmation
	RenderTickMsg  time.Time
)

// NewAppModel initializes the Bubble Tea application state using core.Backend.
func NewAppModel(backend core.Backend, cwd string) (*AppModel, error) {
	ti := textinput.New()
	ti.Placeholder = "Ask Delta anything, or type / for commands..."
	ti.Focus()
	ti.Prompt = "❯ "

	styles := textinput.DefaultDarkStyles()
	styles.Focused.Prompt = view.StyleBrand
	styles.Focused.Text = view.StyleText
	ti.SetStyles(styles)

	m := &AppModel{
		backend:   backend,
		mode:      ModeNormal,
		width:     80,
		height:    24,
		input:     ti,
		modelName: backend.ModelName(),
		cwd:       cwd,
	}

	return m, nil
}

func renderTick() tea.Cmd {
	return tea.Tick(constants.RenderTickInterval, func(t time.Time) tea.Msg {
		return RenderTickMsg(t)
	})
}

func (m *AppModel) Init() tea.Cmd {
	return tea.Batch(
		textinput.Blink,
		renderTick(),
		waitForCoreEvent(m.backend.Events()),
		waitForCoreConfirm(m.backend.Confirmations()),
	)
}

func waitForCoreEvent(ch <-chan core.Event) tea.Cmd {
	return func() tea.Msg {
		ev, ok := <-ch
		if !ok {
			return nil
		}
		return CoreEventMsg(ev)
	}
}

func waitForCoreConfirm(ch <-chan core.Confirmation) tea.Cmd {
	return func() tea.Msg {
		req, ok := <-ch
		if !ok {
			return nil
		}
		return CoreConfirmMsg(req)
	}
}

// setMode transitions to a target mode cleanly resetting transient substate.
func (m *AppModel) setMode(target Mode) {
	m.mode = target
	switch target {
	case ModeNormal:
		m.sessionQuery = ""
		m.paletteQuery = ""
		m.paletteIdx = 0
		m.fileMatches = nil
		m.fileSelectIdx = 0
		m.reviewOffset = 0
	case ModeSessionMenu:
		rows, _ := m.backend.Sessions()
		var sessions []view.SessionRow
		for _, r := range rows {
			sessions = append(sessions, view.SessionRow{
				ID:   r.ID,
				Path: r.FilePath,
				Date: r.Date,
			})
		}
		m.sessions = sessions
		m.selectedSess = 0
		m.sessionQuery = ""
	case ModePalette:
		m.paletteIdx = 0
	case ModeConfirming:
		m.confirmSelected = 0
		m.reviewOffset = 0
	case ModeReviewing:
		m.reviewOffset = 0
	}
}

func (m *AppModel) enterOverlay(kind Mode) {
	m.setMode(kind)
}

func (m *AppModel) closeOverlays() {
	m.setMode(ModeNormal)
}

func (m *AppModel) openSessionMenu() {
	m.setMode(ModeSessionMenu)
	m.updateViewportContent()
	m.viewport.GotoBottom()
}

func (m *AppModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.input.SetWidth(msg.Width - 4)

		if !m.viewportReady {
			m.viewport = viewport.New()
			m.viewport.SetWidth(msg.Width)
			m.viewport.SetHeight(msg.Height)
			m.viewport.MouseWheelEnabled = true
			m.viewport.MouseWheelDelta = 3
			m.viewportReady = true
		} else {
			m.viewport.SetWidth(msg.Width)
			m.viewport.SetHeight(msg.Height)
		}
		m.updateViewportContent()
		return m, nil

	case tea.MouseWheelMsg:
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		cmds = append(cmds, cmd)
		return m, tea.Batch(cmds...)

	case RenderTickMsg:
		m.animFrame++
		if m.mode == ModeStreaming {
			m.dirty = true
		}
		if m.dirty {
			m.updateViewportContent()
			m.viewport.GotoBottom()
			m.dirty = false
		}
		if m.mode == ModeStreaming || m.mode == ModeConfirming || m.mode == ModeReviewing {
			return m, renderTick()
		}
		return m, nil

	case CoreConfirmMsg:
		req := core.Confirmation(msg)
		m.pendingConfirm = &req
		m.setMode(ModeConfirming)
		m.dirty = true
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return m, tea.Batch(waitForCoreConfirm(m.backend.Confirmations()), renderTick())

	case CoreEventMsg:
		ev := core.Event(msg)
		m.dirty = true
		switch ev.Type {
		case core.EventReasoningDelta:
			if len(m.transcript) > 0 && m.transcript[len(m.transcript)-1].Role == "thought" {
				m.transcript[len(m.transcript)-1].Content += ev.Delta
			} else {
				m.transcript = append(m.transcript, view.TranscriptItem{
					Role:    "thought",
					Content: ev.Delta,
				})
			}
		case core.EventTextDelta:
			cleanText := ev.Delta
			if len(m.transcript) > 0 && m.transcript[len(m.transcript)-1].Role == "assistant" {
				m.transcript[len(m.transcript)-1].Content += cleanText
			} else {
				m.transcript = append(m.transcript, view.TranscriptItem{
					Role:    "assistant",
					Content: cleanText,
				})
			}
		case core.EventToolStarted:
			arg := view.PrimaryArg(ev.ToolInput)
			dispName := ev.ToolDisplayName
			if dispName == "" {
				dispName = ev.ToolName
			}
			logLine := fmt.Sprintf("%s(%s)", dispName, arg)
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:     "tool",
				Content:  logLine,
				ToolIcon: "◉",
				ToolName: dispName,
				ToolArg:  arg,
			})
		case core.EventToolFinished:
			if ev.ToolName == "bash" {
				for i := len(m.transcript) - 1; i >= 0; i-- {
					if m.transcript[i].Role == "bash" && m.transcript[i].ToolOutput == "" {
						m.transcript[i].ToolOutput = ev.ToolOutput
						break
					}
				}
				if ev.TurnDone {
					m.setMode(ModeNormal)
					m.dirty = false
					m.updateViewportContent()
					m.viewport.GotoBottom()
				}
				break
			}
			icon := constants.GlyphDone
			if ev.IsError {
				icon = constants.GlyphError
			}
			arg := view.PrimaryArg(ev.ToolInput)
			dispName := ev.ToolDisplayName
			if dispName == "" {
				dispName = ev.ToolName
			}
			logLine := fmt.Sprintf("%s(%s)", dispName, arg)
			outSummary := ev.ToolSummary
			if outSummary == "" {
				outSummary = ev.ToolOutput
			}
			updated := false
			for i := len(m.transcript) - 1; i >= 0; i-- {
				if m.transcript[i].Role == "tool" && (m.transcript[i].ToolName == dispName || m.transcript[i].ToolName == ev.ToolName || m.transcript[i].ToolIcon == "◉") {
					m.transcript[i].ToolIcon = icon
					m.transcript[i].Content = logLine
					m.transcript[i].ToolName = dispName
					m.transcript[i].ToolArg = arg
					m.transcript[i].ToolOutput = outSummary
					updated = true
					break
				}
			}
			if !updated {
				m.transcript = append(m.transcript, view.TranscriptItem{
					Role:       "tool",
					Content:    logLine,
					ToolIcon:   icon,
					ToolName:   dispName,
					ToolArg:    arg,
					ToolOutput: outSummary,
				})
			}
		case core.EventApplicationError:
			errMsg := "Error"
			if ev.Error != nil {
				errMsg = ev.Error.Error()
			}
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "system",
				Content: errMsg,
			})
			if ev.TurnDone {
				m.setMode(ModeNormal)
				m.dirty = false
				m.updateViewportContent()
				m.viewport.GotoBottom()
			}
		case core.EventSessionChanged:
			m.transcript = nil
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "system",
				Content: fmt.Sprintf("Started new session (%s)", ev.SessionID[:8]),
			})
			m.updateViewportContent()
			m.viewport.GotoBottom()
		case core.EventModelChanged:
			m.modelName = ev.ModelName
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "system",
				Content: fmt.Sprintf("Active model switched to %s", ev.ModelName),
			})
			m.updateViewportContent()
			m.viewport.GotoBottom()
		case core.EventTurnCompleted:
			m.setMode(ModeNormal)
			m.updateViewportContent()
			m.viewport.GotoBottom()
			m.dirty = false
		}
		return m, waitForCoreEvent(m.backend.Events())

	case tea.KeyPressMsg:
		key := msg.String()

		// 1. Tool Confirmation / Review Modal
		if m.pendingConfirm != nil {
			if m.mode == ModeReviewing {
				return m.handleKeyReviewing(msg)
			}
			if m.mode == ModeConfirming {
				return m.handleKeyConfirming(msg)
			}
		}

		// 2. Session Menu
		if m.mode == ModeSessionMenu {
			return m.handleKeySessionMenu(msg)
		}

		// 3. User cancellation / stop stream
		if m.mode == ModeStreaming {
			if model, cmd := m.handleKeyStreaming(msg); model != nil {
				return model, cmd
			}
		}

		// 4. Double Ctrl+C to quit immediately
		if key == "ctrl+c" {
			if time.Since(m.lastCtrlC) < constants.DoubleCtrlCInterval {
				return m, tea.Quit
			}
			m.lastCtrlC = time.Now()
			m.quitHint = true
			m.updateViewportContent()
			return m, nil
		}
		m.quitHint = false

		// 5. Slash Command Palette Navigation
		if m.mode == ModePalette {
			if model, cmd := m.handleKeyPalette(msg); model != nil {
				return model, cmd
			}
		}

		// 6. Normal Input State
		if model, cmd := m.handleKeyNormal(msg); model != nil {
			return model, cmd
		}
	}

	oldVal := m.input.Value()
	oldPos := m.input.Position()

	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	cmds = append(cmds, cmd)

	newVal := m.input.Value()
	newPos := m.input.Position()

	wasPalette := m.mode == ModePalette
	if strings.HasPrefix(newVal, "/") {
		m.mode = ModePalette
		m.paletteQuery = strings.TrimPrefix(newVal, "/")
		m.fileMatches = nil
		m.fileSelectIdx = 0
	} else if wasPalette {
		m.mode = ModeNormal
	}

	// File completion update when typing @
	if m.mode == ModeNormal {
		q, atIdx := m.currentAtQuery()
		if atIdx >= 0 {
			matches := workspace.MatchFiles(m.cwd, q, 8)
			m.fileMatches = matches
			if m.fileSelectIdx >= len(matches) {
				m.fileSelectIdx = 0
			}
		} else {
			m.fileMatches = nil
			m.fileSelectIdx = 0
		}
	} else {
		m.fileMatches = nil
		m.fileSelectIdx = 0
	}

	if newVal != oldVal || newPos != oldPos || wasPalette != (m.mode == ModePalette) {
		m.updateViewportContent()
		m.viewport.GotoBottom()
	}

	return m, tea.Batch(cmds...)
}

func (m *AppModel) getFilteredCommands() []view.CommandEntry {
	allCmds := m.backend.Commands()
	var descList []core.CommandDescriptor
	for _, c := range allCmds {
		descList = append(descList, core.CommandDescriptor{
			Name:        c.Name,
			Description: c.Description,
		})
	}
	filtered := core.FilterCommands(descList, m.paletteQuery)
	res := make([]view.CommandEntry, len(filtered))
	for i, c := range filtered {
		res[i] = view.CommandEntry{
			Command:     c.Name,
			Description: c.Description,
		}
	}
	return res
}

// currentAtQuery inspects the input text before the cursor and returns
// the @ query and the byte offset where @ starts. Returns ("", -1) if no active @ mention.
func (m *AppModel) currentAtQuery() (string, int) {
	val := m.input.Value()
	pos := m.input.Position()
	if pos > len(val) {
		pos = len(val)
	}
	prefix := val[:pos]
	lastAt := strings.LastIndex(prefix, "@")
	if lastAt == -1 {
		return "", -1
	}
	// Verify that the character preceding '@' is either start of string or whitespace
	if lastAt > 0 && prefix[lastAt-1] != ' ' && prefix[lastAt-1] != '\t' {
		return "", -1
	}
	// If there's whitespace between the @ and cursor, the @ mention is closed/completed
	query := prefix[lastAt+1:]
	if strings.ContainsAny(query, " \t\n") {
		return "", -1
	}
	return query, lastAt
}

// insertSelectedFile replaces the current @query with the selected relative file path.
func (m *AppModel) insertSelectedFile() {
	if len(m.fileMatches) == 0 {
		return
	}
	idx := m.fileSelectIdx
	if idx >= len(m.fileMatches) {
		idx = len(m.fileMatches) - 1
	}
	if idx < 0 {
		idx = 0
	}
	chosen := m.fileMatches[idx]

	val := m.input.Value()
	pos := m.input.Position()
	if pos > len(val) {
		pos = len(val)
	}
	_, atIdx := m.currentAtQuery()
	if atIdx == -1 {
		return
	}

	before := val[:atIdx]
	after := val[pos:]
	newVal := before + "@" + chosen + " " + after
	m.input.SetValue(newVal)
	m.input.SetCursor(atIdx + 1 + len(chosen) + 1)
	m.fileMatches = nil
	m.fileSelectIdx = 0
}

func (m *AppModel) executeSelectedCommand() (tea.Model, tea.Cmd) {
	filtered := m.getFilteredCommands()
	if len(filtered) == 0 {
		return m, nil
	}
	idx := m.paletteIdx
	if idx >= len(filtered) {
		idx = len(filtered) - 1
	}
	if idx < 0 {
		idx = 0
	}
	selected := filtered[idx]
	m.input.Reset()
	m.setMode(ModeNormal)
	return m.handleSlashCommand(selected.Command)
}

func (m *AppModel) loadSession(path string) {
	viewSess, err := m.backend.ResumeSession(context.Background(), path)
	if err != nil {
		m.transcript = append(m.transcript, view.TranscriptItem{
			Role:    "system",
			Content: fmt.Sprintf("Failed to load session: %v", err),
		})
		m.updateViewportContent()
		m.viewport.GotoBottom()
		return
	}
	m.transcript = nil
	for _, ev := range viewSess.Events {
		switch ev.Role {
		case "user":
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "user",
				Content: ev.Delta,
			})
		case "bash":
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:     "bash",
				Content:  ev.Delta,
				ToolIcon: "!",
			})
		case "assistant":
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:    "assistant",
				Content: ev.Delta,
			})
		case "tool":
			if ev.ToolName == "bash" {
				for i := len(m.transcript) - 1; i >= 0; i-- {
					if m.transcript[i].Role == "bash" && m.transcript[i].ToolOutput == "" {
						m.transcript[i].ToolOutput = ev.ToolOutput
						break
					}
				}
				break
			}
			icon := constants.GlyphDone
			if ev.IsError {
				icon = constants.GlyphError
			}
			arg := view.PrimaryArg(ev.ToolInput)
			dispName := ev.ToolDisplayName
			if dispName == "" {
				dispName = ev.ToolName
			}
			logLine := fmt.Sprintf("%s(%s)", dispName, arg)
			outSummary := ev.ToolSummary
			if outSummary == "" {
				outSummary = ev.ToolOutput
			}
			m.transcript = append(m.transcript, view.TranscriptItem{
				Role:       "tool",
				Content:    logLine,
				ToolIcon:   icon,
				ToolName:   dispName,
				ToolArg:    arg,
				ToolOutput: outSummary,
			})
		}
	}
	m.staticTranscriptCache = ""
	m.cachedTranscriptLen = 0
	m.updateViewportContent()
	m.viewport.GotoBottom()
}

func (m *AppModel) getFilteredSessions() []view.SessionRow {
	if m.sessionQuery == "" {
		return m.sessions
	}
	q := strings.ToLower(m.sessionQuery)
	var filtered []view.SessionRow
	for _, s := range m.sessions {
		if strings.Contains(strings.ToLower(s.ID), q) || strings.Contains(strings.ToLower(s.Date), q) {
			filtered = append(filtered, s)
		}
	}
	return filtered
}

func (m *AppModel) updateViewportContent() {
	var sections []string

	// 1. Banner
	sections = append(sections, view.RenderBanner("0.1.0"))
	sections = append(sections, "")

	// 2. Transcript
	if len(m.transcript) > 0 {
		if m.cachedTranscriptWidth != m.width {
			m.staticTranscriptCache = ""
			m.cachedTranscriptLen = 0
			m.cachedTranscriptWidth = m.width
		}
		var renderedTranscript string
		renderedTranscript, m.staticTranscriptCache, m.cachedTranscriptLen = view.RenderTranscriptIncremental(
			m.transcript,
			m.width,
			m.animFrame,
			m.staticTranscriptCache,
			m.cachedTranscriptLen,
		)
		sections = append(sections, renderedTranscript)
		sections = append(sections, "")
	}

	// 3. Unified Bottom Dock
	dockProps := view.DockProps{
		Width:           m.width,
		Kind:            view.DockNone,
		InputVal:        m.input.Value(),
		CursorPos:       m.input.Position(),
		IsStreaming:     m.mode == ModeStreaming,
		IsBashMode:      m.mode == ModeBash,
		SpinnerFrame:    m.animFrame,
		ModelName:       m.modelName,
		QuitHint:        m.quitHint,
		ConfirmSelected: m.confirmSelected,
		IsReviewing:     m.mode == ModeReviewing,
		ReviewOffset:    m.reviewOffset,
	}

	if (m.mode == ModeConfirming || m.mode == ModeReviewing) && m.pendingConfirm != nil {
		dockProps.Kind = view.DockToolConfirm
		var confLines []view.ConfirmationLine
		for _, l := range m.pendingConfirm.Lines {
			kind := view.LineNeutral
			switch l.Kind {
			case core.LineAddition:
				kind = view.LineAddition
			case core.LineDeletion:
				kind = view.LineDeletion
			}
			confLines = append(confLines, view.ConfirmationLine{
				Kind:       kind,
				LineNumber: l.LineNumber,
				Prefix:     l.Prefix,
				Text:       l.Text,
			})
		}
		dockProps.Confirmation = view.ConfirmationView{
			ToolName:    m.pendingConfirm.ToolName,
			Title:       m.pendingConfirm.Title,
			Subtitle:    m.pendingConfirm.Subtitle,
			Question:    m.pendingConfirm.Question,
			IsDiff:      m.pendingConfirm.PreviewKind == core.PreviewDiff,
			Lines:       confLines,
			RawFallback: m.pendingConfirm.RawArgs,
		}
		dockProps.ConfirmSelected = m.confirmSelected
		dockProps.IsReviewing = m.mode == ModeReviewing
		dockProps.ReviewOffset = m.reviewOffset
		dockProps.Cwd = m.cwd
	} else if m.mode == ModeSessionMenu {
		dockProps.Kind = view.DockSessionMenu
		dockProps.Sessions = m.getFilteredSessions()
		dockProps.SelectedSess = m.selectedSess
		dockProps.SessionQuery = m.sessionQuery
	} else if m.mode == ModePalette {
		dockProps.Kind = view.DockCommandPalette
		dockProps.PaletteCommands = m.getFilteredCommands()
		dockProps.PaletteIdx = m.paletteIdx
	} else if m.mode == ModeHelp {
		dockProps.Kind = view.DockHelpMenu
	} else if len(m.fileMatches) > 0 {
		dockProps.Kind = view.DockFileMatches
		dockProps.FileMatches = m.fileMatches
		dockProps.FileSelectIdx = m.fileSelectIdx
	}

	dock := view.RenderUnifiedDock(dockProps)
	sections = append(sections, dock)

	m.viewport.SetContent(strings.Join(sections, "\n"))
}

func (m *AppModel) View() tea.View {
	v := tea.NewView(m.viewport.View())
	v.AltScreen = false
	v.MouseMode = tea.MouseModeCellMotion
	return v
}

package view

import (
	"fmt"
	"strings"

	"charm.land/lipgloss/v2"
)

// DiffPaginator renders a slice of confirmation preview lines into a paginated or capped window.
type DiffPaginator struct {
	MaxPreviewNonDiff int
	MaxPreviewDiff    int
	ReviewWindowSize  int
}

// DefaultDiffPaginator provides standard review window and preview cap defaults.
func DefaultDiffPaginator() DiffPaginator {
	return DiffPaginator{
		MaxPreviewNonDiff: 6,
		MaxPreviewDiff:    8,
		ReviewWindowSize:  10,
	}
}

// RenderPreview renders lines with standard truncation or interactive review navigation.
func (dp DiffPaginator) RenderPreview(conf ConfirmationView, isReviewing bool, reviewOffset, width int) string {
	if len(conf.Lines) == 0 {
		if conf.RawFallback != "" {
			return StyleDim.Render("  " + conf.RawFallback)
		}
		return ""
	}

	wrapWidth := width - 10
	if wrapWidth < 10 {
		wrapWidth = 10
	}
	contentWidth := width - 4
	if contentWidth < 10 {
		contentWidth = 10
	}

	deleteStyle := lipgloss.NewStyle().
		Background(lipgloss.Color(ColorDiffDeleteBG)).
		Foreground(lipgloss.Color(ColorDiffDeleteFG))

	addStyle := lipgloss.NewStyle().
		Background(lipgloss.Color(ColorDiffAddBG)).
		Foreground(lipgloss.Color(ColorDiffAddFG))

	pointerStyle := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorLavenderLight))
	textStyle := StyleText

	type visualLineItem struct {
		isDelete bool
		isAdd    bool
		prefix   string
		text     string
	}

	var allVisual []visualLineItem
	for _, l := range conf.Lines {
		var prefix string
		if conf.IsDiff {
			if l.LineNumber > 0 && l.Prefix != "" {
				prefix = fmt.Sprintf("%3d %s ", l.LineNumber, l.Prefix)
			} else if l.Prefix != "" {
				prefix = l.Prefix + " "
			}
		}
		wrapped := WrapText(l.Text, wrapWidth)
		if len(wrapped) == 0 {
			wrapped = []string{""}
		}
		for subIdx, w := range wrapped {
			p := prefix
			if subIdx > 0 && prefix != "" {
				p = strings.Repeat(" ", len(prefix))
			}
			allVisual = append(allVisual, visualLineItem{
				isDelete: l.Kind == LineDeletion,
				isAdd:    l.Kind == LineAddition,
				prefix:   p,
				text:     w,
			})
		}
	}

	total := len(allVisual)
	if total == 0 {
		return ""
	}

	renderItem := func(item visualLineItem) string {
		fullText := item.prefix + item.text
		if item.isDelete {
			return deleteStyle.Width(contentWidth).Render(fullText)
		}
		if item.isAdd {
			return addStyle.Width(contentWidth).Render(fullText)
		}
		return textStyle.Render(fullText)
	}

	if isReviewing {
		if reviewOffset < 0 {
			reviewOffset = 0
		}
		if reviewOffset >= total {
			reviewOffset = total - 1
		}

		window := dp.ReviewWindowSize
		if window <= 0 {
			window = 10
		}
		start := 0
		if reviewOffset >= window {
			start = reviewOffset - window + 1
		}
		end := start + window
		if end > total {
			end = total
		}

		var res []string
		for i := start; i < end; i++ {
			item := allVisual[i]
			styled := renderItem(item)
			var line string
			if i == reviewOffset {
				line = pointerStyle.Render("> ") + styled
			} else {
				line = "  " + styled
			}
			res = append(res, line)
		}
		return strings.Join(res, "\n")
	}

	maxPreview := dp.MaxPreviewDiff
	if !conf.IsDiff {
		maxPreview = dp.MaxPreviewNonDiff
	}
	if total < maxPreview {
		maxPreview = total
	}

	var res []string
	for i := 0; i < maxPreview; i++ {
		res = append(res, "  "+renderItem(allVisual[i]))
	}
	if total > maxPreview {
		res = append(res, StyleDim.Render(fmt.Sprintf("  ... (%d more lines, press 'f' to review)", total-maxPreview)))
	}
	return strings.Join(res, "\n")
}

package view

import (
	"fmt"
	"strings"

	"charm.land/lipgloss/v2"
)

// SessionRow represents a presentation-only summary of a session.
type SessionRow struct {
	ID   string
	Path string
	Date string
}

// ConfirmationLineKind indicates whether a preview line is neutral, addition, or deletion.
type ConfirmationLineKind int

const (
	LineNeutral ConfirmationLineKind = iota
	LineAddition
	LineDeletion
)

// ConfirmationLine represents a single rendered preview line.
type ConfirmationLine struct {
	Kind       ConfirmationLineKind
	LineNumber int
	Prefix     string
	Text       string
}

// ConfirmationView contains pure presentation data for a tool confirmation prompt.
type ConfirmationView struct {
	ToolName    string
	Title       string
	Subtitle    string
	Question    string
	IsDiff      bool
	Lines       []ConfirmationLine
	RawFallback string
}

// DockKind represents which modal or dropdown is docked.
type DockKind int

const (
	DockNone DockKind = iota
	DockCommandPalette
	DockSessionMenu
	DockToolConfirm
	DockHelpMenu
	DockFileMatches
)

// DockProps contains all properties needed to render the unified dock.
type DockProps struct {
	Width        int
	Kind         DockKind
	InputVal     string
	CursorPos    int
	IsStreaming  bool
	SpinnerFrame int
	IsBashMode   bool

	// Statusline props
	ModelName string
	QuitHint  bool

	// Palette props
	PaletteCommands []CommandEntry
	PaletteIdx      int

	// File completion props
	FileMatches   []string
	FileSelectIdx int

	// Session menu props
	Sessions     []SessionRow
	SelectedSess int
	SessionQuery string

	// Tool confirm props
	Confirmation    ConfirmationView
	ConfirmSelected int
	IsReviewing     bool
	ReviewOffset    int
	Cwd             string
}

// RenderUnifiedDock renders the single standardized dock component matching Claude Code:
func RenderUnifiedDock(props DockProps) string {
	var sections []string

	switch props.Kind {
	case DockToolConfirm:
		// Tool confirmation card takes over the bottom dock area
		card := RenderToolConfirmCard(props.Confirmation, props.ConfirmSelected, props.IsReviewing, props.ReviewOffset, props.Width)
		sections = append(sections, card)

	case DockCommandPalette:
		inputBar := RenderInputBar(props.Width, props.InputVal, props.CursorPos, props.IsStreaming, props.SpinnerFrame, props.IsBashMode)
		sections = append(sections, inputBar)

		palette := RenderCommandPalette(props.PaletteCommands, props.PaletteIdx, props.Width)
		if palette != "" {
			sections = append(sections, palette)
		}

	case DockSessionMenu:
		inputVal := props.InputVal
		if inputVal == "" {
			inputVal = "/resume"
		}
		inputBar := RenderInputBar(props.Width, inputVal, len(inputVal), props.IsStreaming, props.SpinnerFrame, false)
		sections = append(sections, inputBar)

		menu := RenderSessionMenu(props.Sessions, props.SelectedSess, props.Width, props.SessionQuery)
		if menu != "" {
			sections = append(sections, menu)
		}

	case DockHelpMenu:
		inputBar := RenderInputBar(props.Width, props.InputVal, props.CursorPos, props.IsStreaming, props.SpinnerFrame, props.IsBashMode)
		sections = append(sections, inputBar)

		help := RenderHelpDock(props.Width)
		sections = append(sections, help)

	case DockFileMatches:
		inputBar := RenderInputBar(props.Width, props.InputVal, props.CursorPos, props.IsStreaming, props.SpinnerFrame, props.IsBashMode)
		sections = append(sections, inputBar)

		matches := RenderFileMatches(props.FileMatches, props.FileSelectIdx, props.Width)
		if matches != "" {
			sections = append(sections, matches)
		}

	default:
		inputBar := RenderInputBar(props.Width, props.InputVal, props.CursorPos, props.IsStreaming, props.SpinnerFrame, props.IsBashMode)
		sections = append(sections, inputBar)

		status := RenderStatusLine(props.Width, props.ModelName, 0, 0, "", props.QuitHint)
		sections = append(sections, status)
	}

	return strings.Join(sections, "\n")
}

// RenderBanner generates a clean, minimal welcome banner:
// Just the clean title and brief command hint (no ASCII logo, no wordy description).
func RenderBanner(version string) string {
	title := StyleBrand.Bold(true).Render("Delta")
	ver := StyleInfo.Render(fmt.Sprintf("v%s", version))
	dim := StyleDim
	brand := StyleBrand

	line1 := fmt.Sprintf("%s %s", title, ver)
	line2 := dim.Render("Type ") + brand.Render("/") + dim.Render(" for commands")

	return lipgloss.JoinVertical(lipgloss.Left, line1, line2)
}

// CommandEntry describes a slash command row in the palette.
type CommandEntry struct {
	Command     string
	Description string
}

// RenderCommandPalette renders Claude Code's docked command list directly below prompt.
// It receives pre-filtered command rows and selected index.
func RenderCommandPalette(commands []CommandEntry, selectedIdx int, width int) string {
	if len(commands) == 0 {
		return ""
	}

	if width < 20 {
		width = 80
	}

	if selectedIdx >= len(commands) {
		selectedIdx = len(commands) - 1
	}
	if selectedIdx < 0 {
		selectedIdx = 0
	}

	var lines []string
	for i, item := range commands {
		prefix := "  "
		cmdColWidth := 16
		if i == selectedIdx {
			prefix = StyleLavenderLight.Render(GlyphPrompt)
			cmdStyled := StyleText.Render(padRight(item.Command, cmdColWidth))
			descStyled := StyleText.Render(item.Description)
			lines = append(lines, prefix+cmdStyled+" "+descStyled)
		} else {
			cmdStyled := StyleLavender.Render(padRight(item.Command, cmdColWidth))
			descStyled := StyleDim.Render(item.Description)
			lines = append(lines, prefix+cmdStyled+" "+descStyled)
		}
	}

	return strings.Join(lines, "\n")
}

// RenderToolConfirmCard renders Claude Code's canonical docked PermissionDialog with diff review and line navigation.
func RenderToolConfirmCard(conf ConfirmationView, selectedIdx int, isReviewing bool, reviewOffset int, width int) string {
	if width < 20 {
		width = 80
	}

	dividerRule := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorLavenderHeader)).
		Render(strings.Repeat("─", width))

	dashedRule := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorBorderSubtle)).
		Render(strings.Repeat("┄", width))

	titleText := conf.Title
	if titleText == "" {
		titleText = conf.ToolName
	}
	questionText := conf.Question
	if questionText == "" {
		questionText = StyleText.Render("Do you want to proceed?")
	} else {
		questionText = StyleText.Render(questionText)
	}

	titleStyled := StyleLavender.Render(titleText)
	subtitleStyled := StyleMuted.Render(conf.Subtitle)

	previewBox := renderConfirmationLinesPreview(conf, isReviewing, reviewOffset, width)

	options := []struct {
		num  string
		text string
	}{
		{"1", "Yes"},
		{"2", "Yes, allow for session"},
		{"3", "No"},
	}

	var optLines []string
	for i, opt := range options {
		var line string
		if i == selectedIdx {
			pointer := StyleLavenderLight.Render("❯ ")
			numLabel := StyleText.Render(opt.num + ". ")
			optText := StyleText.Render(opt.text)
			line = pointer + numLabel + optText
		} else {
			line = "  " + StyleDim.Render(opt.num+". "+opt.text)
		}
		optLines = append(optLines, line)
	}

	var footer string
	if isReviewing {
		footer = StyleMuted.Italic(true).Render("f / Esc to return to options  ·  Enter / 1-3 to confirm  ·  ↑/↓ to move line")
	} else {
		footer = StyleMuted.Italic(true).Render("Esc to cancel  ·  f to review diff/preview  ·  Enter to select")
	}

	var parts []string
	parts = append(parts, dividerRule, titleStyled)
	if conf.Subtitle != "" {
		parts = append(parts, subtitleStyled)
	}
	if previewBox != "" {
		parts = append(parts, dashedRule, previewBox, dashedRule)
	}
	parts = append(parts, questionText, strings.Join(optLines, "\n"), footer)

	return strings.Join(parts, "\n")
}

func renderConfirmationLinesPreview(conf ConfirmationView, isReviewing bool, reviewOffset, width int) string {
	return DefaultDiffPaginator().RenderPreview(conf, isReviewing, reviewOffset, width)
}

// RenderHelpDock renders the Claude Code shortcuts help menu:
// - Lavender top divider
// - Title "Shortcuts"
// - 3-column shortcut layout
// - Muted Esc to cancel footer
func RenderHelpDock(width int) string {
	if width < 20 {
		width = 80
	}

	divider := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorLavenderHeader)).
		Render(strings.Repeat("─", width))

	header := StyleLavender.Render("Shortcuts")

	col1 := []string{
		"! for bash mode",
		"/ for commands",
		"@ for file paths",
		"/resume for sessions",
	}

	col2 := []string{
		"double tap esc to clear",
		"ctrl + c to cancel / exit",
		"pgup / pgdn to scroll",
		"\\ + return for newline",
	}

	col3 := []string{
		"/model to change model",
		"/clear to clear context",
		"/new to start new session",
		"? for shortcuts",
	}

	dim := StyleDim
	var rows []string
	for i := 0; i < len(col1); i++ {
		row := fmtRow(col1[i], col2[i], col3[i], width)
		rows = append(rows, dim.Render(row))
	}

	footer := StyleMuted.Italic(true).Render("Esc to cancel")

	return divider + "\n" + header + "\n\n" + strings.Join(rows, "\n") + "\n\n" + footer
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func fmtRow(c1, c2, c3 string, width int) string {
	colWidth := (width - 4) / 3
	if colWidth < 22 {
		colWidth = 22
	}
	s1 := padRight(c1, colWidth)
	s2 := padRight(c2, colWidth)
	return "  " + s1 + " " + s2 + " " + c3
}

// RenderSessionMenu renders Claude Code's canonical Resume Session dock:
func RenderSessionMenu(sessions []SessionRow, selectedIdx int, width int, searchQuery string) string {
	if width < 20 {
		width = 80
	}

	dividerRule := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorLavenderHeader)).
		Render(strings.Repeat("─", width))

	dashedRule := lipgloss.NewStyle().
		Foreground(lipgloss.Color(ColorBorderSubtle)).
		Render(strings.Repeat("┄", width))

	header := StyleLavender.Render("Resume Session")

	var searchContent string
	cursorBlock := lipgloss.NewStyle().
		Background(lipgloss.Color(ColorTextWhite)).
		Foreground(lipgloss.Color(ColorTextBlack)).
		Render(" ")

	if searchQuery == "" {
		searchContent = "  " + StyleMuted.Render(GlyphSearch) + cursorBlock + StyleDim.Render(" Search sessions…")
	} else {
		searchContent = "  " + StyleMuted.Render(GlyphSearch) + StyleText.Render(searchQuery) + cursorBlock
	}

	var lines []string
	lines = append(lines, dividerRule, header, "", searchContent, dashedRule)

	if len(sessions) == 0 {
		lines = append(lines, StyleMuted.Render("  No saved sessions found."))
		lines = append(lines, "", StyleMuted.Italic(true).Render("Esc to cancel"))
		return strings.Join(lines, "\n")
	}

	if selectedIdx >= len(sessions) {
		selectedIdx = len(sessions) - 1
	}

	start := 0
	if selectedIdx >= 6 {
		start = selectedIdx - 5
	}
	end := len(sessions)
	if end > start+6 {
		end = start + 6
	}

	for i := start; i < end; i++ {
		sess := sessions[i]
		shortID := sess.ID
		if len(shortID) > 8 {
			shortID = shortID[:8]
		}

		if i == selectedIdx {
			pointer := StyleLavenderLight.Render(GlyphPrompt)
			title := StyleText.Render("session " + shortID)
			meta := StyleMuted.Render(fmt.Sprintf("%s · HEAD", sess.Date))
			lines = append(lines, pointer+title, "  "+meta)
		} else {
			title := StyleDim.Render("session " + shortID)
			meta := StyleMuted.Render(fmt.Sprintf("%s · HEAD", sess.Date))
			lines = append(lines, "  "+title, "  "+meta)
		}
	}

	footer := StyleMuted.Italic(true).Render(HintSessionDock)
	lines = append(lines, "", footer)

	return strings.Join(lines, "\n")
}

// FormatTokens formats an integer count into compact human-readable notation (e.g. 500, 1.2K, 3.4M, 1.1B).
func FormatTokens(n int) string {
	if n < 0 {
		return "0"
	}
	f := float64(n)
	switch {
	case f >= 1_000_000_000:
		return fmt.Sprintf("%.1fB", f/1_000_000_000)
	case f >= 1_000_000:
		return fmt.Sprintf("%.1fM", f/1_000_000)
	case f >= 1_000:
		return fmt.Sprintf("%.1fK", f/1_000)
	default:
		return fmt.Sprintf("%d", n)
	}
}

// RenderStatusLine renders the bottom row status bar matching Claude Code:
func RenderStatusLine(width int, modelName string, inTokens int, outTokens int, sessionIDShort string, quitHint bool) string {
	if width < 20 {
		width = 80
	}
	dim := StyleDim
	errStyle := StyleError
	muted := StyleMuted

	if quitHint {
		return errStyle.Render(" ▸ ") + dim.Render("Press ") + errStyle.Render("Ctrl+C") + dim.Render(" again to exit")
	}

	left := muted.Render(HintShortcuts)

	var right string
	if modelName != "" {
		right = dim.Render(modelName) + " "
	}

	leftLen := lipgloss.Width(left)
	rightLen := lipgloss.Width(right)
	space := width - leftLen - rightLen
	if space < 0 {
		space = 0
	}

	return left + strings.Repeat(" ", space) + right
}

// RenderFileMatches renders matched file paths directly under the input bar.
func RenderFileMatches(files []string, selectedIdx int, width int) string {
	if len(files) == 0 {
		return ""
	}
	if width < 20 {
		width = 80
	}
	if selectedIdx >= len(files) {
		selectedIdx = len(files) - 1
	}
	if selectedIdx < 0 {
		selectedIdx = 0
	}

	var lines []string
	header := StyleMuted.Render("  Matching files (@):")
	lines = append(lines, header)

	for i, f := range files {
		prefix := "    "
		if i == selectedIdx {
			prefix = "  " + StyleLavenderLight.Render(GlyphPrompt)
			lines = append(lines, prefix+StyleText.Bold(true).Render(f))
		} else {
			lines = append(lines, prefix+StyleDim.Render(f))
		}
	}
	return strings.Join(lines, "\n")
}

package view

import (
	"strings"

	"charm.land/lipgloss/v2"
)

// RenderInputBar renders the input prompt matching Claude Code:
// - Top & bottom horizontal border rules in ColorBorderDivider (#6E6E6E)
// - Prompt symbol ❯ in crisp white (or vibrant pink in bash mode)
// - Smart line wrapping for large input texts with left padding aligning subsequent lines to prompt
// - Solid cursor block
// - Animated traveling wave status sweep when streaming
func RenderInputBar(width int, inputVal string, cursor int, isStreaming bool, spinnerFrame int, isBashMode bool) string {
	if width < 20 {
		width = 80
	}

	borderColor := lipgloss.Color(ColorBorderDivider)
	if isBashMode {
		borderColor = lipgloss.Color(ColorBashPink)
	} else if SafeMode() {
		borderColor = lipgloss.Color("8") // DarkGray
	}

	// Status verbs cycling with a delay when streaming
	statusWords := []string{
		"thinking…",
		"analyzing…",
		"exploring…",
		"computing…",
		"crafting…",
		"generating…",
	}
	currentWordIdx := (spinnerFrame / StatusWordCycleDelay) % len(statusWords)
	currentWord := statusWords[currentWordIdx]

	wavePos := (spinnerFrame / 2) % (len([]rune(currentWord)) + 5)
	shadedText := renderSweepingText(currentWord, wavePos)

	spinnerGlyphs := []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧"}
	glyph := spinnerGlyphs[(spinnerFrame/4)%len(spinnerGlyphs)]
	styledGlyph := StyleBrand.Render(glyph)

	topBorder := lipgloss.NewStyle().Foreground(borderColor).Render(strings.Repeat("─", width))
	bottomBorder := lipgloss.NewStyle().Foreground(borderColor).Render(strings.Repeat("─", width))

	aboveBorder := ""
	if isStreaming {
		aboveBorder = styledGlyph + " " + shadedText + "\n"
	}

	promptSymbol := GlyphPrompt
	promptStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorPromptChevron))
	if isBashMode {
		promptSymbol = "! "
		promptStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBashPink))
	}

	dim := StyleDim
	textStyle := StyleText
	cursorStyle := lipgloss.NewStyle().
		Background(lipgloss.Color(ColorTextWhite)).
		Foreground(lipgloss.Color(ColorTextBlack))

	valRunes := []rune(inputVal)
	cursorToken := "\x00"

	var textWithCursor string
	if cursor >= len(valRunes) {
		textWithCursor = string(valRunes) + cursorToken
	} else {
		textWithCursor = string(valRunes[:cursor]) + cursorToken + string(valRunes[cursor:])
	}

	rawLogicalLines := strings.Split(textWithCursor, "\n")
	wrapWidth := width - 4
	if wrapWidth < 10 {
		wrapWidth = 10
	}

	var visualLines []string

	for lineIdx, rawLogical := range rawLogicalLines {
		wrapped := SmartWrapLine(rawLogical, wrapWidth)
		for subIdx, wLine := range wrapped {
			var linePrefix string
			if lineIdx == 0 && subIdx == 0 {
				linePrefix = promptStyle.Render(promptSymbol)
			} else {
				linePrefix = dim.Render(GlyphPromptPad)
			}

			if strings.Contains(wLine, cursorToken) {
				parts := strings.SplitN(wLine, cursorToken, 2)
				before := parts[0]
				after := parts[1]

				atChar := " "
				if len(after) > 0 {
					afterRunes := []rune(after)
					atChar = string(afterRunes[0])
					after = string(afterRunes[1:])
				}
				renderedLine := linePrefix + textStyle.Render(before) + cursorStyle.Render(atChar) + textStyle.Render(after)
				visualLines = append(visualLines, renderedLine)
			} else {
				visualLines = append(visualLines, linePrefix+textStyle.Render(wLine))
			}
		}
	}

	content := strings.Join(visualLines, "\n")
	return aboveBorder + topBorder + "\n" + content + "\n" + bottomBorder
}

func renderSweepingText(text string, wavePos int) string {
	runes := []rune(text)
	var b strings.Builder

	dimStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorSubtle)).Italic(true)
	shoulderStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBrandTerracotta)).Italic(true)
	peakStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBrandPeak)).Italic(true)

	for i, r := range runes {
		dist := i - (wavePos - 2)
		switch dist {
		case 1:
			b.WriteString(peakStyle.Render(string(r)))
		case 0, 2:
			b.WriteString(shoulderStyle.Render(string(r)))
		default:
			b.WriteString(dimStyle.Render(string(r)))
		}
	}
	return b.String()
}

package view

import (
	"strings"
	"testing"
)

func TestRenderInputBarSmartWrap(t *testing.T) {
	width := 30
	longText := "This is a very long input text that should wrap cleanly across multiple lines with proper indentation."
	rendered := RenderInputBar(width, longText, len([]rune(longText)), false, 0, false)

	lines := strings.Split(rendered, "\n")
	if len(lines) < 4 {
		t.Errorf("expected multiline wrapped output, got %d lines: %s", len(lines), rendered)
	}

	// First content line starts with prompt symbol ❯
	contentLine1 := lines[1]
	if !strings.Contains(contentLine1, "❯") {
		t.Errorf("expected first line to contain prompt symbol, got: %s", contentLine1)
	}

	// Subsequent content lines should be indented with padding
	contentLine2 := lines[2]
	if !strings.HasPrefix(contentLine2, "  ") && !strings.Contains(contentLine2, "  ") {
		t.Errorf("expected second line to have left padding indentation, got: %s", contentLine2)
	}
}

package view_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/sapirrior/delta/internal/tui/view"
)

func TestCharacterizationCommandPalette(t *testing.T) {
	allCmds := []view.CommandEntry{
		{Command: "/model", Description: "Set or display the active model"},
		{Command: "/new", Description: "Start a new session and reset context"},
		{Command: "/clear", Description: "Clear transcript and conversation context"},
		{Command: "/resume", Description: "Resume a previous session from history"},
		{Command: "/exit", Description: "Exit Delta"},
	}

	// 1. All commands
	outAll := view.RenderCommandPalette(allCmds, 0, 80)
	if !strings.Contains(outAll, "/model") || !strings.Contains(outAll, "/exit") {
		t.Errorf("expected all commands in palette, got: %s", outAll)
	}

	// 2. Specific filtered subset
	modelOnly := []view.CommandEntry{
		{Command: "/model", Description: "Set or display the active model"},
	}
	outModel := view.RenderCommandPalette(modelOnly, 0, 80)
	if !strings.Contains(outModel, "/model") {
		t.Errorf("expected /model in query 'model', got: %s", outModel)
	}
	if strings.Contains(outModel, "/new") {
		t.Errorf("did not expect /new in query 'model', got: %s", outModel)
	}

	// 3. No match
	outNone := view.RenderCommandPalette(nil, 0, 80)
	if outNone != "" {
		t.Errorf("expected empty string for empty commands, got: %q", outNone)
	}
}

func TestCharacterizationConfirmCard(t *testing.T) {
	width := 80

	// 1. run_command confirmation
	cardCmd := view.RenderToolConfirmCard(view.ConfirmationView{
		ToolName: "run_command",
		Title:    "Bash command",
		Question: "Do you want to proceed?",
		IsDiff:   false,
		Lines: []view.ConfirmationLine{
			{Kind: view.LineNeutral, Text: "echo 'hello world'"},
			{Kind: view.LineNeutral, Text: "ls -la"},
		},
	}, 0, false, 0, width)
	if !strings.Contains(cardCmd, "Bash command") || !strings.Contains(cardCmd, "Do you want to proceed?") {
		t.Errorf("expected Bash command prompt, got: %s", cardCmd)
	}
	if !strings.Contains(cardCmd, "echo 'hello world'") {
		t.Errorf("expected command preview in card, got: %s", cardCmd)
	}

	// 2. write_file confirmation
	cardWrite := view.RenderToolConfirmCard(view.ConfirmationView{
		ToolName: "write_file",
		Title:    "Create file",
		Subtitle: "src/test.txt",
		Question: "Do you want to create test.txt?",
		IsDiff:   true,
		Lines: []view.ConfirmationLine{
			{Kind: view.LineAddition, LineNumber: 1, Prefix: "+", Text: "line 1"},
			{Kind: view.LineAddition, LineNumber: 2, Prefix: "+", Text: "line 2"},
		},
	}, 1, false, 0, width)
	if !strings.Contains(cardWrite, "Create file") || !strings.Contains(cardWrite, "src/test.txt") {
		t.Errorf("expected Create file prompt, got: %s", cardWrite)
	}
	if !strings.Contains(cardWrite, "1 + line 1") {
		t.Errorf("expected diff addition line in write preview, got: %s", cardWrite)
	}

	// 3. edit_file confirmation
	cardEdit := view.RenderToolConfirmCard(view.ConfirmationView{
		ToolName: "edit_file",
		Title:    "Edit file",
		Subtitle: "main.go",
		Question: "Do you want to make this edit to main.go?",
		IsDiff:   true,
		Lines: []view.ConfirmationLine{
			{Kind: view.LineDeletion, LineNumber: 1, Prefix: "-", Text: "oldCode()"},
			{Kind: view.LineAddition, LineNumber: 1, Prefix: "+", Text: "newCode()"},
		},
	}, 0, false, 0, width)
	if !strings.Contains(cardEdit, "Edit file") || !strings.Contains(cardEdit, "main.go") {
		t.Errorf("expected Edit file prompt, got: %s", cardEdit)
	}
	if !strings.Contains(cardEdit, "oldCode()") || !strings.Contains(cardEdit, "newCode()") {
		t.Errorf("expected target and replacement in edit diff preview, got: %s", cardEdit)
	}
}

func TestCharacterizationTranscriptRendering(t *testing.T) {
	width := 80
	items := []view.TranscriptItem{
		{Role: "user", Content: "Hello assistant!"},
		{Role: "thought", Content: "Thinking about the user query..."},
		{Role: "tool", ToolIcon: view.GlyphDone, ToolName: "read_file", ToolArg: "main.go", ToolOutput: "Read 42 lines"},
		{Role: "assistant", Content: "Here is your response with **markdown** formatting."},
	}

	rendered, staticPrefix, staticLen := view.RenderTranscriptIncremental(items, width, 0, "", 0)
	if rendered == "" {
		t.Fatal("expected non-empty rendered transcript")
	}
	if !strings.Contains(rendered, "Hello assistant!") {
		t.Errorf("rendered transcript missing user message")
	}
	if !strings.Contains(rendered, "Thinking about the user query") {
		t.Errorf("rendered transcript missing thought")
	}
	if !strings.Contains(rendered, "Read 42 lines") {
		t.Errorf("rendered transcript missing tool output")
	}
	if staticLen == 0 || staticPrefix == "" {
		t.Errorf("expected staticLen > 0 and non-empty staticPrefix, got len=%d", staticLen)
	}
}

func generateTranscriptItems(n int) []view.TranscriptItem {
	var items []view.TranscriptItem
	for i := 0; i < n; i++ {
		switch i % 4 {
		case 0:
			items = append(items, view.TranscriptItem{
				Role:    "user",
				Content: fmt.Sprintf("User query turn %d: please inspect the file.", i),
			})
		case 1:
			items = append(items, view.TranscriptItem{
				Role:    "thought",
				Content: fmt.Sprintf("Considering optimal strategy for turn %d...", i),
			})
		case 2:
			items = append(items, view.TranscriptItem{
				Role:       "tool",
				ToolIcon:   view.GlyphDone,
				ToolName:   "read_file",
				ToolArg:    fmt.Sprintf("file_%d.go", i),
				ToolOutput: "Read 100 lines",
			})
		case 3:
			items = append(items, view.TranscriptItem{
				Role:    "assistant",
				Content: fmt.Sprintf("Here is the completed response for step %d with detailed information.", i),
			})
		}
	}
	return items
}

func BenchmarkTranscriptRendering(b *testing.B) {
	sizes := []int{10, 50, 100, 500}
	for _, size := range sizes {
		items := generateTranscriptItems(size)
		b.Run(fmt.Sprintf("Items_%d", size), func(b *testing.B) {
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				_, _, _ = view.RenderTranscriptIncremental(items, 80, 0, "", 0)
			}
		})
	}
}

func BenchmarkStreamingAssistantMessage(b *testing.B) {
	items := generateTranscriptItems(50)
	activeItem := view.TranscriptItem{
		Role:    "assistant",
		Content: strings.Repeat("Streaming word by word in the assistant response to test markdown thrashing. ", 10),
	}
	items = append(items, activeItem)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		items[len(items)-1].Content += " extra token"
		_, _, _ = view.RenderTranscriptIncremental(items, 80, i, "", 0)
	}
}

