// UI Glyphs & Symbols const ( GlyphPrompt = "❯ " GlyphPromptPad = " " GlyphBullet = "● " GlyphTreeElbow = "└ " GlyphSearch = "⌕ " GlyphPending = "◉" GlyphDone = "●" GlyphError = "✕" GlyphTriangle = "▲" )
// UI Timing & Hints const ( StatusWordCycleDelay = 5 HintSessionDock = "Type to Search · Enter to select · Esc to clear" HintShortcuts = "? for shortcuts" )
