// Lipgloss styles with clean unbolded text styling (except banner/markdown) var ( StyleText = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextWhite)) StyleDim = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextDim)) StyleMuted = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextMuted)) StyleBrand = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBrandTerracotta)) StyleError = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorErrorRed)) StyleSuccess = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorSuccessGreen)) StyleWarning = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorWarningYellow)) StyleInfo = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorInfoBlue)) StyleLavender = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorLavenderHeader)) StyleLavenderLight = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorLavenderLight)) StyleBorder = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBorderDivider)) StyleSubtle = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorSubtle)) )
// ContextPctStyle returns contextual style based on percentage usage. func ContextPctStyle(pct int) lipgloss.Style { switch { case pct < 60: return StyleSuccess case pct < 80: return StyleWarning default: return StyleError } }

package view

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"sync"
	"unicode"

	"charm.land/glamour/v2"
	"charm.land/lipgloss/v2"
)

var ansiRegex = regexp.MustCompile(`\x1b\[[0-9;]*[a-zA-Z]`)

func stripANSI(s string) string {
	return ansiRegex.ReplaceAllString(s, "")
}

var (
	rendererMu   sync.Mutex
	cachedWidth  int
	cachedRender *glamour.TermRenderer

	mdCacheMu sync.RWMutex
	mdCache   = make(map[string]string)

	itemCacheMu sync.RWMutex
	itemCache   = make(map[string]string)
)

func getItemCache(key string) (string, bool) {
	itemCacheMu.RLock()
	val, ok := itemCache[key]
	itemCacheMu.RUnlock()
	return val, ok
}

func setItemCache(key, val string) {
	itemCacheMu.Lock()
	if len(itemCache) > 1000 {
		itemCache = make(map[string]string)
	}
	itemCache[key] = val
	itemCacheMu.Unlock()
}

func getGlamourRenderer(width int) (*glamour.TermRenderer, error) {
	rendererMu.Lock()
	defer rendererMu.Unlock()

	if cachedRender != nil && cachedWidth == width {
		return cachedRender, nil
	}

	r, err := glamour.NewTermRenderer(
		glamour.WithStandardStyle("dark"),
		glamour.WithWordWrap(width),
	)
	if err == nil {
		cachedRender = r
		cachedWidth = width
	}
	return r, err
}

func renderMarkdownCached(content string, wrapWidth int) (string, error) {
	cacheKey := fmt.Sprintf("%d:%s", wrapWidth, content)
	mdCacheMu.RLock()
	if cached, ok := mdCache[cacheKey]; ok {
		mdCacheMu.RUnlock()
		return cached, nil
	}
	mdCacheMu.RUnlock()

	r, err := getGlamourRenderer(wrapWidth)
	if err != nil {
		return "", err
	}

	out, err := r.Render(content)
	if err == nil {
		mdCacheMu.Lock()
		// Bound cache size
		if len(mdCache) > 500 {
			mdCache = make(map[string]string)
		}
		mdCache[cacheKey] = out
		mdCacheMu.Unlock()
	}
	return out, err
}

// TranscriptItem models a rendered turn or log line in the transcript.
type TranscriptItem struct {
	Role       string // "user", "assistant", "system", "tool", "thought"
	Content    string
	ToolIcon   string // "○", "◉", "●", "✕"
	ToolName   string // e.g. "read_file"
	ToolArg    string // e.g. "internal/config/config.go"
	ToolOutput string // tool execution output or status summary
}

// SmartWrapLine wraps a single string on whitespace boundaries at max_width.
// Retained specifically for cursor-sentinel (\x00) awareness in input prompt rendering
// where byte/rune indices must not be broken or shifted across arbitrary breakpoints.
// For general presentation text without cursor sentinels, view.WrapText (lipgloss.Wrap) is used.
func SmartWrapLine(line string, maxWidth int) []string {
	if maxWidth < 10 {
		maxWidth = 10
	}
	if line == "" {
		return []string{""}
	}

	var result []string
	var current strings.Builder
	currentLen := 0

	words := splitWithSpaces(line)

	for _, word := range words {
		wLen := lipgloss.Width(word)

		if currentLen+wLen <= maxWidth {
			current.WriteString(word)
			currentLen += wLen
		} else if wLen > maxWidth {
			if current.Len() > 0 {
				result = append(result, current.String())
				current.Reset()
				currentLen = 0
			}

			runes := []rune(word)
			for len(runes) > 0 {
				take := maxWidth
				if take > len(runes) {
					take = len(runes)
				}
				chunk := string(runes[:take])
				runes = runes[take:]
				if len(runes) == 0 {
					current.WriteString(chunk)
					currentLen = lipgloss.Width(chunk)
				} else {
					result = append(result, chunk)
				}
			}
		} else {
			if current.Len() > 0 {
				result = append(result, strings.TrimRight(current.String(), " "))
				current.Reset()
			}
			trimmedStart := strings.TrimLeft(word, " ")
			current.WriteString(trimmedStart)
			currentLen = lipgloss.Width(trimmedStart)
		}
	}

	if current.Len() > 0 {
		result = append(result, current.String())
	}

	if len(result) == 0 {
		return []string{""}
	}
	return result
}

func splitWithSpaces(s string) []string {
	var words []string
	var cur strings.Builder

	for _, r := range s {
		cur.WriteRune(r)
		if unicode.IsSpace(r) {
			words = append(words, cur.String())
			cur.Reset()
		}
	}
	if cur.Len() > 0 {
		words = append(words, cur.String())
	}
	return words
}

func renderSingleItem(item TranscriptItem, width int, animFrame int) string {
	wrapWidth := width - 4
	if wrapWidth < 10 {
		wrapWidth = 10
	}

	assistantWrapWidth := wrapWidth
	if assistantWrapWidth > 100 {
		assistantWrapWidth = 100
	}

	switch item.Role {
	case "user":
		bgCol := lipgloss.Color(ColorUserMessageBG)
		userStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorTextWhite)).
			Width(width)

		pointerStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorUserChevron))
		pointer := pointerStyle.Render(GlyphPrompt)
		pointerPad := lipgloss.NewStyle().
			Background(bgCol).
			Render(GlyphPromptPad)

		textSpanStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorTextWhite))

		var wrappedUserLines []string
		for lineIdx, logicalLine := range strings.Split(item.Content, "\n") {
			subLines := SmartWrapLine(logicalLine, width-2)
			for subIdx, sLine := range subLines {
				styledLine := textSpanStyle.Render(sLine)
				if lineIdx == 0 && subIdx == 0 {
					wrappedUserLines = append(wrappedUserLines, pointer+styledLine)
				} else {
					wrappedUserLines = append(wrappedUserLines, pointerPad+styledLine)
				}
			}
		}
		return userStyle.Render(strings.Join(wrappedUserLines, "\n")) + "\n"

	case "bash":
		bgCol := lipgloss.Color(ColorUserMessageBG)
		userStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorTextWhite)).
			Width(width)

		pointerStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorUserChevron))
		pointer := pointerStyle.Render("! ")
		pointerPad := lipgloss.NewStyle().
			Background(bgCol).
			Render(GlyphPromptPad)

		textSpanStyle := lipgloss.NewStyle().
			Background(bgCol).
			Foreground(lipgloss.Color(ColorTextWhite))

		var wrappedBashLines []string
		for lineIdx, logicalLine := range strings.Split(item.Content, "\n") {
			subLines := SmartWrapLine(logicalLine, width-2)
			for subIdx, sLine := range subLines {
				styledLine := textSpanStyle.Render(sLine)
				if lineIdx == 0 && subIdx == 0 {
					wrappedBashLines = append(wrappedBashLines, pointer+styledLine)
				} else {
					wrappedBashLines = append(wrappedBashLines, pointerPad+styledLine)
				}
			}
		}
		res := userStyle.Render(strings.Join(wrappedBashLines, "\n"))

		if item.ToolOutput != "" {
			lines := strings.Split(strings.TrimRight(item.ToolOutput, "\r\n"), "\n")
			elbow := StyleMuted.Render("  " + GlyphTreeElbow)
			indent := StyleMuted.Render("    ")
			var outLines []string
			for i, outLine := range lines {
				prefix := elbow
				if i > 0 {
					prefix = indent
				}
				outLines = append(outLines, prefix+StyleDim.Render(outLine))
			}
			res += "\n" + strings.Join(outLines, "\n")
		}
		return res + "\n"

	case "thought":
		thoughtStyle := lipgloss.NewStyle().
			Foreground(lipgloss.Color(ColorSubtle)).
			Italic(true).
			Width(assistantWrapWidth)

		if mdOut, err := renderMarkdownCached(item.Content, assistantWrapWidth); err == nil {
			cleanMd := stripANSI(mdOut)
			trimmed := strings.Trim(cleanMd, "\r\n")
			return thoughtStyle.Render(trimmed) + "\n"
		}

		var wrappedLines []string
		trimmedContent := strings.Trim(item.Content, "\r\n")
		for _, logicalLine := range strings.Split(trimmedContent, "\n") {
			wrappedLines = append(wrappedLines, SmartWrapLine(logicalLine, assistantWrapWidth)...)
		}
		return thoughtStyle.Render(strings.Join(wrappedLines, "\n")) + "\n"

	case "assistant":
		bullet := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextWhite)).Render(GlyphBullet)
		bulletPad := GlyphPromptPad

		if mdOut, err := renderMarkdownCached(item.Content, assistantWrapWidth-2); err == nil {
			trimmedOut := strings.Trim(mdOut, "\r\n")
			lines := strings.Split(trimmedOut, "\n")
			if len(lines) > 0 {
				lines[0] = bullet + lines[0]
				for i := 1; i < len(lines); i++ {
					if lines[i] != "" {
						lines[i] = bulletPad + lines[i]
					}
				}
			}
			return strings.Join(lines, "\n") + "\n"
		}

		var wrappedLines []string
		trimmedContent := strings.Trim(item.Content, "\r\n")
		for _, logicalLine := range strings.Split(trimmedContent, "\n") {
			wrappedLines = append(wrappedLines, SmartWrapLine(logicalLine, assistantWrapWidth-2)...)
		}
		if len(wrappedLines) > 0 {
			wrappedLines[0] = bullet + StyleText.Render(wrappedLines[0])
			for i := 1; i < len(wrappedLines); i++ {
				if wrappedLines[i] != "" {
					wrappedLines[i] = bulletPad + StyleText.Render(wrappedLines[i])
				}
			}
		}
		return strings.Join(wrappedLines, "\n") + "\n"

	case "tool":
		icon := item.ToolIcon
		if icon == "" {
			icon = GlyphDone
		}

		var bulletStyle lipgloss.Style
		switch icon {
		case GlyphError:
			bulletStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBulletError))
		case GlyphDone:
			bulletStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(ColorBulletSuccess))
		default:
			beepColors := []string{"#7BA5DA", "#A3C4F3", "#D2E2FB", "#FFFFFF", "#D2E2FB", "#A3C4F3"}
			beepColor := beepColors[(animFrame/3)%len(beepColors)]
			bulletStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(beepColor))
		}

		bullet := bulletStyle.Render(GlyphBullet)

		name := formatToolDisplayName(item.ToolName)
		arg := item.ToolArg
		if name == "" {
			if idx := strings.IndexByte(item.Content, '('); idx != -1 && strings.HasSuffix(item.Content, ")") {
				name = item.Content[:idx]
				arg = item.Content[idx+1 : len(item.Content)-1]
			} else {
				name = item.Content
			}
		}

		nameStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextWhite))
		dimParenStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextDim))
		argStyle := lipgloss.NewStyle().Foreground(lipgloss.Color(ColorTextDim))

		line := bullet + nameStyle.Render(name) + dimParenStyle.Render("(") + argStyle.Render(arg) + dimParenStyle.Render(")")

		outputSummary := item.ToolOutput
		if icon == GlyphPending || icon == "◉" {
			outputSummary = "Running..."
		}

		if outputSummary != "" {
			elbow := StyleMuted.Render("  " + GlyphTreeElbow)
			outText := StyleDim.Render(outputSummary)
			line += "\n" + elbow + outText
		}
		return line

	case "system":
		var wrapped []string
		for _, l := range strings.Split(item.Content, "\n") {
			wrapped = append(wrapped, SmartWrapLine(l, wrapWidth)...)
		}
		return StyleDim.Render(strings.Join(wrapped, "\n")) + "\n"
	}

	return ""
}

func formatToolDisplayName(name string) string {
	switch strings.ToLower(name) {
	case "run_command":
		return "Bash"
	case "write_file":
		return "Write"
	case "edit_file":
		return "Update"
	case "read_file":
		return "Read"
	case "list_dir":
		return "List"
	case "search_text":
		return "Search"
	case "find":
		return "Find"
	case "web_fetch":
		return "Web"
	case "schedule":
		return "Schedule"
	default:
		if len(name) > 0 {
			return strings.ToUpper(name[:1]) + name[1:]
		}
		return name
	}
}

// PrimaryArg extracts the single most relevant argument for the compact log-line form.
// e.g. path for file tools, url for web_fetch, command for run_command.
func PrimaryArg(jsonArgs string) string {
	var obj map[string]any
	if err := json.Unmarshal([]byte(jsonArgs), &obj); err == nil && len(obj) > 0 {
		primaryKeys := []string{
			"path",
			"file_path",
			"target_file",
			"command",
			"url",
			"query",
			"pattern",
			"name",
			"prompt",
		}
		for _, key := range primaryKeys {
			if v, ok := obj[key]; ok {
				if s, ok := v.(string); ok {
					return firstLine(s)
				}
				b, _ := json.Marshal(v)
				return string(b)
			}
		}
		for _, v := range obj {
			if s, ok := v.(string); ok {
				return firstLine(s)
			}
			b, _ := json.Marshal(v)
			return string(b)
		}
	}

	trimmed := strings.TrimSpace(jsonArgs)
	oneLine := firstLine(trimmed)
	if len(oneLine) > 36 {
		return oneLine[:35] + "…"
	}
	return oneLine
}

func firstLine(s string) string {
	parts := strings.SplitN(s, "\n", 2)
	return parts[0]
}

package view

import (
	"strings"
	"sync"
)

// TranscriptCache retains rendered items incrementally by index and width.
type TranscriptCache struct {
	mu          sync.RWMutex
	width       int
	staticLines []string
	stableCount int
}

var defaultTranscriptCache = &TranscriptCache{}

// Reset clears the rendered item cache.
func (tc *TranscriptCache) Reset() {
	tc.mu.Lock()
	defer tc.mu.Unlock()
	tc.staticLines = nil
	tc.stableCount = 0
}

// RenderTranscriptIncremental renders the static prefix once and appends only active/new items.
// Optimized in Phase 12:
//  1. Avoids re-scanning the entire list for stableLen on every frame.
//  2. Stores stable rendered items in a slice of pre-rendered lines rather than repeatedly copying
//     and concatenating one growing giant string.
//  3. Renders only truly dynamic/active items during streaming turns.
func RenderTranscriptIncremental(items []TranscriptItem, width int, animFrame int, staticPrefix string, staticLen int) (string, string, int) {
	if width < 20 {
		width = 80
	}
	if len(items) == 0 {
		return "", "", 0
	}

	tc := defaultTranscriptCache
	tc.mu.Lock()
	defer tc.mu.Unlock()

	if tc.width != width {
		tc.width = width
		tc.staticLines = nil
		tc.stableCount = 0
	}

	lastIdx := len(items) - 1
	var stableLen int
	for i := 0; i < lastIdx; i++ {
		if items[i].Role == "tool" && items[i].ToolIcon != GlyphDone && items[i].ToolIcon != GlyphError {
			break
		}
		stableLen = i + 1
	}

	if stableLen < tc.stableCount {
		// Transcript reset or truncated
		tc.staticLines = nil
		tc.stableCount = 0
	}

	// Incrementally append new finalized items only
	if stableLen > tc.stableCount {
		for i := tc.stableCount; i < stableLen; i++ {
			tc.staticLines = append(tc.staticLines, renderSingleItem(items[i], width, animFrame))
		}
		tc.stableCount = stableLen
	}

	// Join static items and dynamic items
	dynamicCount := len(items) - tc.stableCount
	resultParts := make([]string, 0, len(tc.staticLines)+dynamicCount)
	resultParts = append(resultParts, tc.staticLines...)

	for i := tc.stableCount; i < len(items); i++ {
		resultParts = append(resultParts, renderSingleItem(items[i], width, animFrame))
	}

	cachedPrefix := ""
	if len(tc.staticLines) > 0 {
		cachedPrefix = strings.Join(tc.staticLines, "\n")
	}

	return strings.Join(resultParts, "\n"), cachedPrefix, tc.stableCount
}

package view

import (
	"strings"

	"charm.land/lipgloss/v2"
)

// WrapText wraps text cleanly using lipgloss.Wrap.
// Empty string returns []string{""} for predictable line indexing.
func WrapText(text string, maxWidth int) []string {
	if maxWidth < 10 {
		maxWidth = 10
	}
	if text == "" {
		return []string{""}
	}
	wrapped := lipgloss.Wrap(text, maxWidth, "")
	if wrapped == "" {
		return []string{""}
	}
	return strings.Split(wrapped, "\n")
}

package view_test

import (
	"strings"
	"testing"

	"charm.land/lipgloss/v2"
	"github.com/sapirrior/delta/internal/tui/view"
)

func TestWrapTextAndLipgloss(t *testing.T) {
	testCases := []struct {
		name     string
		input    string
		maxWidth int
	}{
		{
			name:     "empty string",
			input:    "",
			maxWidth: 80,
		},
		{
			name:     "normal words short",
			input:    "hello world foo bar",
			maxWidth: 40,
		},
		{
			name:     "repeated whitespace",
			input:    "hello    world   multiple     spaces",
			maxWidth: 20,
		},
		{
			name:     "long unbroken tokens",
			input:    "abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ",
			maxWidth: 15,
		},
		{
			name:     "unicode text",
			input:    "Hello 世界！这是一个测试字符串，包含中文字符和 emoji 🎉🚀。",
			maxWidth: 20,
		},
		{
			name:     "embedded newlines",
			input:    "Line 1\nLine 2\nLine 3 with more text to wrap",
			maxWidth: 15,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			lines := view.WrapText(tc.input, tc.maxWidth)
			if tc.input == "" {
				if len(lines) != 1 || lines[0] != "" {
					t.Fatalf("expected [\"\"], got %#v", lines)
				}
				return
			}
			for _, line := range lines {
				w := lipgloss.Width(line)
				if w > tc.maxWidth {
					t.Errorf("line exceeds maxWidth %d (got %d): %q", tc.maxWidth, w, line)
				}
			}
		})
	}
}

func TestCursorAwareSmartWrapLine(t *testing.T) {
	input := "func main() {\x00\n\tfmt.Println(\"hi\")\n}"
	wrapped := view.SmartWrapLine(input, 30)
	found := false
	for _, l := range wrapped {
		if strings.Contains(l, "\x00") {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected cursor sentinel \\x00 preserved in wrapped lines, got %#v", wrapped)
	}
}

package workspace

import (
	"os"
	"path/filepath"
	"strings"
)

// MatchFiles finds up to maxResults relative file paths matching the query prefix.
func MatchFiles(root, query string, maxResults int) []string {
	if maxResults <= 0 {
		maxResults = 8
	}
	cleanRoot := filepath.Clean(root)
	q := strings.TrimPrefix(query, "@")
	qLower := strings.ToLower(q)

	var matches []string

	_ = filepath.Walk(cleanRoot, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		// Skip hidden dirs such as .git
		if info.IsDir() {
			base := filepath.Base(path)
			if strings.HasPrefix(base, ".") && path != cleanRoot {
				return filepath.SkipDir
			}
			return nil
		}

		rel, err := filepath.Rel(cleanRoot, path)
		if err != nil {
			return nil
		}

		relLower := strings.ToLower(rel)
		if strings.Contains(relLower, qLower) {
			matches = append(matches, rel)
			if len(matches) >= maxResults {
				return filepath.SkipAll
			}
		}
		return nil
	})

	return matches
}

package workspace_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/sapirrior/delta/internal/workspace"
)

func TestMatchFiles(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_match_files_*")
	if err != nil {
		t.Fatalf("failed creating temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	_ = os.WriteFile(filepath.Join(tempDir, "main.go"), []byte("package main"), 0644)
	_ = os.MkdirAll(filepath.Join(tempDir, "internal", "tui"), 0755)
	_ = os.WriteFile(filepath.Join(tempDir, "internal", "tui", "model.go"), []byte("package tui"), 0644)
	_ = os.WriteFile(filepath.Join(tempDir, "README.md"), []byte("# Delta"), 0644)

	matches := workspace.MatchFiles(tempDir, "@model", 5)
	if len(matches) != 1 || matches[0] != filepath.Join("internal", "tui", "model.go") {
		t.Errorf("expected internal/tui/model.go, got: %v", matches)
	}

	matchesAll := workspace.MatchFiles(tempDir, "@", 5)
	if len(matchesAll) < 3 {
		t.Errorf("expected at least 3 files for empty query, got: %v", matchesAll)
	}
}

package workspace

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// FormatFileContext reads a file safely and formats it in structured markdown
// for inclusion alongside the user prompt.
func FormatFileContext(root, relPath string) (string, error) {
	safe, err := SafePath(root, relPath)
	if err != nil {
		return "", err
	}

	data, err := os.ReadFile(safe)
	if err != nil {
		return "", err
	}

	cleanRel, err := filepath.Rel(root, safe)
	if err != nil {
		cleanRel = relPath
	}

	ext := strings.TrimPrefix(filepath.Ext(cleanRel), ".")
	return fmt.Sprintf("\n\n<file path=%q>\n```%s\n%s\n```\n</file>\n", cleanRel, ext, string(data)), nil
}

