	}
	defer os.RemoveAll(tempDir)

	filePath := filepath.Join(tempDir, "sample.txt")
	_ = os.WriteFile(filePath, []byte("line 1\nline 2"), 0644)

	formatted, err := workspace.FormatFileContext(tempDir, "sample.txt")
	if err != nil {
		t.Fatalf("failed formatting file context: %v", err)
	}

	if !strings.Contains(formatted, "<file path=\"sample.txt\">") {
