	}
	if !strings.Contains(formatted, "line 1\nline 2") {
		t.Errorf("expected file content, got: %s", formatted)
	}
}

package workspace

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

var (
	ErrEscapesRoot     = errors.New("path escapes sandbox root")
	ErrSymlinkRejected = errors.New("symlink traversal rejected")
)

// SafePath safely resolves a user or tool path relative to the workspace root.
// Invariant (AGENTS.md & Finding 1.17):
// 1. All filesystem access goes through SafePath. No direct filepath.Join on user input.
// 2. Reject paths escaping root or pointing to symlinks that escape root.
// 3. Check every existing ancestor directory for symlinks escaping root, even if final leaf doesn't exist yet.
func SafePath(root string, userPath string) (string, error) {
	cleanRoot := filepath.Clean(root)

	// Normalize userPath by stripping leading slashes so it's treated as relative to root
	cleanedUser := filepath.Clean(userPath)
	if filepath.IsAbs(cleanedUser) {
		vol := filepath.VolumeName(cleanedUser)
		cleanedUser = strings.TrimPrefix(cleanedUser, vol)
		cleanedUser = strings.TrimLeft(cleanedUser, string(filepath.Separator))
	}

	// Check for leading parent traversal before joining
	parts := strings.Split(cleanedUser, string(filepath.Separator))
	depth := 0
	for _, part := range parts {
		if part == ".." {
			depth--
			if depth < 0 {
				return "", fmt.Errorf("%w: %s", ErrEscapesRoot, userPath)
			}
		} else if part != "." && part != "" {
			depth++
		}
	}

	resolved := filepath.Join(cleanRoot, cleanedUser)

	evalRoot, err := filepath.EvalSymlinks(cleanRoot)
	if err != nil {
		evalRoot = cleanRoot
	}

	// Check all existing ancestors to catch symlink escapes even for non-existent final leaves
	cur := resolved
	for {
		if _, err := os.Lstat(cur); err == nil {
			// Found the closest existing path component; evaluate symlinks
			target, err := filepath.EvalSymlinks(cur)
			if err != nil {
				return "", fmt.Errorf("%w: failed resolving symlink %s: %v", ErrSymlinkRejected, cur, err)
			}
			rel, err := filepath.Rel(evalRoot, target)
			if err != nil || strings.HasPrefix(rel, "..") {
				return "", fmt.Errorf("%w: target escapes sandbox root: %s", ErrSymlinkRejected, userPath)
			}
			break
		}

		parent := filepath.Dir(cur)
		if parent == cur || parent == cleanRoot {
			break
		}
		cur = parent
	}

	// Final check on resolved if it exists directly
	fi, err := os.Lstat(resolved)
	if err == nil && fi.Mode()&os.ModeSymlink != 0 {
		target, err := filepath.EvalSymlinks(resolved)
		if err != nil {
			return "", fmt.Errorf("%w: failed resolving symlink %s: %v", ErrSymlinkRejected, userPath, err)
		}
		rel, err := filepath.Rel(evalRoot, target)
		if err != nil || strings.HasPrefix(rel, "..") {
			return "", fmt.Errorf("%w: target escapes sandbox root: %s", ErrSymlinkRejected, userPath)
		}
	}

	return resolved, nil
}

package workspace_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/sapirrior/delta/internal/workspace"
)

func TestSafePath(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "delta_workspace_*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	// 1. Valid relative path
	p, err := workspace.SafePath(tempDir, "src/main.go")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if p != filepath.Join(tempDir, "src/main.go") {
		t.Errorf("expected %s, got %s", filepath.Join(tempDir, "src/main.go"), p)
	}

	// 2. Normal internal traversal
	p, err = workspace.SafePath(tempDir, "src/foo/../bar/main.go")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if p != filepath.Join(tempDir, "src/bar/main.go") {
		t.Errorf("expected %s, got %s", filepath.Join(tempDir, "src/bar/main.go"), p)
	}

	// 3. Traversal escaping root
	if _, err := workspace.SafePath(tempDir, "../secret.txt"); err == nil {
		t.Errorf("expected error escaping root, got nil")
	}
	if _, err := workspace.SafePath(tempDir, "a/../../secret.txt"); err == nil {
		t.Errorf("expected error escaping root, got nil")
	}

	// 4. Existing symlink escaping root
	secretFile := filepath.Join(os.TempDir(), "outside_secret.txt")
	_ = os.WriteFile(secretFile, []byte("secret"), 0o644)
	defer os.Remove(secretFile)

	symlinkPath := filepath.Join(tempDir, "link_to_secret")
	if err := os.Symlink(secretFile, symlinkPath); err == nil {
		if _, err := workspace.SafePath(tempDir, "link_to_secret"); err == nil {
			t.Errorf("expected symlink escape error, got nil")
		}
	}

	// 5. Ancestor symlink escape for non-existent leaf (Finding 1.17)
	outsideDir, err := os.MkdirTemp("", "delta_outside_*")
	if err != nil {
		t.Fatalf("failed creating outside dir: %v", err)
	}
	defer os.RemoveAll(outsideDir)

	linkDir := filepath.Join(tempDir, "link_to_outside_dir")
	if err := os.Symlink(outsideDir, linkDir); err == nil {
		// Target leaf file does not exist yet!
		if _, err := workspace.SafePath(tempDir, "link_to_outside_dir/new_file.txt"); err == nil {
			t.Errorf("expected ancestor symlink escape error for non-existent file, got nil")
		}
	}
}

package workspace

import (
	"os"
	"path/filepath"
	"strings"
)

// ExtractFileMentions scans text for @rel/path/to/file patterns and returns matched file paths.
func ExtractFileMentions(root, text string) ([]string, string) {
	words := strings.Fields(text)
	var foundFiles []string
	var cleanedWords []string

	for _, w := range words {
		if strings.HasPrefix(w, "@") && len(w) > 1 {
			candidate := strings.TrimPrefix(w, "@")
			candidate = strings.TrimRight(candidate, ",.;:!?")
			safe, err := SafePath(root, candidate)
			if err == nil {
				if fi, err := os.Stat(safe); err == nil && !fi.IsDir() {
					if rel, relErr := filepath.Rel(root, safe); relErr == nil {
						foundFiles = append(foundFiles, rel)
						cleanedWords = append(cleanedWords, w)
						continue
					}
				}
			}
		}
		cleanedWords = append(cleanedWords, w)
	}

	return foundFiles, strings.Join(cleanedWords, " ")
}

// BuildPromptWithFiles attaches structured file content blocks for all specified file paths.
func BuildPromptWithFiles(root, prompt string, files []string) string {
	if len(files) == 0 {
		return prompt
	}
	var sb strings.Builder
	sb.WriteString(prompt)
	for _, f := range files {
		block, err := FormatFileContext(root, f)
		if err == nil {
			sb.WriteString(block)
		}
	}
	return sb.String()
}
